-- src/Assets/Theme.lua
FluxRegistry["Flux/Assets/Theme"] = function(require)
	--[[
		Assets/Theme — the token tables. Pure data: no instances, no game services.

		Two things are separated deliberately:
		  * `colors` are named semantic roles, not hexes scattered through components;
		  * `metrics` and `fonts` travel with them so a theme change can restyle spacing too.

		The default preset is measured against the reference screenshot: near-black backdrop,
		panel fills one step lighter, hairline borders, low-contrast secondary text, and the
		coral accent reserved for active state rather than decoration.
	]]

	local Color3 = Color3

	local Theme = {}

	Theme.presets = {
		Dark = {
			colors = {
				Background = Color3.fromRGB(16, 16, 20),
				WindowBackground = Color3.fromRGB(18, 18, 24),
				Panel = Color3.fromRGB(24, 24, 30),
				PanelSecondary = Color3.fromRGB(29, 29, 38),
				Field = Color3.fromRGB(31, 31, 38),
				Chip = Color3.fromRGB(33, 33, 40),
				Hover = Color3.fromRGB(36, 36, 46),
				Selection = Color3.fromRGB(40, 40, 52),
				Scrim = Color3.fromRGB(8, 8, 12),

				BorderPrimary = Color3.fromRGB(37, 37, 48),
				BorderSecondary = Color3.fromRGB(48, 48, 59),

				TextPrimary = Color3.fromRGB(231, 231, 237),
				TextSecondary = Color3.fromRGB(153, 153, 168),
				TextMuted = Color3.fromRGB(104, 104, 120),

				BrandPrimary = Color3.fromRGB(183, 106, 255),
				BrandSecondary = Color3.fromRGB(140, 82, 255),

				Accent = Color3.fromRGB(255, 79, 104),
				AccentHover = Color3.fromRGB(255, 102, 122),
				AccentSoft = Color3.fromRGB(72, 30, 40),

				Success = Color3.fromRGB(72, 199, 116),
				Warning = Color3.fromRGB(240, 173, 78),
				Error = Color3.fromRGB(255, 92, 92),
				Info = Color3.fromRGB(96, 165, 250),
			},
			metrics = {
				RadiusWindow = 12,
				RadiusPanel = 10,
				RadiusField = 8,
				RadiusChip = 6,
				RadiusPill = 24,
				HeaderHeight = 72,
				NavHeight = 52,
				FooterHeight = 40,
				RowHeight = 30,
				GroupPadding = 16,
				GroupGap = 14,
				ContentPadding = 18,
				ColumnGap = 16,
				StrokeThickness = 1,
			},
			fonts = {
				Title = Enum.Font.GothamMedium,
				Body = Enum.Font.Gotham,
				Subtitle = Enum.Font.GothamMedium,
				Mono = Enum.Font.Code,
			},
		},
	}

	--- A preset is the Dark table with one role group recoloured, so switching to Purple does
	--- not silently reset spacing or fonts as a side effect.
	local function tinted(name: string, overrides: {[string]: Color3}): {[string]: any}
		local base = Theme.presets.Dark
		local colors = {}
		for key, value in pairs(base.colors) do
			colors[key] = value
		end
		for key, value in pairs(overrides) do
			colors[key] = value
		end

		return {
			colors = colors,
			metrics = base.metrics,
			fonts = base.fonts,
			name = name,
		}
	end

	Theme.presets.Purple = tinted("Purple", {
		Accent = Color3.fromRGB(150, 96, 255),
		AccentHover = Color3.fromRGB(170, 120, 255),
		AccentSoft = Color3.fromRGB(46, 32, 74),
		BrandPrimary = Color3.fromRGB(183, 106, 255),
		Selection = Color3.fromRGB(44, 36, 62),
	})

	Theme.presets.Red = tinted("Red", {
		Accent = Color3.fromRGB(232, 62, 74),
		AccentHover = Color3.fromRGB(246, 92, 102),
		AccentSoft = Color3.fromRGB(62, 26, 32),
		BrandPrimary = Color3.fromRGB(232, 62, 74),
		Selection = Color3.fromRGB(56, 32, 38),
	})

	Theme.presets.Blue = tinted("Blue", {
		Accent = Color3.fromRGB(74, 138, 255),
		AccentHover = Color3.fromRGB(104, 160, 255),
		AccentSoft = Color3.fromRGB(30, 44, 74),
		BrandPrimary = Color3.fromRGB(96, 165, 250),
		Selection = Color3.fromRGB(34, 46, 70),
	})

	Theme.presets.Custom = tinted("Custom", {})

	Theme.defaultPreset = "Dark"

	--- Roles a component may bind to. Listed so ThemeManager can validate a typo at the call
	--- site instead of painting black and leaving the author to guess which token missed.
	Theme.colorRoles = {
		"Background",
		"WindowBackground",
		"Panel",
		"PanelSecondary",
		"Field",
		"Chip",
		"Hover",
		"Selection",
		"Scrim",
		"BorderPrimary",
		"BorderSecondary",
		"TextPrimary",
		"TextSecondary",
		"TextMuted",
		"BrandPrimary",
		"BrandSecondary",
		"Accent",
		"AccentHover",
		"AccentSoft",
		"Success",
		"Warning",
		"Error",
		"Info",
	}

	Theme.metricRoles = {
		"RadiusWindow",
		"RadiusPanel",
		"RadiusField",
		"RadiusChip",
		"RadiusPill",
		"HeaderHeight",
		"NavHeight",
		"FooterHeight",
		"RowHeight",
		"GroupPadding",
		"GroupGap",
		"ContentPadding",
		"ColumnGap",
		"StrokeThickness",
	}

	return Theme
end

-- src/Components/Button.lua
FluxRegistry["Flux/Components/Button"] = function(require)
	--[[
		Components/Button — an action row.
	
		A button spans the card instead of sitting beside a label, because that is what the reference
		design does with the two actions at the bottom of each section. Variant picks the palette role,
		never a hex, so `SetTheme` moves a danger button along with everything else.
	
		Clicks are reported through a `Clicked` signal as well as the callback: a host that wires three
		buttons to one handler should not have to write the same closure three times.
	]]
	
	local Element = require("Flux/Core/Element")
	local Instance = require("Flux/Utilities/Instance")
	local Guard = require("Flux/Utilities/Guard")
	local Signal = require("Flux/Utilities/Signal")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	local AnimationManager = require("Flux/Systems/AnimationManager")
	local TooltipManager = require("Flux/Systems/TooltipManager")
	
	local Button = {}
	
	local VARIANTS = {
		accent = { Fill = "Accent", Text = "TextPrimary", Radius = "RadiusField" },
		soft = { Fill = "PanelSecondary", Text = "TextPrimary", Radius = "RadiusField" },
		outline = { Fill = "Field", Text = "TextSecondary", Radius = "RadiusField" },
		danger = { Fill = "Error", Text = "TextPrimary", Radius = "RadiusField" },
		success = { Fill = "Success", Text = "TextPrimary", Radius = "RadiusField" },
	}
	
	function Button.new(group: any, options: {[string]: any}?)
		options = Element.options(options, {
			Name = "Button",
			Text = nil,
			Desc = nil,
			Icon = nil,
			Variant = "accent",
			Disabled = false,
			Callback = nil,
			Tooltip = nil,
			Height = 34,
		})
	
		local variant = VARIANTS[options.Variant] or VARIANTS.accent
		local label = options.Text or options.Name
		local maid = group.Maid
	
		local root = Instance.new("TextButton", group.Content, {
			Name = "Button_" .. tostring(label),
			Text = "",
			AutoButtonColor = false,
			BackgroundColor3 = ThemeManager.color(variant.Fill),
			Size = UDim2.new(1, 0, 0, options.Height),
			LayoutOrder = group:RowCount() + 1,
			BorderSizePixel = 0,
			ZIndex = 5,
		})
		maid:giveFunction(function()
			root:Destroy()
		end)
		maid:give(ThemeManager.bind(root, "BackgroundColor3", variant.Fill))
		Element.round(maid, root, variant.Radius)
	
		local content = Instance.new("Frame", root, {
			Name = "Content",
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			BorderSizePixel = 0,
			ZIndex = 6,
		})
		maid:giveFunction(function()
			content:Destroy()
		end)
		Instance.new("UIListLayout", content, {
			FillDirection = Enum.FillDirection.Horizontal,
			HorizontalAlignment = Enum.HorizontalAlignment.Center,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 7),
		})
	
		if options.Icon ~= nil then
			Element.icon(maid, content, options.Icon, {
				Role = variant.Text,
				Size = UDim2.fromOffset(14, 14),
				ZIndex = 6,
			})
		end
	
		local text = Element.label(maid, content, "Text", {
			Text = tostring(label),
			Role = variant.Text,
			Font = "Title",
			TextSize = 13,
			Alignment = Enum.TextXAlignment.Center,
			Size = UDim2.new(1, options.Icon ~= nil and -30 or 0, 1, 0),
			AutoWidth = true,
			ZIndex = 6,
		})
	
		local self = {
			Instance = root,
			Title = label,
			Clicked = Signal.new(),
			_callback = options.Callback,
			_disabled = options.Disabled == true,
			Destroyed = false,
		}
	
		local function refreshDisabled()
			-- Transparency on the whole surface, rather than recolouring two children: a disabled
			-- button must look dimmed identically in every variant, including a custom palette.
			root.BackgroundTransparency = self._disabled and 0.55 or 0
			for _, child in ipairs(content:GetChildren()) do
				Guard.set(child, "TextTransparency", self._disabled and 0.35 or 0)
			end
		end
	
		local function fire(source: string)
			if self._disabled then
				return false
			end
			self.Clicked:Dispatch(source)
			if self._callback ~= nil then
				local ok, err = pcall(self._callback)
				if not ok then
					warn("[Flux] button '" .. tostring(label) .. "': " .. tostring(err))
				end
			end
			return true
		end
	
		root.MouseButton1Click:Connect(function()
			if self._disabled then
				return
			end
			-- A press is confirmed by a small squash rather than the engine's own highlight, which is
			-- tuned for saturated buttons and invisible on a dark theme.
			AnimationManager.to(root, { Size = UDim2.new(1, 0, 0, options.Height - 2) }, {
				Duration = 0.06,
				Easing = "outQuad",
			})
			task.delay(0.07, function()
				if not self.Destroyed then
					AnimationManager.to(root, { Size = UDim2.new(1, 0, 0, options.Height) }, {
						Duration = 0.1,
						Easing = "outQuad",
					})
				end
			end)
			fire("click")
		end)
	
		self.Click = function()
			return fire("script")
		end
	
		self.SetCallback = function(a: any, b: any)
			self._callback = Element.recv(self, a, b)
			return self
		end
	
		self.SetText = function(a: any, b: any)
			local value = tostring(Element.recv(self, a, b))
			self.Title = value
			root.Name = "Button_" .. tostring(value)
			local inner = content:FindFirstChild("Text")
			if inner ~= nil then
				inner.Text = value
			end
			return self
		end
	
		self.SetIcon = function(a: any, b: any)
			local glyph = tostring(Element.recv(self, a, b))
			local existing = content:FindFirstChildOfClass("ImageLabel") or content:FindFirstChildOfClass("Frame")
			if existing ~= nil then
				existing:Destroy()
			end
			local icon = Element.icon(maid, content, glyph, {
				Role = variant.Text,
				Size = UDim2.fromOffset(14, 14),
				ZIndex = 6,
			})
			icon.instance.LayoutOrder = -1
			return self
		end
	
		self.SetDisabled = function(a: any, b: any)
			self._disabled = Element.recv(self, a, b) == true
			refreshDisabled()
			return self
		end
	
		self.IsDisabled = function(): boolean
			return self._disabled
		end
	
		self.SetVisible = function(a: any, b: any)
			root.Visible = Element.recv(self, a, b) == true
			return self
		end
	
		self.OnFilter = function(a: any, b: any)
			root.Visible = Element.recv(self, a, b) == true
		end
	
		self.Destroy = function()
			if self.Destroyed then
				return
			end
			self.Destroyed = true
			AnimationManager.cancel(root)
			self.Clicked:Destroy()
			Element.releaseSearch(group, self)
			root:Destroy()
		end
	
		refreshDisabled()
		if type(options.Tooltip) == "string" and options.Tooltip ~= "" then
			TooltipManager.attach(root, options.Tooltip)
		end
	
		self.SearchId = Element.searchable(group, self, tostring(label), options.Desc)
		return self
	end
	
	return Button
end

-- src/Components/Checkbox.lua
FluxRegistry["Flux/Components/Checkbox"] = function(require)
	--[[
		Components/Checkbox — a square check row.
	
		The pill `Toggle` says "a live feature is running"; a checkbox reads as a configuration
		mark, and hosts want both shapes in the same page. Same anatomy as the toggle, different
		artwork: a small radius-chip box with the `check` glyph inside, accent border and fill when
		on, quiet field fill when off. No new chrome, no new tokens.
	
		The state machine is the toggle's verbatim, because it is the contract every row follows:
		the value lives on the widget (so `Set` is safe before the tab mounts), `Set` is silent to
		the callback and only a user click commits, the store is staged through `Element.pushConfig`
		only on a real change, and `Destroy` is idempotent.
	]]
	
	local Element = require("Flux/Core/Element")
	local Instance = require("Flux/Utilities/Instance")
	local Guard = require("Flux/Utilities/Guard")
	local Signal = require("Flux/Utilities/Signal")
	local TooltipManager = require("Flux/Systems/TooltipManager")
	
	local Checkbox = {}
	
	local BOX = 18
	local GLYPH = 12
	
	function Checkbox.new(group: any, options: {[string]: any}?)
		options = Element.options(options, {
			Name = "Checkbox",
			Title = nil,
			Desc = nil,
			Default = false,
			Callback = nil,
			Flag = nil,
			Icon = nil,
		})
	
		local title = options.Title or options.Name
		local maid = group.Maid
		local row = Element.row(maid, group.Content, "Checkbox_" .. tostring(title), {
			Label = title,
			Desc = options.Desc,
			BodyWidth = BOX + 8,
			Order = group:RowCount() + 1,
		})
	
		local box = Element.panel(maid, row.Body, "Box", {
			Color = "Field",
			Radius = "RadiusChip",
			Size = UDim2.fromOffset(BOX, BOX),
			Stroke = "BorderSecondary",
			ZIndex = 6,
		})
	
		-- Element.panel bound the stroke to BorderSecondary for the resting state; tinting replaces
		-- that binding rather than writing over it, so a later theme swap keeps the active colour.
		local stroke = box:FindFirstChildOfClass("UIStroke")
	
		local glyph = Element.icon(maid, box, "check", {
			Size = UDim2.fromOffset(GLYPH, GLYPH),
			Position = UDim2.fromScale(0.5, 0.5),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Role = "Accent",
			ZIndex = 7,
		})
	
		if options.Icon ~= nil then
			Element.icon(maid, row.Body, options.Icon, {
				Role = "TextMuted",
				Size = UDim2.fromOffset(13, 13),
				LayoutOrder = -1,
				ZIndex = 6,
			})
		end
	
		local self = {
			Instance = row.Root,
			Title = title,
			Changed = Signal.new(),
			_value = options.Default == true,
			_callback = options.Callback,
			_maid = maid,
			_group = group,
			_flag = options.Flag,
			_row = row,
		}
	
		local function paint(value: boolean)
			-- Quiet fill, loud border: a fully accent box would outshine the row's own label.
			Element.tint(maid, box, "BackgroundColor3", value and "AccentSoft" or "Field")
			if stroke ~= nil then
				Element.tint(maid, stroke, "Color", value and "Accent" or "BorderSecondary")
			end
			glyph.instance.Visible = value
		end
	
		local function set(value: boolean, silent: boolean?)
			local on = value == true
			if self.Destroyed then
				return self
			end
			local changed = self._value ~= on
			self._value = on
	
			paint(on)
	
			if changed then
				Element.pushConfig(self._flag, on)
				self.Changed:Dispatch(on)
				if not silent and self._callback ~= nil then
					local ok, err = pcall(self._callback, on)
					if not ok then
						warn("[Flux] checkbox '" .. tostring(title) .. "': " .. tostring(err))
					end
				end
			end
			return self
		end
	
		local button = Instance.new("TextButton", row.Root, {
			Name = "HitArea",
			Text = "",
			AutoButtonColor = false,
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			ZIndex = 8,
			BorderSizePixel = 0,
		})
		maid:giveFunction(function()
			button:Destroy()
		end)
	
		button.MouseButton1Click:Connect(function()
			set(not self._value)
		end)
	
		-- The whole row is the target, not an 18px box: on a phone the small version is unusable.
		if type(options.Desc) == "string" and options.Desc ~= "" then
			TooltipManager.attach(button, options.Desc)
		end
	
		-- Every entry point below takes the (a, b) shape: a host calls `w:Set(x)` with a colon, which
		-- arrives as (self, x), while the library calls it plain. One shim reads the same either way,
		-- and Groupbox fires OnFilter the same plain way, so this is the library's own idiom.
		self.Set = function(a: any, b: any)
			local value = a
			if a == self then
				value = b
			end
			return set(value, true)
		end
	
		self.Toggle = function()
			return set(not self._value)
		end
	
		self.GetValue = function()
			return self._value
		end
	
		self.SetCallback = function(a: any, b: any)
			local fn = a
			if a == self then
				fn = b
			end
			self._callback = fn
			return self
		end
	
		self.SetTitle = function(a: any, b: any)
			local text = a
			if a == self then
				text = b
			end
			self.Title = tostring(text)
			row.Title.Text = self.Title
			return self
		end
	
		self.SetVisible = function(a: any, b: any)
			local visible = a
			if a == self then
				visible = b
			end
			row.Root.Visible = visible == true
			return self
		end
	
		self.OnFilter = function(a: any, b: any)
			local matched = a
			if a == self then
				matched = b
			end
			row.Root.Visible = matched == true
		end
	
		self.Destroy = function()
			if self.Destroyed then
				return
			end
			self.Destroyed = true
			self.Changed:Destroy()
			Element.releaseSearch(group, self)
			row.Root:Destroy()
		end
	
		-- The default is staged, not pushed: writing it into the store before bindConfig would
		-- clobber the value a loaded config is about to restore.
		Element.bindConfig(maid, self._flag, function(value)
			set(value == true, true)
		end, function()
			return self._value
		end)
	
		self.SearchId = Element.searchable(group, self, tostring(title), options.Desc)
	
		-- Painted, not animated: the row has never been on screen, and a switch lighting up by
		-- itself as a tab opens reads as the hub toggling features on its own.
		paint(self._value)
		Guard.set(row.Root, "LayoutOrder", group:RowCount())
		return self
	end
	
	return Checkbox
end

-- src/Components/ColorPicker.lua
FluxRegistry["Flux/Components/ColorPicker"] = function(require)
	--[[
		Components/ColorPicker — a swatch row that opens a hue/saturation popup.
	
		The value is carried as three numbers (hue, saturation, value) *and* a Color3: the swatch and
		the hex box paint from the Color3, while the two drag fields need the HSV form. Deriving hue
		from RGB on every repaint is how pickers drift a few units per theme swap, and the engine's
		Color3:ToHSV is not callable everywhere, so the conversion is written out here. A Color3 that
		arrives through `Set` is stored verbatim, so a hand-typed "#FF8000" round-trips through the
		hex box exactly instead of returning from the HSV round trip as #FF7F00.
	
		Colours on the square, the strip and the swatch are literal writes, not theme roles: they show
		the user's colour, not a token. Everything around them — panel, stroke, hex text — binds
		through Element, so a theme swap still restyles the popup itself.
	
		The gradient layers are built under Guard because the offline VM and several old executors
		have no ColorSequence/NumberSequence at all: each layer is created and destroyed as a unit,
		so a client without gradients gets flat (still clickable) fields rather than a black box,
		and the pixel math that turns a click into an HSV coordinate works either way.
	]]
	
	local Element = require("Flux/Core/Element")
	local Instance = require("Flux/Utilities/Instance")
	local Guard = require("Flux/Utilities/Guard")
	local Math = require("Flux/Utilities/Math")
	local Signal = require("Flux/Utilities/Signal")
	local String = require("Flux/Utilities/String")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	
	local UserInputService = Guard.service("UserInputService")
	
	local ColorPicker = {}
	
	local BODY_W = 150
	local SWATCH_W = 44
	local SWATCH_H = 24
	local SV_H = 88
	local STRIP_H = 12
	local POPUP_PAD = 6
	local POPUP_W = 170
	
	local function isPress(input: any): boolean
		local kind = Guard.get(input, "EnumType")
		return kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch
	end
	
	--- Standard RGB->HSV over 0..1 components, computed by hand for the reason in the header.
	local function toHsv(color: any): (number, number, number)
		local r, g, b = color.R, color.G, color.B
		local peak = math.max(r, g, b)
		local lowest = math.min(r, g, b)
		local delta = peak - lowest
		local hue = 0
		if delta > 0 then
			if peak == r then
				hue = ((g - b) / delta) % 6
			elseif peak == g then
				hue = (b - r) / delta + 2
			else
				hue = (r - g) / delta + 4
			end
			hue = hue / 6
			if hue < 0 then
				hue += 1
			end
		end
		local saturation = peak > 0 and delta / peak or 0
		return hue, saturation, peak
	end
	
	--- A gradient-painted overlay frame, or nil where the client cannot build one. The caller keeps
	--- working without it; only the look degrades.
	local function addGradientLayer(maid: any, parent: any, options: {
		Color: string,
		Stops: {{t: number, rgb: {[number]: number}}},
		Alpha: {number}?,
		Rotation: number?,
	}): any
		local ok, layer = Guard.try(function()
			if ColorSequence == nil or ColorSequenceKeypoint == nil then
				return nil
			end
			local frame = Instance.new("Frame", parent, {
				Name = "Layer_" .. options.Color,
				BackgroundColor3 = Color3.fromRGB(255, 255, 255),
				BorderSizePixel = 0,
				Size = UDim2.fromScale(1, 1),
				ZIndex = parent.ZIndex + 1,
			})
			local keys = {}
			for _, stop in ipairs(options.Stops) do
				table.insert(keys, ColorSequenceKeypoint.new(stop.t, Color3.fromRGB(stop.rgb[1], stop.rgb[2], stop.rgb[3])))
			end
			local gradient = Instance.new("UIGradient", frame, { Name = "Gradient" })
			gradient.Color = ColorSequence.new(keys)
			if options.Alpha ~= nil and NumberSequence ~= nil and NumberSequenceKeypoint ~= nil then
				local alphas = {}
				for index, alpha in ipairs(options.Alpha) do
					table.insert(alphas, NumberSequenceKeypoint.new(options.Stops[index].t, alpha))
				end
				gradient.Transparency = NumberSequence.new(alphas)
			end
			if options.Rotation ~= nil then
				gradient.Rotation = options.Rotation
			end
			frame.BackgroundColor3 = Color3.fromRGB(options.Stops[1].rgb[1], options.Stops[1].rgb[2], options.Stops[1].rgb[3])
			frame.BackgroundTransparency = options.Alpha ~= nil and 0 or 1
			return frame
		end)
	
		if not ok or layer == nil then
			return nil
		end
		maid:giveFunction(function()
			layer:Destroy()
		end)
		return layer
	end
	
	--- Component equality rather than `==`: Color3 is a userdata on the engine but a plain table
	--- with no __eq on some stubs and older executors, where identity comparison would report every
	--- re-application of the same colour as a change.
	local function sameColor(a: any, b: any): boolean
		if a == b then
			return true
		end
		local ar, ag, ab = Guard.get(a, "R"), Guard.get(a, "G"), Guard.get(a, "B")
		local br, bg, bb = Guard.get(b, "R"), Guard.get(b, "G"), Guard.get(b, "B")
		if ar == nil or br == nil then
			return false
		end
		return ar == br and ag == bg and ab == bb
	end
	
	function ColorPicker.new(group: any, options: {[string]: any}?)
		options = Element.options(options, {
			Name = "ColorPicker",
			Title = nil,
			Desc = nil,
			Default = Color3.fromRGB(255, 255, 255),
			Callback = nil,
			Flag = nil,
			Presets = nil,
			Transparency = false,
		})
	
		local title = options.Title or options.Name
		local maid = group.Maid
		local withAlpha = options.Transparency == true
	
		local row = Element.row(maid, group.Content, "ColorPicker_" .. tostring(title), {
			Label = title,
			Desc = options.Desc,
			BodyWidth = BODY_W,
			Order = group:RowCount() + 1,
		})
		local baseHeight = row.Root.Size.Y.Offset
	
		local swatch = Instance.new("TextButton", row.Body, {
			Name = "Swatch",
			Text = "",
			AutoButtonColor = false,
			-- The swatch paints the picked colour, not a theme token: a binding here would let a
			-- palette swap silently rewrite the user's choice.
			BackgroundColor3 = Color3.fromRGB(255, 255, 255),
			BorderSizePixel = 0,
			Size = UDim2.fromOffset(SWATCH_W, SWATCH_H),
			ZIndex = 6,
		})
		maid:giveFunction(function()
			swatch:Destroy()
		end)
		Element.round(maid, swatch, "RadiusChip")
	
		local popup = Element.panel(maid, row.Root, "Popup", {
			Color = "Panel",
			Radius = "RadiusField",
			Stroke = "BorderPrimary",
			Size = UDim2.fromOffset(POPUP_W, 0),
			Position = UDim2.new(1, 0, 0, baseHeight + 2),
			AnchorPoint = Vector2.new(1, 0),
			Clips = true,
			Visible = false,
			ZIndex = 40,
		})
	
		local sv = Instance.new("Frame", popup, {
			Name = "SV",
			BackgroundColor3 = Color3.fromRGB(255, 0, 0),
			BorderSizePixel = 0,
			Size = UDim2.new(1, -POPUP_PAD * 2, 0, SV_H),
			Position = UDim2.new(0, POPUP_PAD, 0, POPUP_PAD),
			ZIndex = 41,
		})
		-- white -> hue across, transparent -> black down: the two overlays every SV square uses.
		addGradientLayer(maid, sv, {
			Color = "Saturation",
			Stops = { { t = 0, rgb = { 255, 255, 255 } }, { t = 1, rgb = { 255, 255, 255 } } },
			Alpha = { 0, 1 },
		})
		addGradientLayer(maid, sv, {
			Color = "Value",
			Stops = { { t = 0, rgb = { 0, 0, 0 } }, { t = 1, rgb = { 0, 0, 0 } } },
			Alpha = { 1, 0 },
		})
		local svMarker = Instance.new("Frame", sv, {
			Name = "Marker",
			BackgroundColor3 = Color3.fromRGB(255, 255, 255),
			BorderSizePixel = 2,
			Size = UDim2.fromOffset(9, 9),
			AnchorPoint = Vector2.new(0.5, 0.5),
			ZIndex = 45,
		})
	
		local stripY = POPUP_PAD + SV_H + 6
		local hueStrip = Instance.new("Frame", popup, {
			Name = "Hue",
			BackgroundColor3 = Color3.fromRGB(255, 0, 0),
			BorderSizePixel = 0,
			Size = UDim2.new(1, -POPUP_PAD * 2, 0, STRIP_H),
			Position = UDim2.new(0, POPUP_PAD, 0, stripY),
			ZIndex = 41,
		})
		addGradientLayer(maid, hueStrip, {
			Color = "Hue",
			Stops = {
				{ t = 0, rgb = { 255, 0, 0 } },
				{ t = 0.1667, rgb = { 255, 255, 0 } },
				{ t = 0.3333, rgb = { 0, 255, 0 } },
				{ t = 0.5, rgb = { 0, 255, 255 } },
				{ t = 0.6667, rgb = { 0, 0, 255 } },
				{ t = 0.8333, rgb = { 255, 0, 255 } },
				{ t = 1, rgb = { 255, 0, 0 } },
			},
		})
		local hueMarker = Instance.new("Frame", hueStrip, {
			Name = "Marker",
			BackgroundColor3 = Color3.fromRGB(255, 255, 255),
			BorderSizePixel = 0,
			Size = UDim2.fromOffset(3, STRIP_H),
			AnchorPoint = Vector2.new(0.5, 0),
			ZIndex = 45,
		})
	
		local alphaStrip = nil
		local alphaMarker = nil
		if withAlpha then
			alphaStrip = Instance.new("Frame", popup, {
				Name = "Alpha",
				BackgroundColor3 = Color3.fromRGB(128, 128, 128),
				BorderSizePixel = 0,
				Size = UDim2.new(1, -POPUP_PAD * 2, 0, STRIP_H),
				Position = UDim2.new(0, POPUP_PAD, 0, stripY + STRIP_H + 6),
				ZIndex = 41,
			})
			addGradientLayer(maid, alphaStrip, {
				Color = "Fade",
				Stops = { { t = 0, rgb = { 0, 0, 0 } }, { t = 1, rgb = { 0, 0, 0 } } },
				Alpha = { 1, 0 },
			})
			alphaMarker = Instance.new("Frame", alphaStrip, {
				Name = "Marker",
				BackgroundColor3 = Color3.fromRGB(255, 255, 255),
				BorderSizePixel = 0,
				Size = UDim2.fromOffset(3, STRIP_H),
				AnchorPoint = Vector2.new(0.5, 0),
				ZIndex = 45,
			})
		end
	
		local hexY = stripY + STRIP_H + 6 + (withAlpha and STRIP_H + 6 or 0)
		local hexBox = Instance.new("TextBox", popup, {
			Name = "Hex",
			Text = "",
			PlaceholderText = "RRGGBB",
			BackgroundColor3 = ThemeManager.color("Field"),
			TextColor3 = ThemeManager.color("TextPrimary"),
			Font = ThemeManager.font("Mono"),
			TextSize = 12,
			BorderSizePixel = 0,
			Size = UDim2.new(1, -POPUP_PAD * 2, 0, 20),
			Position = UDim2.new(0, POPUP_PAD, 0, hexY),
			ZIndex = 41,
		})
		maid:giveFunction(function()
			hexBox:Destroy()
		end)
		maid:give(ThemeManager.bind(hexBox, "TextColor3", "TextPrimary"))
	
		local popupHeight = hexY + 20 + POPUP_PAD
	
		local self = {
			Instance = row.Root,
			Title = title,
			Changed = Signal.new(),
			Open = false,
			_color = Color3.fromRGB(255, 255, 255),
			_h = 0,
			_s = 0,
			_v = 1,
			_alpha = 0,
			_callback = options.Callback,
			_group = group,
			_flag = options.Flag,
			_row = row,
		}
	
		local function triple(): {number}
			local color = self._color
			local out = {
				math.floor((Guard.get(color, "R") or 1) * 255 + 0.5),
				math.floor((Guard.get(color, "G") or 0) * 255 + 0.5),
				math.floor((Guard.get(color, "B") or 0) * 255 + 0.5),
			}
			if withAlpha then
				table.insert(out, math.floor((1 - self._alpha) * 255 + 0.5))
			end
			return out
		end
	
		local function paint()
			swatch.BackgroundColor3 = self._color
			sv.BackgroundColor3 = Color3.fromHSV(self._h, 1, 1)
			svMarker.Position = UDim2.fromScale(Math.clamp(self._s, 0, 1), Math.clamp(1 - self._v, 0, 1))
			hueMarker.Position = UDim2.fromScale(Math.clamp(self._h, 0, 1), 0)
			if alphaMarker ~= nil then
				alphaMarker.Position = UDim2.fromScale(Math.clamp(1 - self._alpha, 0, 1), 0)
			end
			hexBox.Text = String.colorToHex(self._color)
		end
	
		local function applyColor(color: any, fromUser: boolean)
			local coerced = ThemeManager.coerceColor(color)
			if coerced == nil then
				return false
			end
			local changed = false
			if not sameColor(coerced, self._color) then
				changed = true
			end
			self._color = coerced
			local h, s, v = toHsv(coerced)
			self._h, self._s, self._v = h, s, v
			paint()
			if changed then
				Element.pushConfig(self._flag, triple())
				self.Changed:Dispatch(coerced)
				if fromUser and self._callback ~= nil then
					local ok, err = pcall(self._callback, coerced)
					if not ok then
						warn("[Flux] color picker '" .. tostring(title) .. "': " .. tostring(err))
					end
				end
			end
			return changed
		end
	
		local region: string? = nil
		local moveConnection = nil
		local endConnection = nil
		local moved = false
	
		-- AbsoluteSize is the denominator for the same reason it is on the slider: input.Position and
		-- absolute geometry are both engine-space pixels, so their quotient already cancels UIScale.
		local function fractionIn(frame: any, point: any, horizontal: boolean): number
			local origin = frame.AbsolutePosition
			local size = frame.AbsoluteSize
			local span = horizontal and size.X or size.Y
			if span <= 0 then
				return 0
			end
			local start = horizontal and origin.X or origin.Y
			local cursor = horizontal and point.X or point.Y
			return Math.clamp((cursor - start) / span, 0, 1)
		end
	
		local function updateRegion(input: any)
			local point = Guard.get(input, "Position")
			if point == nil or region == nil then
				return
			end
			local before = self._color
			if region == "sv" then
				self._s = fractionIn(sv, point, true)
				self._v = 1 - fractionIn(sv, point, false)
				applyColor(Color3.fromHSV(self._h, self._s, self._v), false)
			elseif region == "hue" then
				self._h = fractionIn(hueStrip, point, true)
				applyColor(Color3.fromHSV(self._h, self._s, self._v), false)
			elseif region == "alpha" then
				self._alpha = 1 - fractionIn(alphaStrip, point, true)
				paint()
			end
			if not sameColor(self._color, before) or (region == "alpha" and withAlpha) then
				moved = true
			end
		end
	
		local function releaseDrag(fire: boolean)
			if region == nil then
				return
			end
			region = nil
			if moveConnection ~= nil then
				moveConnection:Disconnect()
				moveConnection = nil
			end
			if endConnection ~= nil then
				endConnection:Disconnect()
				endConnection = nil
			end
			if fire and not self.Destroyed and moved then
				moved = false
				Element.pushConfig(self._flag, triple())
				if self._callback ~= nil then
					local ok, err = pcall(self._callback, self._color)
					if not ok then
						warn("[Flux] color picker '" .. tostring(title) .. "': " .. tostring(err))
					end
				end
			end
			moved = false
		end
	
		local function grab(target: string, input: any)
			if self.Destroyed then
				return
			end
			region = target
			local movementSignal = UserInputService ~= nil and Guard.get(UserInputService, "InputChanged") or nil
			local releaseSignal = UserInputService ~= nil and Guard.get(UserInputService, "InputEnded") or nil
			if movementSignal ~= nil then
				moveConnection = movementSignal:Connect(function(nextInput)
					if region ~= nil and not self.Destroyed then
						updateRegion(nextInput)
					end
				end)
			end
			if releaseSignal ~= nil then
				endConnection = releaseSignal:Connect(function(over)
					if isPress(over) then
						releaseDrag(true)
					end
				end)
			end
			updateRegion(input)
		end
	
		local function overRect(frame: any, point: any, pad: number): boolean
			local origin = frame.AbsolutePosition
			local size = frame.AbsoluteSize
			return point.X >= origin.X - pad
				and point.X <= origin.X + size.X + pad
				and point.Y >= origin.Y - pad
				and point.Y <= origin.Y + size.Y + pad
		end
	
		for _, pair in ipairs({ { sv, "sv" }, { hueStrip, "hue" }, { alphaStrip, "alpha" } }) do
			local frame = pair[1]
			if frame ~= nil then
				local down = Guard.get(frame, "MouseButton1Down")
				if down ~= nil then
					maid:giveConnection(down:Connect(function(input)
						grab(pair[2], input)
					end))
				end
				-- Touch rides the frame's own gesture stream on the engine and the service's on
				-- mobile; the `region ~= nil` latch keeps the two from double-grabbing.
				local touchBegan = Guard.get(frame, "InputBegan")
				local touchMoved = Guard.get(frame, "InputChanged")
				local touchEnded = Guard.get(frame, "InputEnded")
				if touchBegan ~= nil and touchMoved ~= nil and touchEnded ~= nil then
					maid:giveConnection(touchBegan:Connect(function(input)
						if isPress(input) then
							grab(pair[2], input)
						end
					end))
					maid:giveConnection(touchMoved:Connect(function(input)
						if region == pair[2] and isPress(input) then
							updateRegion(input)
						end
					end))
					maid:giveConnection(touchEnded:Connect(function(input)
						if isPress(input) then
							releaseDrag(true)
						end
					end))
				end
			end
		end
	
		local beganSignal = UserInputService ~= nil and Guard.get(UserInputService, "InputBegan") or nil
		if beganSignal ~= nil then
			maid:giveConnection(beganSignal:Connect(function(input)
				if region ~= nil or not self.Open or not isPress(input) then
					return
				end
				local point = Guard.get(input, "Position")
				if point == nil then
					return
				end
				if overRect(sv, point, 0) then
					grab("sv", input)
				elseif overRect(hueStrip, point, 3) then
					grab("hue", input)
				elseif alphaStrip ~= nil and overRect(alphaStrip, point, 3) then
					grab("alpha", input)
				end
			end))
		end
	
		local ensurePresets: () -> ()
		local presetHost = nil
	
		ensurePresets = function()
			if presetHost ~= nil or options.Presets == nil or self.Destroyed then
				return
			end
			presetHost = Instance.new("Frame", popup, {
				Name = "Presets",
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Size = UDim2.new(1, -POPUP_PAD * 2, 0, 18),
				Position = UDim2.new(0, POPUP_PAD, 0, popupHeight + 2),
				ZIndex = 41,
			})
			maid:giveFunction(function()
				presetHost:Destroy()
			end)
			local layout = Instance.new("UIListLayout", presetHost, {
				FillDirection = Enum.FillDirection.Horizontal,
				SortOrder = Enum.SortOrder.LayoutOrder,
				Padding = UDim.new(0, 4),
			})
			maid:giveFunction(function()
				layout:Destroy()
			end)
			local order = 0
			for _, entry in ipairs(options.Presets) do
				local color = ThemeManager.coerceColor(entry)
				if color ~= nil then
					order += 1
					local chip = Instance.new("TextButton", presetHost, {
						Name = "Preset_" .. order,
						Text = "",
						AutoButtonColor = false,
						BackgroundColor3 = color,
						BorderSizePixel = 0,
						Size = UDim2.fromOffset(16, 16),
						LayoutOrder = order,
						ZIndex = 42,
					})
					maid:giveFunction(function()
						chip:Destroy()
					end)
					chip.MouseButton1Click:Connect(function()
						applyColor(color, true)
					end)
				end
			end
			if order > 0 then
				popupHeight = popupHeight + 24
				if self.Open then
					popup.Size = UDim2.fromOffset(POPUP_W, popupHeight)
					row.Root.Size = UDim2.new(1, 0, 0, baseHeight + popupHeight + 6)
				end
			end
		end
	
		self.OpenList = function()
			if self.Open or self.Destroyed then
				return self
			end
			self.Open = true
			ensurePresets()
			popup.Visible = true
			popup.Size = UDim2.fromOffset(POPUP_W, popupHeight)
			-- The row grows to cover the popup so the outside-click watcher counts a click inside
			-- the square as a click on the widget; a list pinned *outside* the watched rectangle
			-- would close itself a mouse-down before the row's click ever lands.
			row.Root.Size = UDim2.new(1, 0, 0, baseHeight + popupHeight + 6)
			return self
		end
	
		self.Close = function()
			if not self.Open then
				return self
			end
			releaseDrag(false)
			self.Open = false
			popup.Visible = false
			popup.Size = UDim2.fromOffset(POPUP_W, 0)
			row.Root.Size = UDim2.new(1, 0, 0, baseHeight)
			return self
		end
	
		local closeWatcher = Element.outsideClick(row.Root, function()
			self:Close()
		end)
	
		swatch.MouseButton1Click:Connect(function()
			if self.Destroyed then
				return
			end
			if self.Open then
				self:Close()
			else
				self:OpenList()
			end
		end)
	
		local function commitHex()
			if self.Destroyed then
				return
			end
			local parsed = String.hexToColor(hexBox.Text)
			if parsed == nil then
				-- Reject, do not guess: applying black to garbage is how a picker "loses" a colour
				-- the first time the field is mistyped.
				hexBox.Text = String.colorToHex(self._color)
				return
			end
			local changed = applyColor(parsed, true)
			if not changed and self._callback ~= nil then
				-- Re-committing the same colour is still a finished edit the host expects to hear.
				local ok, err = pcall(self._callback, self._color)
				if not ok then
					warn("[Flux] color picker '" .. tostring(title) .. "': " .. tostring(err))
				end
			end
		end
	
		local focusLost = Guard.get(hexBox, "FocusLost")
		if focusLost ~= nil then
			maid:giveConnection(focusLost:Connect(function(entered: boolean)
				if entered then
					commitHex()
				end
			end))
		end
		local activated = Guard.get(hexBox, "Activated")
		if activated ~= nil then
			maid:giveConnection(activated:Connect(commitHex))
		end
	
		-- Methods live on the table as fields (the internal style of this library) while hosts call
		-- them with a colon. Accept both: when the first argument is the widget itself, the real
		-- argument is the one behind it.
		local function recv(a: any, b: any): any
			if a == self then
				return b
			end
			return a
		end
	
		self.Set = function(a: any, b: any)
			if self.Destroyed then
				return self
			end
			applyColor(recv(a, b), false)
			return self
		end
		self.SetColor = self.Set
	
		self.GetValue = function()
			return self._color
		end
	
		self.GetHex = function()
			return String.colorToHex(self._color)
		end
	
		self.GetText = function()
			return hexBox.Text
		end
	
		self.SetText = function(a: any, b: any)
			self.Title = tostring(recv(a, b))
			row.Title.Text = self.Title
			return self
		end
		self.SetTitle = self.SetText
	
		self.SetVisible = function(a: any, b: any)
			local visible = recv(a, b)
			if not visible then
				self:Close()
			end
			row.Root.Visible = visible == true
			return self
		end
	
		self.OnFilter = function(a: any, b: any)
			local matched = recv(a, b)
			if not matched then
				self:Close()
			end
			row.Root.Visible = matched == true
		end
	
		self.Destroy = function()
			if self.Destroyed then
				return
			end
			releaseDrag(false)
			self:Close()
			self.Destroyed = true
			if closeWatcher ~= nil then
				closeWatcher()
			end
			self.Changed:Destroy()
			Element.releaseSearch(group, self)
			row.Root:Destroy()
		end
	
		local initial = ThemeManager.coerceColor(options.Default)
		if initial == nil then
			initial = Color3.fromRGB(255, 255, 255)
		end
		self._color = initial
		local h, s, v = toHsv(initial)
		self._h, self._s, self._v = h, s, v
		paint()
	
		Element.bindConfig(maid, self._flag, function(value)
			if not self.Destroyed then
				applyColor(value, false)
			end
		end, function()
			return triple()
		end)
	
		self.SearchId = Element.searchable(group, self, tostring(title), options.Desc)
		Guard.set(row.Root, "LayoutOrder", group:RowCount())
		return self
	end
	
	return ColorPicker
end

-- src/Components/Divider.lua
FluxRegistry["Flux/Components/Divider"] = function(require)
	--[[
		Components/Divider — a hairline separator with an optional inline caption.
	
		A group already has a header; a divider exists for the quieter break inside one — between a
		block of toggles and the paragraph that explains them. One line, one token: the hairline is
		`BorderPrimary` at the theme's `StrokeThickness`, so a preset that thickens borders thickens
		this too, and a host that pins the metric sees the row grow without a rebuild.
	
		The caption sits *on* the line with a `Panel`-bound chip behind it, rather than splitting the
		line into two segments: two segments have to be measured against the text and re-measured on
		every theme font change, and a centred chip costs one frame and one binding.
	]]
	
	local Element = require("Flux/Core/Element")
	local Instance = require("Flux/Utilities/Instance")
	local Guard = require("Flux/Utilities/Guard")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	
	local Divider = {}
	
	local SPACING = 6
	local CHIP_H = 16
	
	function Divider.new(group: any, options: {[string]: any}?)
		options = Element.options(options, {
			Name = "Divider",
			Text = nil,
			Thickness = nil,
			Spacing = nil,
		})
	
		local maid = group.Maid
		local name = tostring(options.Name)
		local override = tonumber(options.Thickness)
		local spacing = tonumber(options.Spacing) or SPACING
		local lineH = override or ThemeManager.metric("StrokeThickness") or 1
	
		local root = Element.panel(maid, group.Content, "Divider_" .. name, {
			Transparency = 1,
			Size = UDim2.new(1, 0, 0, lineH + spacing * 2),
			LayoutOrder = group:RowCount() + 1,
			ZIndex = 5,
		})
	
		local line = Element.panel(maid, root, "Line", {
			Color = "BorderPrimary",
			Size = UDim2.new(1, 0, 0, lineH),
			Position = UDim2.new(0, 0, 0.5, 0),
			AnchorPoint = Vector2.new(0, 0.5),
			ZIndex = 6,
		})
	
		local caption = nil
		if type(options.Text) == "string" and options.Text ~= "" then
			local chip = Instance.new("Frame", root, {
				Name = "Caption",
				BackgroundColor3 = ThemeManager.color("Panel"),
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5),
				BorderSizePixel = 0,
				ZIndex = 7,
			})
			chip.AutomaticSize = Enum.AutomaticSize.XY
			maid:giveFunction(function()
				chip:Destroy()
			end)
			maid:give(ThemeManager.bind(chip, "BackgroundColor3", "Panel"))
			local padding = Instance.pad(chip, {
				Top = UDim.new(0, 1),
				Bottom = UDim.new(0, 1),
				Left = UDim.new(0, 6),
				Right = UDim.new(0, 6),
			})
			maid:giveFunction(function()
				padding:Destroy()
			end)
			Element.round(maid, chip, "RadiusChip")
	
			caption = Element.label(maid, chip, "Text", {
				Text = options.Text,
				Role = "TextMuted",
				TextSize = 11,
				Alignment = Enum.TextXAlignment.Center,
				AutoWidth = true,
				Size = UDim2.fromOffset(0, CHIP_H),
				ZIndex = 8,
			})
		end
	
		local self = {
			Instance = root,
			Title = name,
			_maid = maid,
			_group = group,
			_text = (type(options.Text) == "string" and options.Text) or "",
		}
	
		-- The line height follows the theme's stroke metric unless the host overrode it; a pinned
		-- Thickness is the host's own number and no preset gets to move it.
		maid:give(ThemeManager.bindFn(function(tokens)
			lineH = override or tokens.metrics.StrokeThickness or lineH
			line.Size = UDim2.new(1, 0, 0, lineH)
			root.Size = UDim2.new(1, 0, 0, lineH + spacing * 2)
		end, { "StrokeThickness" }))
	
		self.SetText = function(a: any, b: any)
			local value = a
			if a == self then
				value = b
			end
			if self.Destroyed or caption == nil then
				return self
			end
			self._text = tostring(value)
			caption.Text = self._text
			return self
		end
	
		self.Set = self.SetText
	
		self.GetValue = function()
			return self._text
		end
	
		self.GetText = self.GetValue
	
		-- A divider draws no title of its own (the line IS the row), so SetTitle keeps the family
		-- surface honest: it renames the widget's identity without touching the artwork.
		self.SetTitle = function(a: any, b: any)
			local text = a
			if a == self then
				text = b
			end
			self.Title = tostring(text)
			return self
		end
	
		self.SetVisible = function(a: any, b: any)
			local visible = a
			if a == self then
				visible = b
			end
			root.Visible = visible == true
			return self
		end
	
		-- Groupbox calls this plain and a host calls it with a colon, hence the (a, b) read.
		self.OnFilter = function(a: any, b: any)
			local matched = a
			if a == self then
				matched = b
			end
			root.Visible = matched == true
		end
	
		self.Destroy = function()
			if self.Destroyed then
				return
			end
			self.Destroyed = true
			Element.releaseSearch(group, self)
			root:Destroy()
		end
	
		self.SearchId = Element.searchable(group, self, name, self._text)
		Guard.set(root, "LayoutOrder", group:RowCount())
		return self
	end
	
	return Divider
end

-- src/Components/Dropdown.lua
FluxRegistry["Flux/Components/Dropdown"] = function(require)
	--[[
		Components/Dropdown — a labelled picker over a list of choices.
	
		The list closes on an outside click and never on focus loss. Focus leaves a widget on
		*mouse-down*, so a FocusLost-driven close would collapse the list between the press and the
		release and the first click on every row would miss. `Element.outsideClick` sees the same
		mouse-down, which is why the watcher is anchored to the row and the row grows by the list's
		height while open: a click on a row must read as inside the watched rectangle.
	
		Choice rows are built on open, not at declaration — a hub with six profile dropdowns of forty
		configs each is two hundred and forty instances no one looks at until a list is clicked. The
		module keeps one list of open dropdowns so opening the second closes the first, the way every
		desktop combo box behaves.
	
		Entries accept plain strings or { Label, Value, Disabled } records; the stored value is what
		the callback and the config see, while the label is display-only, so renaming an option cannot
		orphan a saved profile.
	]]
	
	local Element = require("Flux/Core/Element")
	local Instance = require("Flux/Utilities/Instance")
	local Guard = require("Flux/Utilities/Guard")
	local Maid = require("Flux/Utilities/Maid")
	local Signal = require("Flux/Utilities/Signal")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	local Icons = require("Flux/Systems/IconManager")
	
	local Dropdown = {}
	
	local BODY_W = 150
	local BUTTON_H = 26
	local OPTION_H = 22
	local POPUP_GAP = 4
	
	--- Open dropdowns, module-wide. Kept here rather than on a manager because closing is a one-line
	--- call on the widget itself — a system for it would only exist to hold this list.
	local openOnes: {any} = {}
	
	local glyph: string? = nil
	local function chevronName(): string?
		if glyph == nil then
			for _, name in ipairs({ "caret", "chevronDown", "bullet" }) do
				if Icons.has(name) then
					glyph = name
					break
				end
			end
			if glyph == nil then
				glyph = false :: any
			end
		end
		return glyph
	end
	
	local function normalize(source: {any}?): {{label: string, value: any, disabled: boolean}}
		local out = {}
		for _, item in ipairs(source or {}) do
			if type(item) == "table" then
				local value = item.Value
				if value == nil then
					value = item.Label
				end
				table.insert(out, { label = tostring(item.Label or value), value = value, disabled = item.Disabled == true })
			elseif item ~= nil then
				table.insert(out, { label = tostring(item), value = item, disabled = false })
			end
		end
		return out
	end
	
	function Dropdown.new(group: any, options: {[string]: any}?)
		options = Element.options(options, {
			Name = "Dropdown",
			Title = nil,
			Desc = nil,
			Default = nil,
			Options = {},
			Callback = nil,
			Flag = nil,
			Placeholder = "Select…",
			MaxHeight = 200,
			Searchable = false,
		})
	
		local title = options.Title or options.Name
		local maid = group.Maid
		local entries = normalize(options.Options)
	
		local row = Element.row(maid, group.Content, "Dropdown_" .. tostring(title), {
			Label = title,
			Desc = options.Desc,
			BodyWidth = BODY_W,
			Order = group:RowCount() + 1,
		})
		local baseHeight = row.Root.Size.Y.Offset
	
		local button = Instance.new("TextButton", row.Body, {
			Name = "Selector",
			Text = "",
			AutoButtonColor = false,
			BackgroundColor3 = ThemeManager.color("Field"),
			BorderSizePixel = 0,
			Size = UDim2.fromOffset(BODY_W, BUTTON_H),
			ZIndex = 6,
		})
		maid:giveFunction(function()
			button:Destroy()
		end)
		Element.round(maid, button, "RadiusField")
	
		local display = Element.label(maid, button, "Text", {
			Text = "",
			Role = "TextPrimary",
			TextSize = 12,
			Alignment = Enum.TextXAlignment.Left,
			Size = UDim2.new(1, -22, 1, 0),
			ZIndex = 7,
		})
	
		local chevron = nil
		local chevronGlyph = chevronName()
		if chevronGlyph ~= nil then
			chevron = Element.icon(maid, button, chevronGlyph, {
				Role = "TextSecondary",
				Size = UDim2.fromOffset(11, 11),
				Position = UDim2.new(1, -15, 0.5, 0),
				AnchorPoint = Vector2.new(0.5, 0.5),
				ZIndex = 7,
			})
		end
	
		local popup = Instance.new("ScrollingFrame", row.Root, {
			Name = "List",
			BackgroundColor3 = ThemeManager.color("PanelSecondary"),
			BorderSizePixel = 0,
			Size = UDim2.new(1, 0, 0, 0),
			Position = UDim2.new(0, 0, 0, baseHeight + 2),
			ZIndex = 40,
			ScrollingEnabled = true,
			Visible = false,
		})
		maid:giveFunction(function()
			popup:Destroy()
		end)
		popup.ClipsDescendants = true
		Element.round(maid, popup, "RadiusField", -2)
		-- CanvasPosition is only written back through Guard because older clients read the property
		-- but refuse the write, and a failed reset on open must not abort the whole dropdown.
		local popupStroke = Instance.stroke(popup, ThemeManager.color("BorderPrimary"), ThemeManager.metric("StrokeThickness") or 1)
		if popupStroke ~= nil then
			maid:giveFunction(function()
				popupStroke:Destroy()
			end)
			maid:give(ThemeManager.bind(popupStroke, "Color", "BorderPrimary"))
		end
		local popupList = Instance.new("UIListLayout", popup, {
			FillDirection = Enum.FillDirection.Vertical,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 2),
		})
		maid:giveFunction(function()
			popupList:Destroy()
		end)
		local popupPad = Instance.pad(popup, { Top = UDim.new(0, 3), Bottom = UDim.new(0, 3), Left = UDim.new(0, 3), Right = UDim.new(0, 3) })
		maid:giveFunction(function()
			popupPad:Destroy()
		end)
	
		local filterBox = nil
		if options.Searchable == true then
			filterBox = Instance.new("TextBox", popup, {
				Name = "Filter",
				BackgroundTransparency = 1,
				PlaceholderText = "search",
				TextColor3 = ThemeManager.color("TextSecondary"),
				TextSize = 12,
				Size = UDim2.new(1, 0, 0, 18),
				BorderSizePixel = 0,
				ZIndex = 41,
			})
			maid:giveFunction(function()
				filterBox:Destroy()
			end)
			maid:give(ThemeManager.bind(filterBox, "TextColor3", "TextSecondary"))
		end
	
		local self = {
			Instance = row.Root,
			Title = title,
			Changed = Signal.new(),
			Open = false,
			_value = nil,
			_index = nil,
			_callback = options.Callback,
			_group = group,
			_flag = options.Flag,
			_row = row,
			_entries = entries,
			_rows = {},
		}
		local rowsMaid = Maid.new()
		maid:chain(rowsMaid)
	
		local function findEntry(raw: any): number?
			for index, entry in ipairs(entries) do
				if entry.value == raw or entry.label == tostring(raw) then
					return index
				end
			end
			-- A bare number that matches no value is an index, so `Default = 2` works on string lists.
			if type(raw) == "number" then
				local position = math.floor(raw)
				if position >= 1 and position <= #entries then
					return position
				end
			end
			return nil
		end
	
		local function paintDisplay()
			local index = self._index
			if index ~= nil and entries[index] ~= nil then
				display.Text = entries[index].label
				-- Placeholder and selection are the same label in different roles; tinting (rather
				-- than writing TextColor3) keeps a later theme swap on the role that is showing.
				Element.tint(maid, display, "TextColor3", "TextPrimary")
			else
				display.Text = tostring(options.Placeholder)
				Element.tint(maid, display, "TextColor3", "TextMuted")
			end
		end
	
		local function clearRows()
			for _, node in ipairs(popup:GetChildren()) do
				if node ~= popupList and node ~= popupPad and node ~= filterBox and not node:IsA("UIComponent") then
					node:Destroy()
				end
			end
			-- The per-row theme bindings live on a sub-maid: rows are rebuilt on every open, and
			-- handing each generation to the group's maid would grow it one entry per click.
			rowsMaid:cleanup()
			table.clear(self._rows)
		end
	
		local function buildRows()
			clearRows()
			local query = filterBox ~= nil and string.lower(filterBox.Text or "") or ""
			local order = 0
			local shown = 0
	
			for index, entry in ipairs(entries) do
				local needle = string.lower(entry.label)
				if query == "" or needle:find(query, 1, true) ~= nil then
					order += 1
					shown += 1
					local option = Instance.new("TextButton", popup, {
						Name = "Option_" .. index,
						Text = " " .. entry.label,
						AutoButtonColor = true,
						Font = ThemeManager.font("Body"),
						TextSize = 12,
						TextXAlignment = Enum.TextXAlignment.Left,
						BackgroundColor3 = ThemeManager.color("AccentSoft"),
						BackgroundTransparency = 1,
						BorderSizePixel = 0,
						Size = UDim2.new(1, 0, 0, OPTION_H),
						LayoutOrder = order,
						ZIndex = 41,
					})
					self._rows[#self._rows + 1] = { button = option, index = index, entry = entry }
	
					if entry.disabled then
						option.Active = false
						Element.tint(rowsMaid, option, "TextColor3", "TextMuted")
					else
						option.MouseButton1Click:Connect(function()
							if not self.Destroyed then
								self:_pick(index)
							end
						end)
						Element.tint(rowsMaid, option, "TextColor3", "TextPrimary")
					end
				end
			end
	
			if shown == 0 then
				-- An empty list still has to say so: a 0-height popup that opens and closes without a
				-- pixel of feedback reads as a broken button.
				Instance.new("TextLabel", popup, {
					Name = "Empty",
					Text = "Nothing to select",
					BackgroundTransparency = 1,
					TextColor3 = ThemeManager.color("TextMuted"),
					TextSize = 12,
					Font = ThemeManager.font("Body"),
					Size = UDim2.new(1, 0, 0, OPTION_H),
					ZIndex = 41,
				})
				shown = 1
			end
	
			local height = math.min(options.MaxHeight, shown * (OPTION_H + 2) + 6)
			popup.Size = UDim2.new(1, 0, 0, height)
			Guard.set(popup, "CanvasSize", UDim2.new(0, 0, 0, math.max(0, shown * (OPTION_H + 2) + 6)))
			return height
		end
	
		function self:_pick(index: number)
			local entry = entries[index]
			if entry == nil or entry.disabled then
				return self
			end
			local changed = self._value ~= entry.value or self._index ~= index
			self._value = entry.value
			self._index = index
			paintDisplay()
			if changed then
				Element.pushConfig(self._flag, entry.value)
				self.Changed:Dispatch(entry.value)
				if self._callback ~= nil then
					local ok, err = pcall(self._callback, entry.value)
					if not ok then
						warn("[Flux] dropdown '" .. tostring(title) .. "': " .. tostring(err))
					end
				end
			end
			self:Close()
			return self
		end
	
		local function setRotation(angle: number)
			if chevron ~= nil and chevron.instance ~= nil then
				Guard.set(chevron.instance, "Rotation", angle)
			end
		end
	
		self.Close = function()
			if not self.Open then
				return self
			end
			self.Open = false
			popup.Visible = false
			popup.Size = UDim2.new(1, 0, 0, 0)
			row.Root.Size = UDim2.new(1, 0, 0, baseHeight)
			for index = #openOnes, 1, -1 do
				if openOnes[index] == self then
					table.remove(openOnes, index)
				end
			end
			setRotation(0)
			return self
		end
		self._close = self.Close
	
		self.OpenList = function()
			if self.Open or self.Destroyed then
				return self
			end
			for _, other in ipairs(table.clone(openOnes)) do
				if other ~= self then
					other:_close()
				end
			end
			self.Open = true
			table.insert(openOnes, self)
			local height = buildRows()
			-- The row grows so the watched rectangle covers the list: outsideClick compares the
			-- pointer against this frame, and a row click lands below its resting bottom edge.
			row.Root.Size = UDim2.new(1, 0, 0, baseHeight + height + POPUP_GAP + 2)
			popup.Visible = true
			setRotation(90)
			return self
		end
	
		self.IsOpen = function()
			return self.Open
		end
	
		local closeWatcher = Element.outsideClick(row.Root, function()
			self:Close()
		end)
	
		button.MouseButton1Click:Connect(function()
			if self.Destroyed then
				return
			end
			if self.Open then
				self:Close()
			else
				self:OpenList()
			end
		end)
	
		if filterBox ~= nil then
			local changed = Guard.get(filterBox, "GetPropertyChangedSignal")
			if changed ~= nil then
				maid:giveConnection(changed(filterBox, "Text"):Connect(function()
					if self.Open and not self.Destroyed then
						buildRows()
					end
				end))
			end
		end
	
		-- Methods live on the table as fields (the internal style of this library) while hosts call
		-- them with a colon. Accept both; with two positional arguments that means shifting the
		-- whole list by one when the leading one is the widget itself.
		local function take(widget: any, a: any, b: any, c: any): (any, any)
			if widget ~= nil and a == widget then
				return b, c
			end
			return a, b
		end
	
		self.Set = function(a: any, b: any, c: any)
			if self.Destroyed then
				return self
			end
			local value, silent = take(self, a, b, c)
			local index = findEntry(value)
			self._index = index
			self._value = index ~= nil and entries[index].value or nil
			paintDisplay()
			if index ~= nil then
				Element.pushConfig(self._flag, self._value)
				if not silent then
					self.Changed:Dispatch(self._value)
				end
			end
			return self
		end
	
		self.GetValue = function()
			return self._value
		end
	
		self.GetOptions = function()
			local out = {}
			for _, entry in ipairs(entries) do
				table.insert(out, entry.value)
			end
			return out
		end
	
		self.Refresh = function(a: any, b: any)
			local newOptions = take(self, a, b, nil)
			entries = normalize(newOptions)
			self._entries = entries
			local keep = self._value
			self._index = nil
			self._value = nil
			local index = findEntry(keep)
			if index ~= nil then
				self._index = index
				self._value = entries[index].value
			end
			paintDisplay()
			if self.Open then
				buildRows()
			end
			return self
		end
	
		self.SetText = function(a: any, b: any)
			self.Title = tostring(take(self, a, b, nil))
			row.Title.Text = self.Title
			return self
		end
		self.SetTitle = self.SetText
	
		self.SetVisible = function(a: any, b: any)
			local visible = take(self, a, b, nil)
			if not visible then
				self:Close()
			end
			row.Root.Visible = visible == true
			return self
		end
	
		self.OnFilter = function(a: any, b: any)
			local matched = take(self, a, b, nil)
			if not matched then
				self:Close()
			end
			row.Root.Visible = matched == true
		end
	
		self.Destroy = function()
			if self.Destroyed then
				return
			end
			self:Close()
			self.Destroyed = true
			if closeWatcher ~= nil then
				closeWatcher()
			end
			self.Changed:Destroy()
			Element.releaseSearch(group, self)
			row.Root:Destroy()
		end
	
		-- Staged directly instead of through Set: pushing the default into the config store before
		-- bindConfig runs would clobber the value a loaded config restored moments earlier.
		local initial = findEntry(options.Default)
		self._index = initial
		self._value = initial ~= nil and entries[initial].value or nil
		paintDisplay()
		Element.bindConfig(maid, self._flag, function(value)
			if not self.Destroyed then
				self:Set(value, true)
			end
		end, function()
			return self._value
		end)
	
		self.SearchId = Element.searchable(group, self, tostring(title), options.Desc)
		Guard.set(row.Root, "LayoutOrder", group:RowCount())
		return self
	end
	
	return Dropdown
end

-- src/Components/Index.lua
FluxRegistry["Flux/Components/Index"] = function(require)
	--[[
		Components/Index — the widget list, in one place.

		Core/Container builds every constructor from this table, so adding a component means writing
		the module and naming it here: nothing in the window, tab or groupbox code changes. Paths are
		module ids the bundler resolves, not filesystem paths.
	]]

	return {
		-- Controls the user acts on
		Button = "Flux/Components/Button",
		Toggle = "Flux/Components/Toggle",
		Checkbox = "Flux/Components/Checkbox",
		Slider = "Flux/Components/Slider",
		Dropdown = "Flux/Components/Dropdown",
		Input = "Flux/Components/Input",
		Keybind = "Flux/Components/Keybind",
		ColorPicker = "Flux/Components/ColorPicker",

		-- Read-only surfaces
		Label = "Flux/Components/Label",
		Paragraph = "Flux/Components/Paragraph",
		Divider = "Flux/Components/Divider",
		ProgressBar = "Flux/Components/ProgressBar",
	}
end

-- src/Components/Input.lua
FluxRegistry["Flux/Components/Input"] = function(require)
	--[[
		Components/Input — a labelled text field.
	
		Commit happens on both FocusLost and Return, and the two paths must collapse into one
		callback: on a real client Return releases focus, so an unguarded implementation fires twice
		per Enter press. A `_dirty` latch set by user keystrokes makes the second commit a no-op
		while still committing a value the engine's own focus release hands over.
	
		Numeric filtering runs inside `GetPropertyChangedSignal("Text")` rather than on commit, so
		a pasted "1e5 apples" never reaches the label; the rewrite re-enters the same signal, which
		is why the filter is wrapped in a re-entry guard instead of a plain assignment. The empty
		string is allowed through — a field mid-edit is not a field holding zero.
	
		Restore from config runs the identical coercion as a typed commit: a file edited by hand to
		`"vol": "900"` clamps to Max exactly like typing 900 would, instead of showing a value the
		slider next to it refuses to accept.
	]]
	
	local Element = require("Flux/Core/Element")
	local Instance = require("Flux/Utilities/Instance")
	local Guard = require("Flux/Utilities/Guard")
	local Math = require("Flux/Utilities/Math")
	local Signal = require("Flux/Utilities/Signal")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	
	local UserInputService = Guard.service("UserInputService")
	
	local Input = {}
	
	local BODY_W = 170
	local FIELD_H = 24
	local MULTI_H = 64
	
	function Input.new(group: any, options: {[string]: any}?)
		options = Element.options(options, {
			Name = "Input",
			Title = nil,
			Desc = nil,
			Default = "",
			Placeholder = "",
			Callback = nil,
			OnChanged = nil,
			Flag = nil,
			Numeric = false,
			Min = nil,
			Max = nil,
			LengthLimit = 0,
			Multi = false,
			Height = nil,
		})
	
		local title = options.Title or options.Name
		local maid = group.Maid
		local numeric = options.Numeric == true
		local multi = options.Multi == true
		local lower = tonumber(options.Min)
		local upper = tonumber(options.Max)
		local height = tonumber(options.Height) or (multi and MULTI_H or FIELD_H)
	
		local row = Element.row(maid, group.Content, "Input_" .. tostring(title), {
			Label = title,
			Desc = options.Desc,
			BodyWidth = BODY_W,
			Height = multi and height + 14 or nil,
			Order = group:RowCount() + 1,
		})
	
		local field = Element.panel(maid, row.Body, "Field", {
			Color = "Field",
			Radius = "RadiusField",
			Size = UDim2.fromOffset(BODY_W, height),
			Stroke = "BorderSecondary",
			ZIndex = 6,
		})
	
		local box = Instance.new("TextBox", field, {
			Name = "Box",
			Text = "",
			PlaceholderText = tostring(options.Placeholder or ""),
			BackgroundTransparency = 1,
			TextColor3 = ThemeManager.color("TextPrimary"),
			Font = ThemeManager.font(numeric and "Mono" or "Body"),
			TextSize = 12,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = multi,
			MultiLine = multi,
			ClearTextOnFocus = false,
			Size = UDim2.new(1, -10, 1, 0),
			Position = UDim2.new(0, 5, 0, 0),
			BorderSizePixel = 0,
			ZIndex = 7,
		})
		maid:giveFunction(function()
			box:Destroy()
		end)
		maid:give(ThemeManager.bind(box, "TextColor3", "TextPrimary"))
		if multi then
			-- AutomaticSize would shrink a wrapped box to one line's height and clip the rest of
			-- the paragraph, so multi-line fields opt out of it explicitly.
			box.AutomaticSize = Enum.AutomaticSize.None
			box.TextYAlignment = Enum.TextYAlignment.Top
		end
		if type(options.LengthLimit) == "number" and options.LengthLimit > 0 then
			box.MaxLength = math.floor(options.LengthLimit)
		end
		Guard.set(box, "CaretColor", ThemeManager.color("Accent"))
	
		local self = {
			Instance = row.Root,
			Title = title,
			Changed = Signal.new(),
			_value = "",
			_callback = options.Callback,
			_onChanged = options.OnChanged,
			_group = group,
			_flag = options.Flag,
			_row = row,
			_dirty = false,
		}
	
		-- Set while the component itself rewrites box.Text (numeric filtering, clamp coercion) so
		-- the keystroke listener can tell a programmatic write from the user typing.
		local internal = false
		-- Held off until after bindConfig: staging the declared default into the store before the
		-- restore runs would overwrite a loaded config the same way a push-on-build slider would.
		local canPush = false
	
		local function coerce(raw: any): string
			local text = tostring(raw == nil and "" or raw)
			if numeric then
				local cleaned = ""
				for index = 1, #text do
					local char = text:sub(index, index)
					if char:match("%d") or char == "-" or char == "." then
						cleaned = cleaned .. char
					end
				end
				text = cleaned
			end
			return text
		end
	
		local function clampNumber(text: string): (string, number?)
			local parsed = tonumber(text)
			if parsed == nil then
				return text, nil
			end
			if lower ~= nil then
				parsed = math.max(parsed, lower)
			end
			if upper ~= nil then
				parsed = math.min(parsed, upper)
			end
			return tostring(parsed), parsed
		end
	
		local function writeText(text: string)
			internal = true
			box.Text = coerce(text)
			internal = false
		end
	
		local function apply(rawValue: any, fromUser: boolean)
			local text = coerce(rawValue)
			local value: any = text
			if numeric then
				local coerced, parsed = clampNumber(text)
				if parsed == nil then
					-- An unparseable number is not zero: revert to the last value the field owned
					-- rather than quietly saving 0 over whatever the user meant to erase.
					value = self._value
					writeText(self._value)
				else
					value = parsed
					if coerced ~= text then
						writeText(coerced)
					end
				end
			end
	
			local changed = value ~= self._value
			self._value = value
			if changed then
				if canPush then
					Element.pushConfig(self._flag, value)
				end
				self.Changed:Dispatch(value)
			end
			if fromUser and changed and self._callback ~= nil then
				local ok, err = pcall(self._callback, value)
				if not ok then
					warn("[Flux] input '" .. tostring(title) .. "': " .. tostring(err))
				end
			end
			return value
		end
	
		local textChanged = Guard.get(box, "GetPropertyChangedSignal")
		if textChanged ~= nil then
			maid:giveConnection(textChanged(box, "Text"):Connect(function()
				if internal or self.Destroyed then
					return
				end
				-- Rewriting Text from inside this handler re-enters it, so the guard is set before
				-- the filtered write and cleared after.
				local filtered = coerce(box.Text)
				if filtered ~= box.Text then
					internal = true
					box.Text = filtered
					internal = false
				end
				self._dirty = true
				if self._onChanged ~= nil then
					local ok, err = pcall(self._onChanged, filtered)
					if not ok then
						warn("[Flux] input '" .. tostring(title) .. "': " .. tostring(err))
					end
				end
			end))
		end
	
		local function commit()
			if self.Destroyed or not self._dirty then
				return
			end
			self._dirty = false
			apply(box.Text, true)
		end
	
		local focusLost = Guard.get(box, "FocusLost")
		if focusLost ~= nil then
			maid:giveConnection(focusLost:Connect(function(_enter: boolean)
				commit()
			end))
		end
	
		local beganSignal = UserInputService ~= nil and Guard.get(UserInputService, "InputBegan") or nil
		if beganSignal ~= nil then
			maid:giveConnection(beganSignal:Connect(function(input)
				if self.Destroyed or not self._dirty then
					return
				end
				if Guard.get(input, "KeyCode") ~= Enum.KeyCode.Return then
					return
				end
				local getter = Guard.get(UserInputService, "GetFocusedTextBox")
				if getter ~= nil then
					local ok, focused = pcall(function()
						return UserInputService:GetFocusedTextBox()
					end)
					if not ok or focused ~= box then
						return
					end
				end
				commit()
				local release = Guard.get(box, "ReleaseFocus")
				if release ~= nil then
					pcall(function()
						box:ReleaseFocus()
					end)
				end
			end))
		end
	
		-- Methods live on the table as fields (the internal style of this library) while hosts call
		-- them with a colon. Accept both: when the first argument is the widget itself, the real
		-- argument is the one behind it.
		local function recv(a: any, b: any): any
			if a == self then
				return b
			end
			return a
		end
	
		self.Set = function(a: any, b: any)
			if self.Destroyed then
				return self
			end
			local value = recv(a, b)
			writeText(value)
			apply(box.Text, false)
			return self
		end
	
		self.SetValue = self.Set
	
		self.GetText = function()
			return box.Text
		end
	
		self.GetValue = function()
			return self._value
		end
	
		self.Focus = function()
			local capture = Guard.get(box, "CaptureFocus")
			if capture ~= nil then
				pcall(function()
					box:CaptureFocus()
				end)
			end
			return self
		end
	
		self.Blur = function()
			local release = Guard.get(box, "ReleaseFocus")
			if release ~= nil then
				pcall(function()
					box:ReleaseFocus()
				end)
			end
			return self
		end
	
		self.SetText = function(a: any, b: any)
			self.Title = tostring(recv(a, b))
			row.Title.Text = self.Title
			return self
		end
		self.SetTitle = self.SetText
	
		self.SetVisible = function(a: any, b: any)
			row.Root.Visible = recv(a, b) == true
			return self
		end
	
		self.OnFilter = function(a: any, b: any)
			row.Root.Visible = recv(a, b) == true
		end
	
		self.Destroy = function()
			if self.Destroyed then
				return
			end
			self.Destroyed = true
			self.Changed:Destroy()
			Element.releaseSearch(group, self)
			row.Root:Destroy()
		end
	
		writeText(options.Default)
		self._value = apply(box.Text, false)
	
		Element.bindConfig(maid, self._flag, function(value)
			if not self.Destroyed then
				writeText(value)
				apply(box.Text, false)
			end
		end, function()
			return self._value
		end)
		canPush = true
	
		self.SearchId = Element.searchable(group, self, tostring(title), options.Desc)
		Guard.set(row.Root, "LayoutOrder", group:RowCount())
		return self
	end
	
	return Input
end

-- src/Components/Keybind.lua
FluxRegistry["Flux/Components/Keybind"] = function(require)
	--[[
		Components/Keybind — a rebindable key row built entirely on Systems/InputManager.
	
		The row owns no input hooks of its own: every trigger goes through one InputManager binding,
		so chords, the typed-TextBox filter, auto-repeat latching and focus-loss release behave exactly
		like the binds a host registers itself. Clicking the row opens the manager's capture session
		(Escape cancels, Delete clears per the session's own ClearOnDelete rule), and the resolved
		payload — an Enum member plus the modifier set at the moment of the press — is written back
		through the binding's own Set.
	
		Hold rows are pulled, not pushed. The manager only reports a falling edge when the engine
		surfaces InputEnded, and that edge is missing whenever the window loses focus with the key
		down — so a hold row registers its binding *without* a callback and reads `GetState()` from
		ONE shared RenderStepped pass that serves every keybind row in the hub. A hub with sixty
		keybinds costs one connection and sixty polls per frame, never sixty coroutines.
	
		Toggle rows are the opposite: the pushed rising edge is exactly the semantics wanted, so the
		binding's Callback forwards straight to the host. Neither style ever calls the host callback
		because a bind was (re)set — capture, Set and a config restore change the trigger, not the
		feature state.
	
		The config value is a plain string ("Q", "Shift+K", "MouseButton2") — never a UserInput object,
		never an Enum member — so a file written today decodes tomorrow, and restoring hands the name
		back to the manager, which is the only place enum resolution lives.
	]]
	
	local Element = require("Flux/Core/Element")
	local Instance = require("Flux/Utilities/Instance")
	local Guard = require("Flux/Utilities/Guard")
	local Signal = require("Flux/Utilities/Signal")
	local String = require("Flux/Utilities/String")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	local InputManager = require("Flux/Systems/InputManager")
	
	local RunService = Guard.service("RunService")
	
	local Keybind = {}
	
	local CHIP_W = 74
	local CHIP_H = 24
	
	-- The row's whole UI budget stays inside the library's 25-instance ceiling (spec 14 counts it).
	
	--[[ shared hold loop ------------------------------------------------------------
	
		One RenderStepped connection for every keybind row, opened with the first hold row and
		closed again when the last one is destroyed — the same lifecycle LayoutManager uses for its
		poll. `frames` counts passes so a spec can prove N rows cost one poll per frame, not N
		connections each firing their own callback. ]]
	
	local pollers: {any} = {}
	local pollConnection = nil
	local frames = 0
	
	local function runFrame()
		frames += 1
		local index = 1
		while index <= #pollers do
			local row = pollers[index]
			if row.Destroyed then
				-- A destroyed row drops itself even if Destroy's removal was missed (a row torn
				-- down from inside another row's callback, for instance).
				table.remove(pollers, index)
			else
				local down = row._binding ~= nil and row._binding:GetState() or false
				if down ~= row._lastState then
					row._lastState = down
					row._edge(down)
				end
				index += 1
			end
		end
	end
	
	local function addPoller(row: any)
		for _, existing in ipairs(pollers) do
			if existing == row then
				return
			end
		end
		table.insert(pollers, row)
		if pollConnection == nil and RunService ~= nil then
			pollConnection = RunService.RenderStepped:Connect(runFrame)
		end
	end
	
	local function removePoller(row: any)
		for index = #pollers, 1, -1 do
			if pollers[index] == row then
				table.remove(pollers, index)
			end
		end
		if #pollers == 0 and pollConnection ~= nil then
			pollConnection:Disconnect()
			pollConnection = nil
		end
	end
	
	--- How many hold rows the shared frame loop is currently polling.
	function Keybind.pollerCount(): number
		return #pollers
	end
	
	--- Whether the shared RenderStepped connection is live.
	function Keybind.loopRunning(): boolean
		return pollConnection ~= nil
	end
	
	--- Frame passes so far, so a spec can show the loop runs ONCE per frame for any row count.
	function Keybind.pollFrames(): number
		return frames
	end
	
	--[[ trigger parsing --------------------------------------------------------------
	
		Displayed short names are accepted back as input (String.keyName prints MB2, the row must
		take "MB2"), and full Left/Right modifier spellings collapse onto the manager's three
		modifier tokens. A bare bind stores the plain enum name; chords store "Shift+K" style.
		Empty tokens are malformed ("+K", "Shift+") and rejected rather than bound to nothing; a
		whitespace-only value means "clear the bind". ]]
	
	local MOD_ORDER = { "Ctrl", "Shift", "Alt" }
	local MOD_ALIASES = {
		ctrl = "Ctrl", control = "Ctrl", leftcontrol = "Ctrl", rightcontrol = "Ctrl",
		shift = "Shift", leftshift = "Shift", rightshift = "Shift",
		alt = "Alt", leftalt = "Alt", rightalt = "Alt",
	}
	local KEY_ALIASES = {
		mb1 = "MouseButton1", mb2 = "MouseButton2", mb3 = "MouseButton3",
	}
	-- A lone modifier word in the key slot binds the physical left-hand key: the Enum has no
	-- "Ctrl" member, so handing the bare word to the manager would store an inert trigger.
	local MOD_KEY_NAMES = {
		ctrl = "LeftControl", control = "LeftControl",
		shift = "LeftShift",
		alt = "LeftAlt",
	}
	
	--- Returns (key, mods) for a bindable spelling, or (nil, nil) when it is not one. `key` is the
	--- raw enum name handed to the manager's binding, `mods` the chord words folded onto the
	--- manager's three modifier tokens.
	local function parseString(value: string): (string?, {[string]: boolean}?)
		local tokens = {}
		for _, raw in ipairs(String.split(value, "+")) do
			local token = String.trim(raw)
			if token == "" then
				return nil, nil
			end
			table.insert(tokens, token)
		end
		if #tokens > 4 then
			return nil, nil
		end
	
		local mods = {}
		for index = 1, #tokens - 1 do
			local mod = MOD_ALIASES[tokens[index]:lower()]
			if mod == nil then
				return nil, nil
			end
			mods[mod] = true
		end
	
		-- A lone modifier word still binds *something* (the physical left key), unlike the chord
		-- prefix slot where "Shift+Shift" would be nonsense the manager could not match.
		local key = tokens[#tokens]
		local lower = key:lower()
		local alias = KEY_ALIASES[lower] or MOD_KEY_NAMES[lower]
		if alias ~= nil then
			key = alias
		end
		return key, mods
	end
	
	--- The config/display spelling: canonical modifier words first, then the raw key name.
	local function serialize(key: string, mods: {[string]: boolean}?): string
		local parts = {}
		for _, mod in ipairs(MOD_ORDER) do
			if mods ~= nil and mods[mod] then
				table.insert(parts, mod)
			end
		end
		table.insert(parts, key)
		return table.concat(parts, "+")
	end
	
	--- Normalise any accepted trigger form to (stored, key, mods). Non-empty third result means
	--- the value is not bindable at all and the row must keep what it had.
	local function normalize(value: any): (string?, string?, {[string]: boolean}?, boolean?)
		if value == nil then
			return nil, nil, nil, nil
		end
	
		if type(value) == "string" then
			if String.trim(value) == "" then
				-- An empty config value is "no bind", not "a bind the row refuses to show".
				return nil, nil, nil, nil
			end
			local key, mods = parseString(value)
			if key == nil then
				return nil, nil, nil, true
			end
			return serialize(key, mods), key, mods, nil
		end
	
		-- A live EnumItem on a real client is userdata; the offline harness models one as a table.
		-- Both shapes are identified by their string Name, which is also what a config stores, and
		-- a restored { Name = "MouseButton1", Enum = "UserInputType" } entry carries the same Name.
		if typeof(value) == "EnumItem" or type(value) == "table" then
			local name = Guard.get(value, "Name")
			if type(name) == "string" and name ~= "" then
				local key, mods = parseString(name)
				if key ~= nil then
					return serialize(key, mods), key, mods, nil
				end
				return name, name, {}, nil
			end
		end
	
		return nil, nil, nil, true
	end
	
	function Keybind.new(group: any, options: {[string]: any}?)
		options = Element.options(options, {
			Name = "Keybind",
			Title = nil,
			Desc = nil,
			Default = nil,
			Hold = false,
			Callback = nil,
			Flag = nil,
			ClearOnDelete = true,
			Prompt = "Press a key…",
			AllowWhileTyping = false,
		})
	
		local title = options.Title or options.Name
		local maid = group.Maid
		local hold = options.Hold == true
	
		local row = Element.row(maid, group.Content, "Keybind_" .. tostring(title), {
			Label = title,
			Desc = options.Desc,
			BodyWidth = CHIP_W,
			Order = group:RowCount() + 1,
		})
	
		-- A TextButton, not a Frame: an unparented or Active=false frame never reports clicks on a
		-- real client, and the chip — like Toggle's HitArea — must be clickable wherever the row is.
		local chip = Instance.new("TextButton", row.Body, {
			Name = "Chip",
			Text = "",
			AutoButtonColor = false,
			BackgroundTransparency = 0,
			BorderSizePixel = 0,
			Size = UDim2.fromOffset(CHIP_W, CHIP_H),
			ZIndex = 7,
		})
		maid:giveFunction(function()
			chip:Destroy()
		end)
		Element.round(maid, chip, "RadiusChip")
	
		local chipStroke = Instance.stroke(
			chip,
			ThemeManager.color("BorderSecondary"),
			ThemeManager.metric("StrokeThickness") or 1
		)
		if chipStroke ~= nil then
			maid:giveFunction(function()
				chipStroke:Destroy()
			end)
		end
	
		local chipText = Element.label(maid, chip, "Text", {
			Text = "Unbound",
			Role = "TextMuted",
			Font = "Mono",
			TextSize = 11,
			Size = UDim2.new(1, -8, 1, 0),
			Position = UDim2.new(0, 4, 0, 0),
			ZIndex = 8,
		})
	
		-- The whole row opens the capture, not just the 74px chip: on the reference layout the chip
		-- is a read-out, and hunting it with a thumb on a phone is the usual complaint. The hit
		-- layer sits above the chip (Toggle's row does the same) — both buttons call the same
		-- latched beginCapture, so a client that delivers the click to either gets identical state.
		local hit = Instance.new("TextButton", row.Root, {
			Name = "HitArea",
			Text = "",
			AutoButtonColor = false,
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			ZIndex = 9,
			BorderSizePixel = 0,
		})
		maid:giveFunction(function()
			hit:Destroy()
		end)
	
		local self = {
			Instance = row.Root,
			Title = title,
			Changed = Signal.new(),
			Hold = hold,
			_value = nil,
			_binding = nil,
			_capturing = false,
			_session = nil,
			_lastState = false,
			_callback = options.Callback,
			_maid = maid,
			_group = group,
			_flag = options.Flag,
			_row = row,
		}
	
		local function paint()
			-- Idle and capture differ in text and role through Element.tint, so a theme swap while
			-- a capture is open repaints onto the capture roles, not the resting palette.
			if self._capturing then
				chipText.Text = tostring(options.Prompt)
				Element.tint(maid, chipText, "TextColor3", "Accent")
				if chipStroke ~= nil then
					Element.tint(maid, chipStroke, "Color", "Accent")
				end
				Element.tint(maid, chip, "BackgroundColor3", "Selection")
			else
				chipText.Text = self._binding ~= nil and self._binding:GetLabel() or "Unbound"
				if self._value == nil then
					Element.tint(maid, chipText, "TextColor3", "TextMuted")
				else
					Element.tint(maid, chipText, "TextColor3", "TextSecondary")
				end
				if chipStroke ~= nil then
					Element.tint(maid, chipStroke, "Color", "BorderSecondary")
				end
				Element.tint(maid, chip, "BackgroundColor3", "Field")
			end
		end
	
		local function runCallback(state: boolean)
			if self._callback == nil then
				return
			end
			local ok, err = pcall(self._callback, state)
			if not ok then
				warn("[Flux] keybind '" .. tostring(title) .. "': " .. tostring(err))
			end
		end
	
		-- The frame loop's only per-row work: hand a polled edge to the host. Toggle rows never
		-- enter it; their edges arrive pushed through the manager's own Callback.
		self._edge = function(state: boolean)
			if not self.Destroyed then
				runCallback(state)
			end
		end
	
		--- Rebuild the manager binding for the current trigger. Destroy-and-replace rather than
		--- handle.Set because clearing must also drop the manager's `held` latch: a handle has no
		--- way to forget its input, and a stale one would keep matching presses.
		local function attach(key: string?, mods: {[string]: boolean}?)
			if self._binding ~= nil then
				self._binding:Destroy()
			end
			local spec = {
				Name = self._flag or tostring(title),
				Mode = hold and "hold" or "toggle",
				AllowWhileTyping = options.AllowWhileTyping == true,
			}
			-- A hold bind is registered *without* a Callback on purpose: the manager's pushed
			-- edges and the frame loop's polled ones would otherwise double-fire the host
			-- (spec 14 counts the calls). `and nil or` would not express that — `true and nil`
			-- falls through to the function — so the field is set only for the toggle mode.
			if not hold then
				spec.Callback = function(state)
					if not self.Destroyed then
						runCallback(state)
					end
				end
			end
			self._binding = InputManager.bind(spec)
			if key ~= nil then
				self._binding:Set(key, mods)
			end
			self._lastState = false
		end
	
		local function apply(stored: string?, key: string?, mods: {[string]: boolean}?, silent: boolean?): boolean
			if stored == self._value then
				return true
			end
			self._value = stored
			attach(key, mods)
			paint()
			if not silent then
				Element.pushConfig(self._flag, self._value)
				self.Changed:Dispatch(self._value)
			end
			return true
		end
	
		local function setTrigger(value: any, silent: boolean?): boolean
			if self.Destroyed then
				return false
			end
			local stored, key, mods, rejected = normalize(value)
			if rejected then
				-- A trigger this client cannot resolve never lands: the row keeps its old bind
				-- rather than showing a key it will not react to.
				return false
			end
			return apply(stored, key, mods, silent)
		end
	
		local function endCapture()
			if not self._capturing then
				return
			end
			self._capturing = false
			self._session = nil
			paint()
		end
	
		local function beginCapture()
			if self.Destroyed or self._capturing then
				return self
			end
			self._capturing = true
			paint()
	
			local session = InputManager.capture({
				ClearOnDelete = options.ClearOnDelete,
				OnCancel = endCapture,
			})
			self._session = session
			session.Done:Connect(function(payload: {[string]: any}?)
				if payload == nil then
					return
				end
				if payload.cancelled then
					-- Escape, a timeout, or the manager refusing a second concurrent session:
					-- every cancelled path leaves the previous trigger standing, untouched.
					endCapture()
					return
				end
				if payload.cleared then
					endCapture()
					setTrigger(nil)
					return
				end
				if payload.input ~= nil then
					-- Rebuild the stored spelling from the resolved Enum member plus the modifier
					-- snapshot the manager took at the moment of the press: capture is the only
					-- path that can produce a chord, so the chord words are written from
					-- payload.mods directly rather than re-read from the keyboard.
					local capturedStored, capturedKey = normalize(payload.input)
					local names = {}
					local mods = {}
					if payload.mods ~= nil then
						for _, mod in ipairs(MOD_ORDER) do
							if payload.mods[mod] == true then
								table.insert(names, mod)
								mods[mod] = true
							end
						end
					end
					if capturedKey ~= nil then
						table.insert(names, capturedStored)
						endCapture()
						apply(table.concat(names, "+"), capturedKey, mods)
					else
						endCapture()
					end
				end
			end)
			return self
		end
	
		chip.MouseButton1Click:Connect(function()
			beginCapture()
		end)
		hit.MouseButton1Click:Connect(function()
			beginCapture()
		end)
	
		-- Methods live on the table as fields while hosts call them with a colon; accept both, the
		-- way Slider and Dropdown do.
		local function recv(a: any, b: any): any
			if a == self then
				return b
			end
			return a
		end
	
		self.Set = function(a: any, b: any)
			if self._capturing then
				-- A programmatic rebind closes an open capture: the picker would otherwise resolve
				-- later and overwrite the trigger the host just wrote.
				if self._session ~= nil then
					self._session.Cancel()
				end
				endCapture()
			end
			local value = recv(a, b)
			if not setTrigger(value) then
				return false
			end
			return self
		end
	
		self.Clear = function(a: any, b: any)
			setTrigger(nil)
			return self
		end
	
		self.GetValue = function()
			return self._value
		end
	
		self.GetTrigger = function()
			return self._value
		end
	
		self.GetLabel = function()
			if self._binding ~= nil then
				return self._binding:GetLabel()
			end
			return "Unbound"
		end
	
		self.GetBinding = function()
			return self._binding
		end
	
		--- Live "is the key down right now" poll, straight through to the manager (chord included).
		self.GetState = function()
			if self._binding == nil then
				return false
			end
			return self._binding:GetState()
		end
	
		self.IsCapturing = function()
			return self._capturing
		end
	
		self.StartCapture = function(a: any, b: any)
			beginCapture()
			return self
		end
	
		self.CancelCapture = function(a: any, b: any)
			if self._session ~= nil then
				self._session.Cancel()
			end
			endCapture()
			return self
		end
	
		self.SetCallback = function(a: any, b: any)
			self._callback = recv(a, b)
			return self
		end
	
		self.SetText = function(a: any, b: any)
			self.Title = tostring(recv(a, b))
			row.Title.Text = self.Title
			return self
		end
		self.SetTitle = self.SetText
	
		self.SetVisible = function(a: any, b: any)
			row.Root.Visible = recv(a, b) == true
			return self
		end
	
		self.OnFilter = function(a: any, b: any)
			local matched = recv(a, b)
			if matched ~= true then
				self:CancelCapture()
			end
			row.Root.Visible = matched == true
		end
	
		self.Destroy = function()
			if self.Destroyed then
				return
			end
			if self._session ~= nil then
				self._session.Cancel()
			end
			endCapture()
			self.Destroyed = true
			removePoller(self)
			if self._binding ~= nil then
				self._binding:Destroy()
				self._binding = nil
			end
			self.Changed:Destroy()
			Element.releaseSearch(group, self)
			row.Root:Destroy()
		end
	
		-- The default trigger is staged, not pushed: bindConfig below applies a restored value on
		-- top of it, and pushing now would stamp the default over a config that was just loaded.
		local defaultStored, defaultKey, defaultMods, defaultRejected = normalize(options.Default)
		if defaultRejected then
			warn("[Flux] keybind '" .. tostring(title) .. "': default " .. tostring(options.Default) .. " is not bindable")
		end
		self._value = defaultStored
		attach(defaultKey, defaultMods)
		if hold then
			addPoller(self)
		end
		paint()
	
		-- Restoring is silent all the way down: a load pushes every flag at once, and a hub that
		-- rebuilds on Changed would thrash forty times for one file read. No callback either.
		Element.bindConfig(maid, self._flag, function(value)
			if not self.Destroyed then
				setTrigger(value, true)
			end
		end, function()
			return self._value
		end)
	
		self.SearchId = Element.searchable(group, self, tostring(title), options.Desc)
		Guard.set(row.Root, "LayoutOrder", group:RowCount())
		return self
	end
	
	return Keybind
end

-- src/Components/Label.lua
FluxRegistry["Flux/Components/Label"] = function(require)
	--[[
		Components/Label — a title/value readout row a script owns.
	
		The row shape of Toggle/Slider with no control on the right: just a value the host pushes
		with `SetValue`, right-aligned in the mono font the numeric readouts already use. It is the
		only member of the family with no user interaction — nothing to click, no callback — but it
		still persists, because a readout like "current profile" or "session FPS target" is config
		the user expects to survive a restart, and `Flag` is how the rest of the library says that.
	
		Values render through a documented format, never raw `tostring`: `tostring(0.1 + 0.2)` puts
		float dust on the screen, and a readout is the one place a user actually reads the digits.
		Numbers go through `Format` (a `string.format` pattern, `%g` by default) and every rendered
		value gets `Suffix` appended; `nil` clears the slot.
	]]
	
	local Element = require("Flux/Core/Element")
	local Guard = require("Flux/Utilities/Guard")
	local Signal = require("Flux/Utilities/Signal")
	
	local Label = {}
	
	--- Script-facing colour states. `accent` is the one that moves with a theme preset, which is
	--- how a live readout stays the hub's colour instead of a frozen hex from build time.
	local STATES = {
		normal = "TextSecondary",
		good = "Success",
		warn = "Warning",
		bad = "Error",
		info = "Info",
		accent = "Accent",
	}
	
	function Label.new(group: any, options: {[string]: any}?)
		options = Element.options(options, {
			Name = "Label",
			Title = nil,
			Text = nil,
			Desc = nil,
			Value = nil,
			Flag = nil,
			Role = nil,
			State = nil,
			Format = "%g",
			Suffix = "",
			BodyWidth = nil,
		})
	
		local title = options.Title or options.Text or options.Name
		local maid = group.Maid
		local role = options.Role or STATES[options.State or "normal"] or "TextSecondary"
	
		local row = Element.row(maid, group.Content, "Label_" .. tostring(title), {
			Label = title,
			Desc = options.Desc,
			BodyWidth = options.BodyWidth or 110,
			Order = group:RowCount() + 1,
		})
	
		local readout = Element.label(maid, row.Body, "Value", {
			Text = "",
			Role = role,
			Font = "Mono",
			TextSize = 12,
			Alignment = Enum.TextXAlignment.Right,
			AutoWidth = true,
			ZIndex = 6,
		})
	
		local self = {
			Instance = row.Root,
			Title = title,
			Changed = Signal.new(),
			_value = nil,
			_role = role,
			_state = options.State or "normal",
			_maid = maid,
			_group = group,
			_flag = options.Flag,
			_row = row,
		}
	
		local function render(value: any)
			local text
			local num = tonumber(value)
			if num ~= nil and type(value) ~= "boolean" then
				text = string.format(options.Format or "%g", num)
			else
				text = tostring(value)
			end
			readout.Text = text .. (options.Suffix or "")
		end
	
		local function apply(value: any, push: boolean?)
			if self.Destroyed then
				return self
			end
			local changed = value ~= self._value
			self._value = value
	
			if value == nil then
				readout.Text = ""
			else
				render(value)
			end
	
			if changed then
				if push then
					Element.pushConfig(self._flag, value)
				end
				self.Changed:Dispatch(value)
			end
			return self
		end
	
		-- Staged without pushing (the Slider rule): a config restored later must not lose the
		-- file's value to the default this label was declared with.
		self._value = options.Value
		if options.Value ~= nil then
			render(options.Value)
		end
	
		self.SetValue = function(a: any, b: any)
			local value = a
			if a == self then
				value = b
			end
			return apply(value, true)
		end
	
		self.Set = self.SetValue
	
		self.GetValue = function()
			return self._value
		end
	
		self.SetState = function(a: any, b: any)
			local name = a
			if a == self then
				name = b
			end
			local nextRole = STATES[name]
			if nextRole == nil then
				warn("[Flux] label '" .. tostring(title) .. "': no state named " .. tostring(name))
				return self
			end
			self._state = name
			self._role = nextRole
			Element.tint(maid, readout, "TextColor3", nextRole)
			return self
		end
	
		self.GetState = function()
			return self._state
		end
	
		self.SetCallback = function()
			-- A label has no user interaction to report; the Changed signal is the hook.
			warn("[Flux] label '" .. tostring(title) .. "': a readout has no callback, use :Changed:Connect")
			return self
		end
	
		self.SetTitle = function(a: any, b: any)
			local text = a
			if a == self then
				text = b
			end
			self.Title = tostring(text)
			row.Title.Text = self.Title
			return self
		end
	
		self.SetVisible = function(a: any, b: any)
			local visible = a
			if a == self then
				visible = b
			end
			row.Root.Visible = visible == true
			return self
		end
	
		self.OnFilter = function(a: any, b: any)
			local matched = a
			if a == self then
				matched = b
			end
			row.Root.Visible = matched == true
		end
	
		self.Destroy = function()
			if self.Destroyed then
				return
			end
			self.Destroyed = true
			self.Changed:Destroy()
			Element.releaseSearch(group, self)
			row.Root:Destroy()
		end
	
		Element.bindConfig(maid, self._flag, function(value)
			apply(value)
		end, function()
			return self._value
		end)
	
		self.SearchId = Element.searchable(group, self, tostring(title), options.Desc)
		Guard.set(row.Root, "LayoutOrder", group:RowCount())
		return self
	end
	
	return Label
end

-- src/Components/Paragraph.lua
FluxRegistry["Flux/Components/Paragraph"] = function(require)
	--[[
		Components/Paragraph — a wrapping text block inside a group.
	
		A settings page needs prose: a disclaimer, a key hint, a short explanation under a section
		title. Paragraph is the row shape with the interactivity removed — no body control, no
		callback, nothing to click — and an explicit height, because the row auto-sizing a hub
		trusts (AutomaticSize) is exactly the mechanism a weak executor resolves last: a paragraph
		that grows a frame late overlaps whatever sits under it, and a clipped one silently loses
		sentences. So the block measures its own text and writes its own height.
	
		The measurement is a character-count estimate — none of the target clients answer a text
		metrics query off-screen reliably — with `Width` as the assumed wrap column. It errs wide:
		one extra line of breathing room costs a few pixels, a clipped word costs the message.
		Nothing in this row sets `ClipsDescendants`, so a bad estimate loses whitespace, never text.
	]]
	
	local Element = require("Flux/Core/Element")
	local Guard = require("Flux/Utilities/Guard")
	
	local Paragraph = {}
	
	local PAD = 8
	local TITLE_H = 18
	
	--- Wrapped line count for one segment against an assumed character column.
	local function measureLines(text: string, maxChars: number): number
		local total = 0
		local rest = text
		while true do
			local nl = rest:find("\n", 1, true)
			local segment = rest
			if nl ~= nil then
				segment = rest:sub(1, nl - 1)
				rest = rest:sub(nl + 1)
			else
				rest = ""
			end
	
			local lines = 1
			local used = 0
			for word in segment:gmatch("%S+") do
				local width = #word + (used > 0 and 1 or 0)
				if used + width > maxChars then
					lines += 1
					used = #word
				else
					used += width
				end
			end
			total += lines
	
			if nl == nil then
				break
			end
		end
		return math.max(total, 1)
	end
	
	function Paragraph.new(group: any, options: {[string]: any}?)
		options = Element.options(options, {
			Name = "Paragraph",
			Title = nil,
			Text = "",
			Role = "TextSecondary",
			Size = 12,
			Width = 320,
		})
	
		local maid = group.Maid
		local lineH = options.Size + 4
		local hasTitle = type(options.Title) == "string" and options.Title ~= ""
		local maxChars = math.max(12, math.floor((tonumber(options.Width) or 320) / (options.Size * 0.55)))
	
		local root = Element.panel(maid, group.Content, "Paragraph_" .. tostring(options.Name), {
			Transparency = 1,
			Size = UDim2.new(1, 0, 0, PAD * 2),
			LayoutOrder = group:RowCount() + 1,
			ZIndex = 5,
		})
	
		local titleNode = nil
		if hasTitle then
			titleNode = Element.label(maid, root, "Title", {
				Text = options.Title,
				Role = "TextPrimary",
				Font = "Title",
				TextSize = 13,
				Size = UDim2.new(1, 0, 0, TITLE_H),
				Position = UDim2.new(0, 0, 0, PAD - 4),
				ZIndex = 6,
			})
		end
	
		local body = Element.label(maid, root, "Body", {
			Text = "",
			Role = options.Role,
			TextSize = options.Size,
			Wrap = true,
			Vertical = Enum.TextYAlignment.Top,
			Size = UDim2.new(1, 0, 0, lineH),
			Position = UDim2.new(0, 0, 0, PAD + (hasTitle and TITLE_H or 0)),
			ZIndex = 6,
		})
	
		local self = {
			Instance = root,
			Title = hasTitle and options.Title or tostring(options.Name),
			_maid = maid,
			_group = group,
			_text = "",
			_lines = 1,
		}
	
		local function relayout(text: string): number
			local lines = measureLines(text, maxChars)
			body.Text = text
			self._lines = lines
			root.Size = UDim2.new(1, 0, 0, PAD * 2 + (hasTitle and TITLE_H or 0) + lines * lineH)
			return lines
		end
	
		self.SetText = function(a: any, b: any)
			local value = a
			if a == self then
				value = b
			end
			if self.Destroyed then
				return self
			end
			self._text = tostring(value)
			relayout(self._text)
			return self
		end
	
		self.Set = self.SetText
	
		self.GetText = function()
			return self._text
		end
	
		self.GetValue = self.GetText
	
		--- How many wrapped lines the current text occupies — the number the height was built from,
		--- exposed so a host (and a spec) can prove the block tracks its content.
		self.LineCount = function()
			return self._lines
		end
	
		self.SetTitle = function(a: any, b: any)
			local value = a
			if a == self then
				value = b
			end
			self.Title = tostring(value)
			if titleNode ~= nil then
				titleNode.Text = self.Title
			end
			return self
		end
	
		self.SetVisible = function(a: any, b: any)
			local visible = a
			if a == self then
				visible = b
			end
			root.Visible = visible == true
			return self
		end
	
		-- Groupbox fires this plain (`row.OnFilter(isMatch)`) and a host with a colon, so the flag
		-- arrives in either position; the shim reads whichever one carries it.
		self.OnFilter = function(a: any, b: any)
			local matched = a
			if a == self then
				matched = b
			end
			root.Visible = matched == true
		end
	
		self.Destroy = function()
			if self.Destroyed then
				return
			end
			self.Destroyed = true
			Element.releaseSearch(group, self)
			root:Destroy()
		end
	
		self.SetText(options.Text)
		self.SearchId = Element.searchable(group, self, tostring(self.Title), options.Text)
		Guard.set(root, "LayoutOrder", group:RowCount())
		return self
	end
	
	return Paragraph
end

-- src/Components/ProgressBar.lua
FluxRegistry["Flux/Components/ProgressBar"] = function(require)
	--[[
		Components/ProgressBar — a determinate fill row.
	
		The readout half of a Slider: same rail, same accent fill, none of the drag surface — the
		number is written by a script (a download, a cooldown, a sweep counter), never by the
		pointer, so there is one rule instead of a hit test: every value lands clamped into
		[Min, Max], and anything that is not a number is refused with a warn rather than
		silently coercing the bar to one end. A host typo that painted "50%" at full would be
		unfindable.
	
		The fill tweens, and only when something changed: a row that existed at Min and was
		declared at 40% paints instantly (the Toggle rule — an entrance tween on a value the user
		never saw move reads as the hub acting by itself), and an idle bar costs no frame time,
		because AnimationManager's loop only exists while a tween is running.
	]]
	
	local Element = require("Flux/Core/Element")
	local Instance = require("Flux/Utilities/Instance")
	local Guard = require("Flux/Utilities/Guard")
	local Math = require("Flux/Utilities/Math")
	local Signal = require("Flux/Utilities/Signal")
	local AnimationManager = require("Flux/Systems/AnimationManager")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	
	local ProgressBar = {}
	
	local BODY_W = 150
	local BODY_H = 28
	local TRACK_H = 6
	
	function ProgressBar.new(group: any, options: {[string]: any}?)
		options = Element.options(options, {
			Name = "ProgressBar",
			Title = nil,
			Desc = nil,
			Min = 0,
			Max = 1,
			Default = 0,
			Text = nil,
			ShowValue = true,
			Flag = nil,
			Callback = nil,
		})
	
		local title = options.Title or options.Name
		local maid = group.Maid
		local lower = tonumber(options.Min) or 0
		local upper = tonumber(options.Max) or 1
		if upper < lower then
			lower, upper = upper, lower
		end
	
		local row = Element.row(maid, group.Content, "Progress_" .. tostring(title), {
			Label = title,
			Desc = options.Desc,
			BodyWidth = BODY_W,
			Order = group:RowCount() + 1,
		})
	
		local gauge = Instance.new("Frame", row.Body, {
			Name = "Gauge",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.fromOffset(BODY_W, BODY_H),
			ZIndex = 5,
		})
		maid:giveFunction(function()
			gauge:Destroy()
		end)
		local gaugeList = Instance.new("UIListLayout", gauge, {
			FillDirection = Enum.FillDirection.Vertical,
			VerticalAlignment = Enum.VerticalAlignment.Bottom,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 3),
		})
		maid:giveFunction(function()
			gaugeList:Destroy()
		end)
	
		local readout = nil
		if options.ShowValue ~= false then
			readout = Element.label(maid, gauge, "Value", {
				Text = "",
				Role = "TextSecondary",
				Font = "Mono",
				TextSize = 11,
				Alignment = Enum.TextXAlignment.Right,
				Size = UDim2.new(1, 0, 0, 12),
				LayoutOrder = 0,
				ZIndex = 6,
			})
		end
	
		local track = Element.panel(maid, gauge, "Track", {
			Color = "Chip",
			Radius = "RadiusPill",
			Size = UDim2.new(1, 0, 0, TRACK_H),
			LayoutOrder = 1,
			ZIndex = 6,
		})
	
		local fill = Element.panel(maid, track, "Fill", {
			Color = "Accent",
			Radius = "RadiusPill",
			Size = UDim2.fromScale(0, 1),
			ZIndex = 7,
		})
	
		-- The thin rail is the whole readout; only its ink follows the theme.
		maid:give(ThemeManager.bindFn(function(tokens)
			local color = tokens.colors.Accent
			if color ~= nil then
				fill.BackgroundColor3 = color
			end
		end, { "Accent" }))
	
		local self = {
			Instance = row.Root,
			Title = title,
			Changed = Signal.new(),
			_value = lower,
			_callback = options.Callback,
			_maid = maid,
			_group = group,
			_flag = options.Flag,
			_row = row,
		}
	
		local function format(value: number, frac: number): string
			local pct = math.floor(frac * 100 + 0.5)
			if type(options.Text) == "function" then
				local ok, out = pcall(options.Text, value, frac, pct)
				if ok and out ~= nil then
					return tostring(out)
				end
				warn("[Flux] progress '" .. tostring(title) .. "': text callback failed, showing percent")
				return pct .. "%"
			end
			if type(options.Text) == "string" and options.Text:find("%%d", 1, false) ~= nil then
				local ok, out = pcall(string.format, options.Text, pct)
				if ok then
					return out
				end
				warn("[Flux] progress '" .. tostring(title) .. "': bad format pattern, showing percent")
				return pct .. "%"
			end
			if type(options.Text) == "string" and options.Text ~= "" then
				return options.Text
			end
			return pct .. "%"
		end
	
		local function paint(value: number, animate: boolean?)
			local span = upper - lower
			local frac = 0
			if span > 0 then
				frac = Math.clamp((value - lower) / span, 0, 1)
			end
			local goal = UDim2.fromScale(frac, 1)
			if animate then
				AnimationManager.to(fill, { Size = goal }, { Duration = 0.25, Easing = "outQuint" })
			else
				fill.Size = goal
			end
			if readout ~= nil then
				readout.Text = format(value, frac)
			end
		end
	
		-- `silent` is the config-restore path: the value lands, the bar snaps to it, and neither the
		-- host callback nor a tween fires — a page re-entering must not animate numbers the user
		-- never saw move.
		local function set(rawValue: any, silent: boolean?)
			if self.Destroyed then
				return self
			end
			local value = tonumber(rawValue)
			if value == nil then
				warn(("[Flux] progress '%s': refusing '%s', the value must be a number"):format(
					tostring(title), tostring(rawValue)))
				return self
			end
			value = Math.clamp(value, lower, upper)
	
			local changed = value ~= self._value
			self._value = value
	
			if changed then
				paint(value, not silent)
				Element.pushConfig(self._flag, value)
				self.Changed:Dispatch(value)
				if not silent and self._callback ~= nil then
					local ok, err = pcall(self._callback, value)
					if not ok then
						warn("[Flux] progress '" .. tostring(title) .. "': " .. tostring(err))
					end
				end
			end
			return self
		end
	
		self.Set = function(a: any, b: any)
			local value = a
			if a == self then
				value = b
			end
			return set(value)
		end
	
		--- The clamped number the bar is actually showing, never the number the caller hoped for.
		self.SetValue = function()
			return self._value
		end
	
		self.GetValue = function()
			return self._value
		end
	
		self.SetCallback = function(fn)
			self._callback = fn
			return self
		end
	
		self.SetTitle = function(a: any, b: any)
			local text = a
			if a == self then
				text = b
			end
			self.Title = tostring(text)
			row.Title.Text = self.Title
			return self
		end
	
		self.SetVisible = function(a: any, b: any)
			local visible = a
			if a == self then
				visible = b
			end
			row.Root.Visible = visible == true
			return self
		end
	
		-- Groupbox calls this plain (`row.OnFilter(isMatch)`) and a host with a colon, so the flag arrives in
		-- either position; the shim reads whichever one carries it.
		self.OnFilter = function(a: any, b: any)
			local matched = a
			if a == self then
				matched = b
			end
			row.Root.Visible = matched == true
		end
	
		self.Destroy = function()
			if self.Destroyed then
				return
			end
			self.Destroyed = true
			AnimationManager.cancel(fill)
			self.Changed:Destroy()
			Element.releaseSearch(group, self)
			row.Root:Destroy()
		end
	
		self._value = Math.clamp(tonumber(options.Default) or lower, lower, upper)
		paint(self._value, false)
	
		Element.bindConfig(maid, self._flag, function(value)
			if not self.Destroyed then
				set(value, true)
			end
		end, function()
			return self._value
		end)
	
		self.SearchId = Element.searchable(group, self, tostring(title), options.Desc)
		Guard.set(row.Root, "LayoutOrder", group:RowCount())
		return self
	end
	
	return ProgressBar
end

-- src/Components/Slider.lua
FluxRegistry["Flux/Components/Slider"] = function(require)
	--[[
		Components/Slider — a draggable value row.
	
		The pointer is followed through the input *service*, not the track: a GuiObject stops
		receiving motion the frame the cursor leaves it, and a slider that drops the drag the moment
		the pointer overshoots the 6 px rail is the bug every user notices first. The track's own
		MouseButton1Down is still used when the client has it; the service path behind a hit test
		covers click-to-position and the clients that never surface the instance signal at all.
	
		Positions are computed from the track's AbsoluteSize against input.Position because both are
		engine-space pixels: the UIScale the layout manager puts on the ScreenGui is already baked into
		absolute geometry by the engine, so dividing one by the other cancels it. Multiplying the
		pointer back through the scale (or a local-layout offset) is how a slider ends up moving half
		as fast on a phone.
	
		The user callback is held until the interaction ends. A drag produces one commit, not two
		hundred `host:rebuild()` calls, while `Changed` and the config store still see every value
		the knob passes — the store debounces its own write.
	]]
	
	local Element = require("Flux/Core/Element")
	local Instance = require("Flux/Utilities/Instance")
	local Guard = require("Flux/Utilities/Guard")
	local Math = require("Flux/Utilities/Math")
	local Signal = require("Flux/Utilities/Signal")
	
	local UserInputService = Guard.service("UserInputService")
	
	local Slider = {}
	
	local BODY_W = 150
	local BODY_H = 28
	local TRACK_H = 6
	local KNOB = 14
	local HIT_PAD = 10
	
	local function isPress(input: any): boolean
		local kind = Guard.get(input, "EnumType")
		return kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch
	end
	
	function Slider.new(group: any, options: {[string]: any}?)
		options = Element.options(options, {
			Name = "Slider",
			Title = nil,
			Desc = nil,
			Default = 0,
			Min = 0,
			Max = 100,
			Step = 1,
			Decimals = nil,
			Callback = nil,
			Flag = nil,
			Prefix = "",
			Suffix = "",
			ShowValue = true,
			Unit = nil,
		})
	
		local title = options.Title or options.Name
		local maid = group.Maid
		local lower = tonumber(options.Min) or 0
		local upper = tonumber(options.Max) or 100
		if upper < lower then
			lower, upper = upper, lower
		end
		local step = tonumber(options.Step) or 1
		local decimals = tonumber(options.Decimals) or Math.decimalsForStep(step)
		local tail = options.Unit or options.Suffix or ""
	
		local row = Element.row(maid, group.Content, "Slider_" .. tostring(title), {
			Label = title,
			Desc = options.Desc,
			BodyWidth = BODY_W,
			Order = group:RowCount() + 1,
		})
	
		local gauge = Instance.new("Frame", row.Body, {
			Name = "Gauge",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.fromOffset(BODY_W, BODY_H),
			ZIndex = 5,
		})
		maid:giveFunction(function()
			gauge:Destroy()
		 end)
		local gaugeList = Instance.new("UIListLayout", gauge, {
			FillDirection = Enum.FillDirection.Vertical,
			VerticalAlignment = Enum.VerticalAlignment.Bottom,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 3),
		})
		maid:giveFunction(function()
			gaugeList:Destroy()
		end)
	
		local readout = nil
		if options.ShowValue ~= false then
			readout = Element.label(maid, gauge, "Value", {
				Text = "",
				Role = "TextSecondary",
				Font = "Mono",
				TextSize = 11,
				Alignment = Enum.TextXAlignment.Right,
				Size = UDim2.new(1, 0, 0, 12),
				LayoutOrder = 0,
				ZIndex = 6,
			})
		end
	
		local track = Element.panel(maid, gauge, "Track", {
			Color = "Chip",
			Radius = "RadiusPill",
			Size = UDim2.new(1, 0, 0, TRACK_H),
			LayoutOrder = 1,
			ZIndex = 6,
		})
	
		local fill = Element.panel(maid, track, "Fill", {
			Color = "Accent",
			Radius = "RadiusPill",
			Size = UDim2.fromScale(0, 1),
			ZIndex = 7,
		})
	
		local knob = Element.panel(maid, track, "Knob", {
			Color = "Accent",
			Radius = "RadiusPill",
			Size = UDim2.fromOffset(KNOB, KNOB),
			AnchorPoint = Vector2.new(0.5, 0.5),
			ZIndex = 8,
		})
	
		local self = {
			Instance = row.Root,
			Title = title,
			Changed = Signal.new(),
			_value = 0,
			_callback = options.Callback,
			_group = group,
			_flag = options.Flag,
			_row = row,
		}
	
		local function quantize(candidate: number): number
			-- snap owns the floor (a value below it rounds to one step *below* itself), so only the
			-- ceiling needs the clamp; reversing the order would let 0.7 round above Max unbounded.
			return Math.clamp(Math.snap(candidate, lower, step, decimals), lower, upper)
		end
	
		local function paint(value: number)
			local span = upper - lower
			local frac = Math.inverseLerp(value, lower, upper)
			if span <= 0 then
				frac = 0
			end
			fill.Size = UDim2.fromScale(frac, 1)
			knob.Position = UDim2.fromScale(frac, 0.5)
			if readout ~= nil then
				readout.Text = tostring(options.Prefix or "") .. string.format("%." .. decimals .. "f", value) .. tail
			end
		end
	
		local function set(rawValue: any): number
			local value = quantize(tonumber(rawValue) or lower)
			local changed = value ~= self._value
			self._value = value
			paint(value)
			if changed then
				Element.pushConfig(self._flag, value)
				self.Changed:Dispatch(value)
			end
			return value
		end
	
		local function fireCallback()
			if self._callback == nil then
				return
			end
			local ok, err = pcall(self._callback, self._value)
			if not ok then
				warn("[Flux] slider '" .. tostring(title) .. "': " .. tostring(err))
			end
		end
	
		local dragging = false
		local startValue = 0
		local moveConnection = nil
		local endConnection = nil
	
		-- Resolved once: a client without the service input events still gets the instance-level
		-- down path, and one without either simply gets a slider that responds to Set only.
		local movementSignal = UserInputService ~= nil and Guard.get(UserInputService, "InputChanged") or nil
		local releaseSignal = UserInputService ~= nil and Guard.get(UserInputService, "InputEnded") or nil
	
		local function updateFrom(input: any)
			local point = Guard.get(input, "Position")
			if point == nil then
				return
			end
			local origin = track.AbsolutePosition
			local size = track.AbsoluteSize
			if size.X <= 0 then
				return
			end
			set(lower + (upper - lower) * Math.inverseLerp(point.X, origin.X, origin.X + size.X))
		end
	
		local function stopDrag(fire: boolean)
			if not dragging then
				return
			end
			dragging = false
			if moveConnection ~= nil then
				moveConnection:Disconnect()
				moveConnection = nil
			end
			if endConnection ~= nil then
				endConnection:Disconnect()
				endConnection = nil
			end
			-- The per-drag listeners are gone; the resting colour replaces the active one through
			-- the same tint slot, so a later theme swap keeps moving the knob.
			Element.tint(maid, knob, "BackgroundColor3", "Accent")
			if fire and not self.Destroyed and self._value ~= startValue then
				fireCallback()
			end
		end
	
		local function beginDrag(input: any)
			if dragging or self.Destroyed then
				return
			end
			dragging = true
			startValue = self._value
			if movementSignal ~= nil then
				moveConnection = movementSignal:Connect(function(moved)
					if not self.Destroyed then
						updateFrom(moved)
					end
				end)
			end
			if releaseSignal ~= nil then
				endConnection = releaseSignal:Connect(function(over)
					if isPress(over) then
						stopDrag(true)
					end
				end)
			end
			Element.tint(maid, knob, "BackgroundColor3", "AccentHover")
			updateFrom(input)
		end
	
		local downSignal = Guard.get(track, "MouseButton1Down")
		if downSignal ~= nil then
			maid:giveConnection(downSignal:Connect(beginDrag))
		end
	
		local beganSignal = UserInputService ~= nil and Guard.get(UserInputService, "InputBegan") or nil
		if beganSignal ~= nil then
			maid:giveConnection(beganSignal:Connect(function(input)
				if not isPress(input) or dragging then
					return
				end
				local point = Guard.get(input, "Position")
				if point == nil then
					return
				end
				local origin = track.AbsolutePosition
				local size = track.AbsoluteSize
				local inside = point.X >= origin.X - HIT_PAD
					and point.X <= origin.X + size.X + HIT_PAD
					and point.Y >= origin.Y - HIT_PAD
					and point.Y <= origin.Y + size.Y + HIT_PAD
				if inside then
					beginDrag(input)
				end
			end))
		end
	
		-- Touch on a frame is a gesture stream of its own on the engine; it arrives alongside the
		-- service events, and beginDrag's `dragging` latch makes the duplication harmless.
		local frameBegan = Guard.get(track, "InputBegan")
		local frameMoved = Guard.get(track, "InputChanged")
		local frameEnded = Guard.get(track, "InputEnded")
		if frameBegan ~= nil and frameMoved ~= nil and frameEnded ~= nil then
			maid:giveConnection(frameBegan:Connect(function(input)
				if isPress(input) then
					beginDrag(input)
				end
			end))
			maid:giveConnection(frameMoved:Connect(function(input)
				if dragging and isPress(input) then
					updateFrom(input)
				end
			end))
			maid:giveConnection(frameEnded:Connect(function(input)
				if isPress(input) then
					stopDrag(true)
				end
			end))
		end
	
		-- Methods live on the table as fields (the internal style of this library) while hosts call
		-- them with a colon. Accept both: when the first argument is the widget itself, the real
		-- argument is the one behind it.
		local function recv(a: any, b: any): any
			if a == self then
				return b
			end
			return a
		end
	
		self.Set = function(a: any, b: any)
			if self.Destroyed then
				return self
			end
			set(recv(a, b))
			return self
		end
	
		self.GetValue = function()
			return self._value
		end
	
		self.SetCallback = function(a: any, b: any)
			self._callback = recv(a, b)
			return self
		end
	
		self.SetText = function(a: any, b: any)
			self.Title = tostring(recv(a, b))
			row.Title.Text = self.Title
			return self
		end
		self.SetTitle = self.SetText
	
		self.SetVisible = function(a: any, b: any)
			row.Root.Visible = recv(a, b) == true
			return self
		end
	
		self.OnFilter = function(a: any, b: any)
			stopDrag(false)
			row.Root.Visible = recv(a, b) == true
		end
	
		self.Destroy = function()
			if self.Destroyed then
				return
			end
			stopDrag(false)
			self.Destroyed = true
			self.Changed:Destroy()
			Element.releaseSearch(group, self)
			row.Root:Destroy()
		end
	
		-- Staged without pushing: writing the default into the config store *before* bindConfig
		-- would overwrite the value a loaded config restored, and the file's number would be lost
		-- the moment the row is built after the load.
		self._value = quantize(tonumber(options.Default) or lower)
		paint(self._value)
	
		Element.bindConfig(maid, self._flag, function(value)
			if not self.Destroyed then
				set(value)
			end
		end, function()
			return self._value
		end)
	
		self.SearchId = Element.searchable(group, self, tostring(title), options.Desc)
		Guard.set(row.Root, "LayoutOrder", group:RowCount())
		return self
	end
	
	return Slider
end

-- src/Components/Toggle.lua
FluxRegistry["Flux/Components/Toggle"] = function(require)
	--[[
		Components/Toggle — a labelled switch row.
	
		This is the reference component: everything the other nineteen follow. A widget
	
		  * builds through `Element.row` so the label and hint are placed identically everywhere,
		  * keeps its own value rather than reading the UI back, so `Set` is safe before the row is
		    mounted and a theme swap cannot change state,
		  * reports to the search index and the config store through Element helpers, and
		  * exposes `Set / GetValue / Destroy` plus a `Changed` signal, which is the whole public
		    surface a hub needs from any control.
	]]
	
	local Element = require("Flux/Core/Element")
	local Instance = require("Flux/Utilities/Instance")
	local Guard = require("Flux/Utilities/Guard")
	local Signal = require("Flux/Utilities/Signal")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	local AnimationManager = require("Flux/Systems/AnimationManager")
	local TooltipManager = require("Flux/Systems/TooltipManager")
	
	local Toggle = {}
	
	local SWITCH_WIDTH = 42
	local SWITCH_HEIGHT = 22
	local KNOB = 16
	
	function Toggle.new(group: any, options: {[string]: any}?)
		options = Element.options(options, {
			Name = "Toggle",
			Title = nil,
			Desc = nil,
			Default = false,
			Callback = nil,
			Flag = nil,
			Icon = nil,
			Suffix = nil,
		})
	
		local title = options.Title or options.Name
		local maid = group.Maid
		local row = Element.row(maid, group.Content, "Toggle_" .. tostring(title), {
			Label = title,
			Desc = options.Desc,
			BodyWidth = SWITCH_WIDTH + 8,
			Order = group:RowCount() + 1,
		})
	
		local track = Element.panel(maid, row.Body, "Switch", {
			Color = "Field",
			Radius = "RadiusPill",
			Size = UDim2.fromOffset(SWITCH_WIDTH, SWITCH_HEIGHT),
			Stroke = "BorderSecondary",
			ZIndex = 6,
		})
	
		local knob = Element.panel(maid, track, "Knob", {
			Color = "TextMuted",
			Radius = "RadiusPill",
			Size = UDim2.fromOffset(KNOB, KNOB),
			Position = UDim2.new(0, 3, 0.5, 0),
			AnchorPoint = Vector2.new(0, 0.5),
			ZIndex = 7,
		})
	
		if options.Icon ~= nil then
			Element.icon(maid, row.Body, options.Icon, {
				Role = "TextMuted",
				Size = UDim2.fromOffset(13, 13),
				LayoutOrder = -1,
				ZIndex = 6,
			})
		end
	
		local self = {
			Instance = row.Root,
			Title = title,
			Changed = Signal.new(),
			_value = options.Default == true,
			_callback = options.Callback,
			_maid = maid,
			_group = group,
			_flag = options.Flag,
			_row = row,
		}
	
		-- Element.panel bound the stroke to BorderSecondary for the resting state; tinting replaces
		-- that binding rather than writing over it, so a later theme swap keeps the active colour.
		local stroke = track:FindFirstChildOfClass("UIStroke")
	
		local function paint(value: boolean, instant: boolean?)
			-- Colour and position move together: a knob that slides without lighting up reads as a
			-- hover effect rather than a state change.
			Element.tint(maid, track, "BackgroundColor3", value and "AccentSoft" or "Field")
			if stroke ~= nil then
				Element.tint(maid, stroke, "Color", value and "Accent" or "BorderSecondary")
			end
			Element.tint(maid, knob, "BackgroundColor3", value and "Accent" or "TextMuted")
	
			local goal = UDim2.new(0, value and (SWITCH_WIDTH - KNOB - 3) or 3, 0.5, 0)
			if instant then
				knob.Position = goal
			else
				AnimationManager.to(knob, { Position = goal }, { Duration = 0.16, Easing = "outQuad" })
			end
		end
	
		local function set(value: boolean, silent: boolean?)
			local on = value == true
			if self.Destroyed then
				return self
			end
			local changed = self._value ~= on
			self._value = on
	
			paint(on, silent)
	
			if changed then
				Element.pushConfig(self._flag, on)
				self.Changed:Dispatch(next)
				if not silent and self._callback ~= nil then
					local ok, err = pcall(self._callback, next)
					if not ok then
						warn("[Flux] toggle '" .. tostring(title) .. "': " .. tostring(err))
					end
				end
			end
			return self
		end
	
		local button = Instance.new("TextButton", row.Root, {
			Name = "HitArea",
			Text = "",
			AutoButtonColor = false,
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			ZIndex = 8,
			BorderSizePixel = 0,
		})
		maid:giveFunction(function()
			button:Destroy()
		end)
	
		button.MouseButton1Click:Connect(function()
			set(not self._value)
		end)
	
		-- The whole row is the target, not a 42px switch: on a phone the small version is unusable.
		if type(options.Desc) == "string" and options.Desc ~= "" then
			TooltipManager.attach(button, options.Desc)
		end
	
		-- Methods are fields on the handle (the library's internal style) while hosts call them with a
		-- colon, which prepends the handle. `Element.recv` reads the real argument either way.
		self.Set = function(a: any, b: any)
			return set(Element.recv(self, a, b), true)
		end
	
		self.Toggle = function()
			return set(not self._value)
		end
	
		self.GetValue = function()
			return self._value
		end
	
		self.SetCallback = function(a: any, b: any)
			self._callback = Element.recv(self, a, b)
			return self
		end
	
		self.SetTitle = function(a: any, b: any)
			local text = tostring(Element.recv(self, a, b))
			self.Title = text
			row.Title.Text = text
			return self
		end
	
		self.SetVisible = function(a: any, b: any)
			row.Root.Visible = Element.recv(self, a, b) == true
			return self
		end
	
		self.OnFilter = function(a: any, b: any)
			row.Root.Visible = Element.recv(self, a, b) == true
		end
	
		self.Destroy = function()
			if self.Destroyed then
				return
			end
			self.Destroyed = true
			AnimationManager.cancel(knob)
			self.Changed:Destroy()
			Element.releaseSearch(group, self)
			row.Root:Destroy()
		end
	
		Element.bindConfig(maid, self._flag, function(value)
			set(value == true, true)
		end, function()
			return self._value
		end)
	
		local searchId = Element.searchable(group, self, tostring(title), options.Desc)
		self.SearchId = searchId
	
		-- The value is painted, not animated, before the row has ever been on screen: an entrance
		-- tween on a switch that was already on looks like the hub turning features on by itself.
		paint(self._value, true)
		Guard.set(row.Root, "LayoutOrder", group:RowCount())
		return self
	end
	
	return Toggle
end

-- src/Core/Container.lua
FluxRegistry["Flux/Core/Container"] = function(require)
	--[[
		Core/Container — gives a container its component constructors.

		A groupbox, a modal body and a list row all take the same widgets, and each of them used to
		re-declare twenty forwarding methods. This attaches them once from the component index, so a
		new component exists on every container the moment it is listed there.

		Every constructor receives the container itself, which is what carries the Maid, the row
		parent and the search tracker. A component never reaches for a window directly.
	]]

	local Index = require("Flux/Components/Index")

	local Container = {}
	local loaded = nil

	local function modules(): {[string]: any}
		if loaded == nil then
			loaded = {}
			for name, path in pairs(Index) do
				local ok, module = pcall(require, path)
				if ok and type(module) == "table" and type(module.new) == "function" then
					loaded[name] = module
				else
					warn(("[Flux] component '%s' (%s) failed to load: %s"):format(name, tostring(path), tostring(module)))
				end
			end
		end
		return loaded
	end

	--- Attach `Toggle`, `Slider`, … to `object`. `object` must expose Maid, Content and track().
	function Container.decorate(object: any, context: {[string]: any}?)
		local available = modules()

		for name, module in pairs(available) do
			if object[name] == nil then
				object[name] = function(self: any, options: any)
					if self.Destroyed then
						warn(("[Flux] %s added to a destroyed container"):format(name))
						return nil
					end
					return module.new(self, options, context)
				end
			end
		end

		return object
	end

	function Container.names(): {string}
		local out = {}
		for name in pairs(modules()) do
			table.insert(out, name)
		end
		table.sort(out)
		return out
	end

	function Container.has(name: string): boolean
		return modules()[name] ~= nil
	end

	--- Components register themselves at runtime too, which is how an optional widget in a host
	--- script becomes available on every container without editing the index.
	function Container.register(name: string, module: any): boolean
		if type(name) ~= "string" or type(module) ~= "table" or type(module.new) ~= "function" then
			warn("[Flux] component registration needs a name and a module with .new")
			return false
		end

		loaded = loaded or modules()
		loaded[name] = module
		Index[name] = Index[name] or ("custom/" .. name)
		return true
	end

	return Container
end

-- src/Core/Element.lua
FluxRegistry["Flux/Core/Element"] = function(require)
	--[[
		Core/Element — the shared building blocks every widget is made of.
	
		Components should not be assembling UICorner + UIStroke + UIPadding by hand in twenty places:
		that is how a library ends up with three slightly different panels and a theme change that
		misses one of them. Everything here takes the component's Maid so the instance it creates is
		owned by the thing that asked for it, and takes a *role name* rather than a colour so a theme
		swap reaches it.
	
		Every function in this module is allowed to be called on a client that lacks half the engine:
		rounding, strokes and padding are all optional members, and Guard.set decides whether the
		element exists rather than the caller discovering it crashed.
	]]
	
	local Instance = require("Flux/Utilities/Instance")
	local Guard = require("Flux/Utilities/Guard")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	local IconManager = require("Flux/Systems/IconManager")
	local AnimationManager = require("Flux/Systems/AnimationManager")
	local Table = require("Flux/Utilities/Table")
	
	local Players = Guard.service("Players")
	
	local Element = {}
	
	local defaultZIndex = 1
	
	--- The ScreenGui a hub owns. Created once and reused, because a second ScreenGui means two click
	--- capturers and two sets of ZIndex scopes.
	function Element.root(maid: any, options: { Name: string?, Order: number?, ResetOnSpawn: boolean? }): any
		options = options or {}
	
		local player = Players and Players.LocalPlayer
		local parent = player and player:FindFirstChildOfClass("PlayerGui") or (player and player:FindFirstChildOfClass("CoreGui"))
	
		if parent == nil then
			parent = Guard.service("CoreGui")
		end
	
		local gui = Instance.new("ScreenGui", parent, {
			Name = options.Name or "FluxHub",
			ResetOnSpawn = options.ResetOnSpawn == true,
			IgnoreGuiInset = true,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
			DisplayOrder = options.Order or 1000,
			ResetOnSpawnBehavior = nil,
		})
	
		if maid ~= nil then
			maid:giveInstance(gui)
		end
	
		return gui
	end
	
	--- A filled, rounded, optionally bordered rectangle — the shape almost every surface is.
	--- Returns the frame; the corner and stroke are given to the maid.
	function Element.panel(maid: any, parent: any, name: string, options: {
		Color: string?,
		Transparency: number?,
		Radius: string?,
		RadiusOffset: number?,
		Stroke: string?,
		StrokeTransparency: number?,
		Thickness: number?,
		Clips: boolean?,
		Size: UDim2?,
		Position: UDim2?,
		AnchorPoint: Vector2?,
		LayoutOrder: number?,
		ZIndex: number?,
		Visible: boolean?,
	}): any
		local frame = Instance.new("Frame", parent, {
			Name = name,
			BackgroundColor3 = ThemeManager.color(options and options.Color or "Panel"),
			BackgroundTransparency = options and options.Transparency or 0,
			Size = options and options.Size or UDim2.new(),
			Position = options and options.Position or UDim2.new(),
			AnchorPoint = options and options.AnchorPoint or Vector2.new(0, 0),
			LayoutOrder = options and options.LayoutOrder or 0,
			ZIndex = options and options.ZIndex or defaultZIndex,
			Visible = options.Visible ~= false,
			BorderSizePixel = 0,
		})
	
		if options and options.Clips then
			frame.ClipsDescendants = true
		end
	
		local role = options and options.Color or "Panel"
		if maid ~= nil then
			maid:give(ThemeManager.bind(frame, "BackgroundColor3", role))
		end
	
		if options and options.Radius ~= nil then
			local metric = ThemeManager.metric(options.Radius) or 0
			local radius = (options.RadiusOffset or 0) + metric
			local corner = Instance.corner(frame, UDim.new(0, math.max(0, radius)))
			if maid ~= nil then
				maid:giveFunction(function()
					corner:Destroy()
				end)
			end
		end
	
		if options and options.Stroke then
			local stroke = Instance.stroke(
				frame,
				ThemeManager.color(options.Stroke),
				options.Thickness or ThemeManager.metric("StrokeThickness") or 1,
				options.StrokeTransparency or 0
			)
			if stroke ~= nil then
				if maid ~= nil then
					maid:giveFunction(function()
						stroke:Destroy()
					end)
					maid:give(ThemeManager.bind(stroke, "Color", options.Stroke))
				end
			end
		end
	
		return frame
	end
	
	--- Text bound to a type role: colour, font and size all follow the theme.
	function Element.label(maid: any, parent: any, name: string, options: {
		Text: string?,
		Role: string?,
		Font: string?,
		TextSize: number?,
		Size: UDim2?,
		Position: UDim2?,
		AnchorPoint: Vector2?,
		LayoutOrder: number?,
		Alignment: Enum.TextXAlignment?,
		Vertical: Enum.TextYAlignment?,
		Wrap: boolean?,
		AutoWidth: boolean?,
		MaxWidth: number?,
		SizeConstraint: Enum.SizeConstraint?,
		ZIndex: number?,
		Transparency: number?,
	}): any
		options = options or {}
		local role = options.Role or "TextPrimary"
	
		local label = Instance.new("TextLabel", parent, {
			Name = name,
			Text = options.Text or "",
			BackgroundTransparency = 1,
			TextColor3 = ThemeManager.color(role) or Color3.fromRGB(231, 231, 237),
			Font = ThemeManager.font(options.Font or "Body"),
			TextSize = options.TextSize or 14,
			TextXAlignment = options.Alignment or Enum.TextXAlignment.Left,
			TextYAlignment = options.Vertical or Enum.TextYAlignment.Center,
			TextWrapped = options.Wrap == true,
			Size = options.Size or UDim2.fromScale(1, 1),
			Position = options.Position or UDim2.new(),
			AnchorPoint = options.AnchorPoint or Vector2.new(0, 0),
			LayoutOrder = options.LayoutOrder or 0,
			ZIndex = options.ZIndex or defaultZIndex,
			TextTransparency = options.Transparency or 0,
		})
	
		-- Auto-sizing text is a TextLabel's default behaviour; opting into a width constraint is what
		-- stops a long paragraph running off a panel.
		if options.AutoWidth then
			label.AutomaticSize = Enum.AutomaticSize.X
			if options.MaxWidth then
				label.TextWrapped = true
				label.Size = UDim2.fromOffset(options.MaxWidth, label.Size.Y.Offset)
			end
		elseif options.Wrap then
			label.AutomaticSize = Enum.AutomaticSize.Y
		end
	
		if maid ~= nil then
			maid:give(ThemeManager.bind(label, "TextColor3", role))
		end
	
		return label
	end
	
	--- Bind a property to a role, replacing whatever role that property was bound to before.
	--- Selection states need this: a nav label is TextSecondary until it becomes the active tab, and
	--- a plain re-write would then be undone by the next theme swap.
	local binds = setmetatable({}, { __mode = "k" })
	
	function Element.tint(maid: any, instance: any, property: string, role: string): boolean
		if instance == nil or role == nil then
			return false
		end
	
		local perInstance = binds[instance]
		if perInstance == nil then
			perInstance = {}
			binds[instance] = perInstance
		end
	
		local previous = perInstance[property]
		if previous ~= nil then
			previous()
		end
	
		local unbind = ThemeManager.bind(instance, property, role)
		perInstance[property] = unbind
	
		if maid ~= nil then
			maid:giveFunction(function()
				local entry = binds[instance]
				if entry ~= nil then
					entry[property] = nil
				end
				unbind()
			end)
		end
	
		return true
	end
	
	--- A glyph, coloured by role. Returns the IconManager handle so the caller can re-tint it.
	function Element.icon(maid: any, parent: any, name: string, options: {
		Size: UDim2?,
		Position: UDim2?,
		AnchorPoint: Vector2?,
		Role: string?,
		LayoutOrder: number?,
		ZIndex: number?,
		Transparency: number?,
	}): any
		options = options or {}
		local role = options.Role or "TextSecondary"
	
		local handle = IconManager.attach(parent, name, {
			Name = "Icon_" .. name,
			Size = options.Size,
			Position = options.Position,
			AnchorPoint = options.AnchorPoint,
			Color = ThemeManager.color(role),
			LayoutOrder = options.LayoutOrder,
			ZIndex = options.ZIndex,
			Transparency = options.Transparency,
		})
	
		if maid ~= nil then
			maid:giveFunction(function()
				if handle.instance ~= nil then
					handle.instance:Destroy()
				end
			end)
	
			-- Unfiltered on purpose: `setRole` below moves the colour this closure reads, so a role
			-- list captured now would wake the repaint for the wrong token after a selection change.
			maid:give(ThemeManager.bindFn(function(tokens)
				local value = tokens.colors[role]
				if value ~= nil then
					handle:setColor(value)
				end
			end, nil))
		end
	
		handle.setRole = function(nextRole: string)
			role = nextRole
			local value = ThemeManager.color(role)
			if value ~= nil then
				handle:setColor(value)
			end
		end
	
		return handle
	end
	
	--- A full-bleed hover/press layer: the affordance almost every interactive row has.
	--- Returns the instance it attached to, plus whether motion is available.
	function Element.interactive(instance: any, options: {
		Maid: any,
		HoverColor: string?,
		OnEnter: (() -> ())?,
		OnLeave: (() -> ())?,
		OnClick: (() -> ())?,
	}): any
		options = options or {}
		local maid = options.Maid
	
		local baseColor = Guard.get(instance, "BackgroundColor3")
		local hoverRole = options.HoverColor or "Hover"
		local pressed = false
	
		local function paint(color: Color3?, transparency: number?)
			if color ~= nil then
				Guard.set(instance, "BackgroundColor3", color)
			end
			if transparency ~= nil then
				Guard.set(instance, "BackgroundTransparency", transparency)
			end
		end
	
		local function restore(instant: boolean?)
			local goals = { BackgroundColor3 = baseColor }
			if instant then
				paint(baseColor)
				return
			end
			AnimationManager.to(instance, goals, { Duration = 0.12, Easing = "outQuad" })
		end
	
		if maid ~= nil then
			maid:give(ThemeManager.bindFn(function(tokens)
				-- The base colour is a role, so a theme change must move it even while the pointer is
				-- sitting on the row; otherwise the hovered element keeps the old palette.
				if not pressed then
					paint(tokens.colors[hoverRole] or baseColor)
				end
			end, { hoverRole }))
		end
	
		local enter = Guard.get(instance, "MouseEnter")
		if enter ~= nil then
			if maid ~= nil then
				maid:giveConnection(enter:Connect(function()
					AnimationManager.to(instance, { BackgroundColor3 = ThemeManager.color(hoverRole) or baseColor }, {
						Duration = 0.12,
						Easing = "outQuad",
					})
					if options.OnEnter ~= nil then
						options.OnEnter()
					end
				end))
			else
				enter:Connect(function()
					if options.OnEnter ~= nil then
						options.OnEnter()
					end
				end)
			end
		end
	
		local leave = Guard.get(instance, "MouseLeave")
		if leave ~= nil and maid ~= nil then
			maid:giveConnection(leave:Connect(function()
				pressed = false
				restore()
				if options.OnLeave ~= nil then
					options.OnLeave()
				end
			end))
		end
	
		local down = Guard.get(instance, "MouseButton1Down")
		if down ~= nil and maid ~= nil then
			maid:giveConnection(down:Connect(function()
				pressed = true
				AnimationManager.to(instance, { BackgroundColor3 = ThemeManager.color("Selection") or baseColor }, {
					Duration = 0.08,
					Easing = "outQuad",
				})
			end))
		end
	
		local up = Guard.get(instance, "MouseButton1Up")
		if up ~= nil and maid ~= nil then
			maid:giveConnection(up:Connect(function()
				pressed = false
				restore()
				if options.OnClick ~= nil then
					options.OnClick()
				end
			end))
		end
	
		return instance
	end
	
	--- A click-anywhere-else detector, used by dropdowns, colour pickers and context menus. One
	--- connection is shared for the whole library: a per-widget InputBegan listener is how a menu
	--- with forty open widgets costs forty callbacks per click.
	local clickWatchers = {}
	local clickConnection: RBXScriptConnection? = nil
	local UserInputService = Guard.service("UserInputService")
	
	local function ensureClickWatcher()
		if clickConnection ~= nil or UserInputService == nil then
			return
		end
	
		clickConnection = UserInputService.InputBegan:Connect(function(input, processed)
			local targets = {}
			for _, watcher in pairs(clickWatchers) do
				table.insert(targets, watcher)
			end
	
			for _, watcher in ipairs(targets) do
				watcher(input, processed)
			end
		end)
	end
	
	--- Call the function when the pointer clicks outside `instance`. Returns an unbind.
	function Element.outsideClick(instance: any, fn: () -> ()): () -> ()
		local key = tostring(instance)
		local tracker = function(input: any, _processed: boolean)
			local inputType = Guard.get(input, "EnumType")
			local isClick = inputType ~= nil
				and (inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch)
			if not isClick then
				return
			end
	
			local ok, parent = pcall(function()
				return instance.Parent
			end)
			if not ok or parent == nil then
				-- The widget is gone, so this watcher is dead weight; unhook rather than keep
				-- testing an instance that no longer exists.
				clickWatchers[key] = nil
				return
			end
	
			local position = Guard.get(input, "Position")
			local absolute = Guard.get(instance, "AbsolutePosition")
			local size = Guard.get(instance, "AbsoluteSize")
			if position == nil or absolute == nil or size == nil then
				return
			end
	
			local inside = position.X >= absolute.X
				and position.X <= absolute.X + size.X
				and position.Y >= absolute.Y
				and position.Y <= absolute.Y + size.Y
	
			if not inside then
				fn()
			end
		end
	
		clickWatchers[key] = tracker
		ensureClickWatcher()
	
		return function()
			clickWatchers[key] = nil
			if next(clickWatchers) == nil and clickConnection ~= nil then
				clickConnection:Disconnect()
				clickConnection = nil
			end
		end
	end
	
	function Element.watcherCount(): number
		local count = 0
		for _ in pairs(clickWatchers) do
			count += 1
		end
		return count
	end
	
	--- Rounded corners the theme owns: pass the metric role, not a number, so the radius moves with
	--- the preset. Returns whether the client accepted the corner.
	function Element.round(maid: any, instance: any, role: string, offset: number?): boolean
		local metric = ThemeManager.metric(role)
		if metric == nil then
			return false
		end
		local corner = Instance.corner(instance, UDim.new(0, math.max(0, metric + (offset or 0))))
		if corner == nil then
			return false
		end
		if maid ~= nil then
			maid:giveFunction(function()
				corner:Destroy()
			end)
		end
		return true
	end
	
	--- Padding from a role-defined number, e.g. Element.pad(maid, frame, "ContentPadding").
	function Element.pad(maid: any, instance: any, role: string): boolean
		local metric = ThemeManager.metric(role)
		if metric == nil then
			return false
		end
		local padding = Instance.pad(instance, {
			Top = UDim.new(0, metric),
			Bottom = UDim.new(0, metric),
			Left = UDim.new(0, metric),
			Right = UDim.new(0, metric),
		})
		if padding == nil then
			return false
		end
		if maid ~= nil then
			maid:giveFunction(function()
				padding:Destroy()
			end)
		end
		return true
	end
	
	--- A vertical stack that owns its spacing, so a group of rows does not need to know the metric.
	function Element.stack(maid: any, parent: any, options: { Gap: string?, Sort: boolean?, Padding: number? }): any
		local gap = options.Padding or 8
		if options.Gap ~= nil then
			gap = ThemeManager.metric(options.Gap) or gap
		end
	
		local list = Instance.list(parent, {
			Padding = UDim.new(0, gap),
			SortOrder = options.Sort ~= false and Enum.SortOrder.LayoutOrder or Enum.SortOrder.Name,
		})
	
		if maid ~= nil and list ~= nil then
			maid:giveFunction(function()
				list:Destroy()
			end)
	
			if options.Gap then
				maid:give(ThemeManager.bindFn(function(tokens)
					local value = tokens.metrics[options.Gap]
					if value ~= nil then
						Guard.set(list, "Padding", UDim.new(0, value))
					end
				end, { options.Gap }))
			end
		end
	
		return list
	end
	
	--- The anatomy of a settings row: a label (with optional description) on the left, the control
	--- itself on the right. Twelve components are this shape, so it is written once — and a change to
	--- the spacing between a title and its hint reaches all twelve.
	---
	--- The text block auto-sizes and the body is pinned to the right edge, so a two-line description
	--- grows the row instead of overlapping the control, which is what a fixed-height row does badly.
	function Element.row(maid: any, parent: any, name: string, options: {
		Label: string?,
		Desc: string?,
		Height: number?,
		Order: number?,
		ZIndex: number?,
		BodyWidth: number?,
	}): {[string]: any}
		options = options or {}
		local height = options.Height or ThemeManager.metric("RowHeight") or 30
		local zIndex = options.ZIndex or 5
	
		local root = Element.panel(maid, parent, name, {
			Transparency = 1,
			Size = UDim2.new(1, 0, 0, height),
			LayoutOrder = options.Order or 0,
			ZIndex = zIndex,
		})
	
		local text = Instance.new("Frame", root, {
			Name = "Text",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.new(1, -(options.BodyWidth or 130), 1, 0),
			ZIndex = zIndex,
		})
		text.AutomaticSize = Enum.AutomaticSize.None
		Instance.new("UIListLayout", text, {
			FillDirection = Enum.FillDirection.Vertical,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
		})
	
		local title = Element.label(maid, text, "Title", {
			Text = options.Label or "",
			Role = "TextPrimary",
			TextSize = 13,
			Size = UDim2.new(1, 0, 0, options.Desc ~= nil and 15 or height),
			ZIndex = zIndex,
		})
	
		local desc = nil
		if type(options.Desc) == "string" and options.Desc ~= "" then
			desc = Element.label(maid, text, "Hint", {
				Text = options.Desc,
				Role = "TextMuted",
				TextSize = 11,
				Wrap = true,
				LayoutOrder = 1,
				Size = UDim2.new(1, 0, 0, 13),
				ZIndex = zIndex,
			})
			-- Two lines need two lines' worth of height, or the hint is clipped by the row.
			root.Size = UDim2.new(1, 0, 0, height + 12)
		end
	
		local body = Instance.new("Frame", root, {
			Name = "Body",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			AnchorPoint = Vector2.new(1, 0.5),
			Size = UDim2.fromOffset(options.BodyWidth or 120, height),
			Position = UDim2.new(1, 0, 0.5, 0),
			ZIndex = zIndex,
		})
		Instance.new("UIListLayout", body, {
			FillDirection = Enum.FillDirection.Horizontal,
			HorizontalAlignment = Enum.HorizontalAlignment.Right,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 6),
		})
	
		return { Root = root, Text = text, Title = title, Hint = desc, Body = body }
	end
	
	--- Wire a widget to a config flag: restore what was saved, keep the store current, and release the
	--- binding when the widget is destroyed. Components take a Flag and get persistence for free.
	function Element.bindConfig(maid: any, key: string?, apply: (any) -> (), read: (() -> any)?): boolean
		if type(key) ~= "string" or key == "" then
			return false
		end
	
		local ConfigManager = require("Flux/Systems/ConfigManager")
		local unbind = ConfigManager.bind(key, { Apply = apply, Read = read })
		maid:giveFunction(unbind)
		return true
	end
	
	--- Stage a widget's value under its flag. Nil keys are a no-op rather than an error, because a
	--- host that does not use configs should not have to pass Flag=false everywhere.
	function Element.pushConfig(key: string?, value: any, options: { Immediate: boolean }?)
		if type(key) ~= "string" or key == "" then
			return false
		end
		local ConfigManager = require("Flux/Systems/ConfigManager")
		return ConfigManager.set(key, value, options)
	end
	
	--- Register a finished row with the search index so it can be filtered out by term. Returns the id.
	function Element.searchable(group: any, row: any, label: string, extra: string?): any
		if group == nil or type(group.track) ~= "function" then
			return nil
		end
		return group:track(row, label, extra)
	end
	
	--- Read the argument of a widget method that may have been called with a colon.
	---
	--- The component handles expose their methods as fields, so the library can call them plain
	--- (`handle.Set(true)`) while a host almost always writes `handle:Set(true)` — which hands the
	--- method the handle as its first argument. One shim keeps both readings correct, so a component
	--- never has to decide which caller it was written for.
	function Element.recv(self: any, a: any, b: any): any
		if a == self then
			return b
		end
		return a
	end
	
	--- Release a row's slot in its card when the component is destroyed on its own. Going through the
	--- group rather than the search index alone is what keeps the card's match count honest.
	function Element.releaseSearch(group: any, row: any): boolean
		local id = row ~= nil and row.SearchId or nil
		if id == nil then
			return false
		end
		if group ~= nil and type(group.forget) == "function" then
			return group:forget(id)
		end
		local SearchManager = require("Flux/Systems/SearchManager")
		return SearchManager.unregister(id)
	end
	
	--- Values a component commonly needs defaulted, in one place, so every widget's option table reads
	--- the same way.
	function Element.options(options: {[string]: any}?, defaults: {[string]: any}): {[string]: any}
		return Table.withDefaults(options, defaults)
	end
	
	return Element
end

-- src/Core/Groupbox.lua
FluxRegistry["Flux/Core/Groupbox"] = function(require)
	--[[
		Core/Groupbox — a titled card on a page, and the container every component is added to.
	
		The panel and its rows are built *without a parent* and only mounted into the tab's column when
		that tab is first opened. An unparented subtree costs the engine nothing to lay out, so a hub
		that declares nine tabs still renders one page — and `Tab:Open` mounts the groups through the
		renderer, so even that page arrives over several frames instead of one blocking pass.
	
		Creating instances at declaration is still what `group:Toggle{…}` means, because the call returns
		a usable handle immediately and an unparented instance is cheap; a host that wants even that
		deferred declares its page inside `window:Defer(function() … end)`, which runs when the tab opens.
	]]
	
	local Maid = require("Flux/Utilities/Maid")
	local Instance = require("Flux/Utilities/Instance")
	local Element = require("Flux/Core/Element")
	local Guard = require("Flux/Utilities/Guard")
	local Container = require("Flux/Core/Container")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	local SearchManager = require("Flux/Systems/SearchManager")
	local TooltipManager = require("Flux/Systems/TooltipManager")
	
	local Groupbox = {}
	Groupbox.__index = Groupbox
	
	local function metric(role: string, fallback: number): number
		return ThemeManager.metric(role) or fallback
	end
	
	function Groupbox.new(tab: any, options: {[string]: any})
		options = Element.options(options, {
			Title = "",
			Desc = nil,
			Icon = nil,
			Side = nil,
			Collapsible = true,
		})
	
		local self = setmetatable({
			Tab = tab,
			Window = tab.Window,
			Title = tostring(options.Title),
			Desc = options.Desc,
			Mounted = false,
			Destroyed = false,
			Collapsed = false,
			Collapsible = options.Collapsible == true,
			_rows = {},
			_rowsById = {},
			_titleMatched = false,
			_matchedSet = {},
			_matched = 0,
			_hidden = false,
		}, Groupbox)
	
		self.Maid = Maid.new()
		tab.Maid:giveFunction(function()
			self.Maid:cleanup()
		end)
		-- Registered on the maid rather than only in `Destroy`, because the window chain tears the
		-- groups down by cleaning maids: a card that outlived its window in the search index would put
		-- dead rows in every result list.
		self.Maid:giveFunction(function()
			SearchManager.unregister(self.SearchId)
			for _, id in ipairs(self._rows) do
				SearchManager.unregister(id)
			end
			table.clear(self._rows)
		end)
	
		local padding = metric("GroupPadding", 16)
		-- The header is a row of its own height: a 24px control needs 24px, and the content offsets
		-- itself by whatever the header ended up being.
		local headerH = (options.Icon ~= nil or options.Collapsible == true) and 24 or 18
	
		self.Panel = Element.panel(self.Maid, nil, "Group_" .. self.Title, {
			Color = "Panel",
			Radius = "RadiusPanel",
			Stroke = "BorderPrimary",
			Size = UDim2.new(1, 0, 0, 0),
			ZIndex = 4,
		})
		self.Panel.AutomaticSize = Enum.AutomaticSize.Y
	
		self.Header = Instance.new("Frame", self.Panel, {
			Name = "GroupHeader",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, -padding * 2, 0, headerH),
			Position = UDim.new(0, padding, 0, padding),
			BorderSizePixel = 0,
			ZIndex = 5,
		})
		Instance.new("UIListLayout", self.Header, {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 7),
			SortOrder = Enum.SortOrder.LayoutOrder,
		})
		Guard.set(self.Header, "AutomaticSize", Enum.AutomaticSize.Y)
	
		if options.Icon ~= nil then
			local badge = Element.panel(self.Maid, self.Header, "Badge", {
				Color = "AccentSoft",
				Radius = "RadiusChip",
				Size = UDim2.fromOffset(18, 18),
				ZIndex = 6,
			})
			badge.LayoutOrder = 0
			Element.icon(self.Maid, badge, options.Icon, {
				Role = "Accent",
				Size = UDim2.fromOffset(11, 11),
				Position = UDim2.fromScale(0.5, 0.5),
				AnchorPoint = Vector2.new(0.5, 0.5),
				ZIndex = 7,
			})
		end
	
		-- The title gives up the width of the badge and the chevron it sits between, or the row layout
		-- would push the control off the card on a full parent-width label.
		local inset = (options.Icon ~= nil and 25 or 0) + (options.Collapsible == true and 31 or 0)
	
		self.TitleLabel = Element.label(self.Maid, self.Header, "Title", {
			Text = self.Title,
			Role = "TextPrimary",
			Font = "Title",
			TextSize = 14,
			LayoutOrder = 1,
			Size = UDim2.new(1, -inset, 1, 0),
			ZIndex = 5,
		})
	
		if options.Collapsible == true then
			self:_buildChevron()
		end
	
		-- Content sits under the header by explicit offset rather than as a sibling in a list layout:
		-- the header auto-sizes with its title, and a second list inside the panel would fight the
		-- group's own AutomaticSize on a client that resolves them in a different order.
		self.Content = Element.panel(self.Maid, self.Panel, "Rows", {
			Transparency = 1,
			Size = UDim2.new(1, -padding * 2, 0, 0),
			Position = UDim2.new(0, padding, 0, headerH + 10),
			ZIndex = 4,
		})
		self.Content.AutomaticSize = Enum.AutomaticSize.Y
		self.RowList = Instance.new("UIListLayout", self.Content, {
			Padding = UDim.new(0, 8),
			FillDirection = Enum.FillDirection.Vertical,
			SortOrder = Enum.SortOrder.LayoutOrder,
		})
	
		self._bottomPadding = Instance.new("UIPadding", self.Panel, {
			PaddingBottom = UDim.new(0, padding),
		})
		self._topGap = headerH + 10 + padding
	
		local text = self.Title
		if type(self.Desc) == "string" and self.Desc ~= "" then
			text = self.Title .. " — " .. self.Desc
		end
	
		self.SearchId = "group:" .. tostring(tab.Title) .. "/" .. self.Title
		SearchManager.register({
			Id = self.SearchId,
			Label = self.Title,
			Text = text,
			Tab = tab.Title,
			OnMatch = function(_entry, isMatch)
				self:_onMatch(isMatch)
			end,
		})
	
		Container.decorate(self, {
			Maid = self.Maid,
			Parent = self.Content,
			Window = self.Window,
			Tab = tab,
			Group = self,
		})
	
		return self
	end
	
	--- The card's own collapse control, in its header at the far right. Rotating the glyph rather
	--- than swapping it keeps one icon instance, and an icon swap on a themed glyph would have to
	--- re-resolve its colour anyway.
	function Groupbox:_buildChevron()
		local maid = self.Maid
	
		local button = Instance.new("TextButton", self.Header, {
			Name = "Collapse",
			Text = "",
			AutoButtonColor = false,
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(24, 24),
			LayoutOrder = 2,
			BorderSizePixel = 0,
			ZIndex = 6,
		})
		maid:giveFunction(function()
			button:Destroy()
		end)
		self.CollapseButton = button
	
		self._chevron = Element.icon(maid, button, "chevronDown", {
			Role = "TextMuted",
			Size = UDim2.fromOffset(12, 12),
			Position = UDim2.fromScale(0.5, 0.5),
			AnchorPoint = Vector2.new(0.5, 0.5),
			ZIndex = 7,
		})
	
		Element.interactive(button, {
			Maid = maid,
			OnClick = function()
				self:SetCollapsed(not self.Collapsed)
			end,
		})
	
		TooltipManager.attach(button, "Collapse this section")
	end
	
	--- Show or hide the card's rows. The panel auto-sizes from its children, so hiding the content is
	--- the whole animation budget — no height bookkeeping to fall out of sync with the rows.
	function Groupbox:SetCollapsed(collapsed: boolean): boolean
		if not self.Collapsible then
			return self.Collapsed
		end
	
		self.Collapsed = collapsed == true
		self.Content.Visible = not self.Collapsed
	
		if self._chevron ~= nil and self._chevron.instance ~= nil then
			Guard.set(self._chevron.instance, "Rotation", self.Collapsed and -90 or 0)
		end
	
		return self.Collapsed
	end
	
	Groupbox.Collapse = Groupbox.SetCollapsed
	
	function Groupbox:Mount(parent: any)
		if self.Destroyed or self.Mounted or parent == nil then
			return false
		end
		self.Panel.Parent = parent
		self.Mounted = true
		self:_applyFilter()
		return true
	end
	
	--- A group mounted while a search is running has to honour it immediately: its rows were built
	--- before the panel ever reached the tree, so nothing has told them to hide.
	function Groupbox:_applyFilter()
		local query = SearchManager.term()
		if query == "" or self.Destroyed then
			return
		end
	
		self._titleMatched = SearchManager.passes(self.SearchId)
		self._matchedSet = {}
		self._matched = 0
		for _, id in ipairs(self._rows) do
			if self._titleMatched or SearchManager.passes(id) then
				self._matchedSet[id] = true
				self._matched += 1
			end
		end
	
		-- Rows built while the query was live hid themselves on registration, against the card they were
		-- not yet mounted into. A card that the query reaches through its own title or description comes
		-- back open with them.
		if self._titleMatched then
			for _, id in ipairs(self._rows) do
				local row = self._rowsById[id]
				if row ~= nil and not row.Destroyed then
					if row.Instance ~= nil then
						row.Instance.Visible = true
					end
					if row.OnFilter ~= nil then
						row.OnFilter(true)
					end
				end
			end
		end
	
		self:_updateVisibility()
	end
	
	--- Called by a component row when the live search term includes or excludes it. The count is
	--- incremental because a page of forty rows must not rescan the index on every keystroke.
	function Groupbox:reportRow(id: any, isMatch: boolean)
		-- A row reporting "no match" for the first time is not a row that stopped matching: treating the
		-- absent entry as a transition would put the count negative on any card whose first row fails,
		-- and a card with a real match alongside it would hide.
		local was = self._matchedSet[id] == true
		local now = isMatch == true
		if was == now then
			return
		end
	
		self._matchedSet[id] = now
		self._matched += now and 1 or -1
		self:_updateVisibility()
	end
	
	--- Release a row that was destroyed on its own. Leaving its count set is what keeps a filtered page
	--- honest: a card held open by a row the user can no longer click is the stale-index bug the search
	--- system exists to avoid. The id stays in `_rows` on purpose — that list is the card's ordering
	--- cursor, and a slot that opened behind a survivor would put the next row beside it, not last.
	function Groupbox:forget(id: any): boolean
		if id == nil then
			return false
		end
	
		SearchManager.unregister(id)
		self._rowsById[id] = nil
	
		if self._matchedSet[id] == true then
			self._matchedSet[id] = nil
			self._matched -= 1
		end
	
		self:_updateVisibility()
		return true
	end
	
	function Groupbox:RowCount(): number
		return #self._rows
	end
	
	function Groupbox:_onMatch(isMatch: boolean)
		-- Set before the rows report: a card found through its own title or description opens with its
		-- rows in it, because its index entry is the only place those words are written.
		self._titleMatched = isMatch == true
		self:_updateVisibility()
	end
	
	function Groupbox:_updateVisibility()
		if self.Destroyed or not self.Mounted then
			return
		end
	
		local query = SearchManager.term()
		if query == "" then
			self:_setVisible(false)
			return
		end
	
		local anyRow = self._matched > 0
		-- `hidden` is the awkward polarity here: the caller below passes the boolean the panel's own
		-- `Visible` must be inverted from, so a card with a matching row or a matching title stays up.
		self:_setVisible(not (anyRow or self._titleMatched == true))
	end
	
	function Groupbox:_setVisible(hidden: boolean)
		if self._hidden == hidden then
			return
		end
		self._hidden = hidden
		self.Panel.Visible = not hidden
	end
	
	function Groupbox:IsVisibleToSearch(): boolean
		return not self._hidden
	end
	
	--- Components call this to have a row participate in search filtering.
	function Groupbox:track(row: any, label: string, extra: string?)
		local id = "row:" .. tostring(self.Title) .. "/" .. tostring(label)
		local haystack = table.concat({ self.Title, self.Tab.Title, label, extra or "" }, " "):lower()
	
		SearchManager.register({
			Id = id,
			Label = label,
			Text = haystack,
			Tab = self.Tab.Title,
			OnMatch = function(_entry, isMatch)
				-- Destroying a row releases it through `Groupbox:forget`, so by the time a keystroke
				-- reaches this callback the index no longer holds a card for it.
				if row.Destroyed then
					return
				end
	
				-- The card is indexed under its own title and description, which no row repeats, so a
				-- section found that way opens with its rows instead of as an empty panel.
				local show = isMatch == true or self._titleMatched == true
	
				self:reportRow(id, show)
				if row.Instance ~= nil then
					row.Instance.Visible = show
				end
				if row.OnFilter ~= nil then
					-- Called plain, because a handle's methods are fields: the shim each widget uses
					-- (`Element.recv`) reads the boolean from the first argument when the library calls
					-- it this way and from the second when a host calls the same method with a colon.
					row.OnFilter(show)
				end
			end,
		})
	
		table.insert(self._rows, id)
		self._rowsById[id] = row
		return id
	end
	
	--- Rename the card. The index entry is re-registered under the new title rather than left pointing
	--- at the old one, because a host that renames a section at runtime expects the new name to be
	--- searchable. The rows keep the ids they were registered with; only their card's entry moves.
	function Groupbox:SetTitle(text: string)
		self.Title = text
		self.TitleLabel.Text = text
	
		local haystack = text
		if type(self.Desc) == "string" and self.Desc ~= "" then
			haystack = text .. " — " .. tostring(self.Desc)
		end
	
		local previous = self.SearchId
		self.SearchId = "group:" .. tostring(self.Tab.Title) .. "/" .. text
		if previous ~= self.SearchId then
			SearchManager.unregister(previous)
		end
	
		SearchManager.register({
			Id = self.SearchId,
			Label = text,
			Text = haystack,
			Tab = self.Tab.Title,
			OnMatch = function(_entry, isMatch)
				self:_onMatch(isMatch)
			end,
		})
		self:_applyFilter()
	end
	
	function Groupbox:Destroy()
		if self.Destroyed then
			return
		end
		self.Destroyed = true
		-- The maid owns the search bookkeeping (see the note in `new`), so destroying the card takes its
		-- rows out of the index as well.
		self.Maid:cleanup()
		self.Panel:Destroy()
	end
	
	return Groupbox
end

-- src/Core/Library.lua
FluxRegistry["Flux/Core/Library"] = function(require)
	--[[
		Core/Library — the object a hub receives from the loader.

		Everything below is a façade over the systems, which are singletons: two windows share one
		theme, one renderer and one notification stack, because that is what makes a menu that is open
		in two places repaint as one thing. The façade exists so host code reads as

			local Flux = loadstring(game:HttpGet(url))()
			local Window = Flux:Window({ Title = "Flux", ToggleKey = Enum.KeyCode.RightControl })
			local Tab = Window:Tab({ Title = "Aim", Icon = "crosshair" })
			Tab:GroupBox({ Title = "Legit" }):Toggle({ Name = "Silent aim", Default = false })

		rather than as a tour of the module graph.
	]]

	local Element = require("Flux/Core/Element")
	local Guard = require("Flux/Utilities/Guard")
	local Signal = require("Flux/Utilities/Signal")
	local Lifecycle = require("Flux/Core/Lifecycle")
	local Container = require("Flux/Core/Container")
	local WindowModule = require("Flux/Core/Window")

	local ThemeManager = require("Flux/Systems/ThemeManager")
	local NotificationManager = require("Flux/Systems/NotificationManager")
	local ConfigManager = require("Flux/Systems/ConfigManager")
	local InputManager = require("Flux/Systems/InputManager")
	local TooltipManager = require("Flux/Systems/TooltipManager")
	local AnimationManager = require("Flux/Systems/AnimationManager")
	local LayoutManager = require("Flux/Systems/LayoutManager")
	local Renderer = require("Flux/Systems/Renderer")
	local IconManager = require("Flux/Systems/IconManager")
	local SearchManager = require("Flux/Systems/SearchManager")

	local Library = {}
	Library.__index = Library

	function Library.new(options: {[string]: any}?)
		options = options or {}

		local self = setmetatable({
			Version = "0.0.0-dev",
			Windows = {},
			Closed = Signal.new(),
			Options = options,
		}, Library)

		if type(options.Theme) == "string" then
			ThemeManager.use(options.Theme)
		elseif type(options.Theme) == "table" then
			ThemeManager.set(options.Theme)
		end

		if type(options.Notifications) == "table" then
			NotificationManager.configure(options.Notifications)
		end

		if type(options.Tooltips) == "table" then
			TooltipManager.configure(options.Tooltips)
		end

		if type(options.Renderer) == "table" then
			Renderer.configure(options.Renderer)
		end

		if type(options.Icons) == "table" then
			IconManager.configure(options.Icons)
		end

		if options.Config ~= false then
			ConfigManager.configure(type(options.Config) == "table" and options.Config or nil)
		end

		if type(options.BaseSize) == "number" then
			LayoutManager.setBase(options.BaseSize, options.BaseSize * 0.62)
		end

		AnimationManager.setReducedMotion(options.ReducedMotion == true)
		return self
	end

	--- Create a window. The first one is what `Flux:Notify`, `Flux:Search` and the toggle key act on.
	function Library:Window(options: any)
		if type(options) == "string" then
			options = { Title = options }
		end

		local window = WindowModule.new(self, options or {})
		table.insert(self.Windows, window)
		self.Primary = self.Primary or window

		local onClosed = options and options.OnClose
		if type(onClosed) == "function" then
			Lifecycle.onClose(function()
				onClosed(window)
			end)
		end
		return window
	end

	Library.CreateWindow = Library.Window
	Library.NewWindow = Library.Window

	function Library:GetWindow(title: string): any
		for _, window in ipairs(self.Windows) do
			if window.Title == title then
				return window
			end
		end
		return nil
	end

	--- A second window in the same hub. The reference design shows one, but a script that separates
	--- config from gameplay controls asks for this constantly.
	function Library:WindowList(): {any}
		return self.Windows
	end

	function Library:Notify(options: any)
		return NotificationManager.notify(options)
	end

	--- `Flux:SetTheme("Purple")` or `Flux:SetTheme{ Accent = Color3.fromRGB(...) }`.
	function Library:SetTheme(value: any): {[string]: any}
		if type(value) == "string" then
			ThemeManager.use(value)
		elseif type(value) == "table" then
			-- A restored snapshot carries name/colors/metrics/fonts; anything else is a flat override
			-- table, and the two shapes must not be confused for each other.
			if value.colors ~= nil or value.metrics ~= nil or value.name ~= nil then
				ThemeManager.restore(value)
			else
				ThemeManager.set(value)
			end
		end
		return ThemeManager.snapshot()
	end

	function Library:GetTheme(): {[string]: any}
		return ThemeManager.snapshot()
	end

	function Library:OnThemeChanged(fn: () -> ()): () -> ()
		local connection = ThemeManager.Changed:Connect(fn)
		return function()
			connection:Disconnect()
		end
	end

	--- Search across every window's registered controls.
	function Library:Search(term: string): number
		local matched = SearchManager.set(term)
		for _, window in ipairs(self.Windows) do
			for _, tab in ipairs(window.TabOrder) do
				tab:RefreshSearch()
			end
		end
		return matched
	end

	function Library:Save(name: string?): boolean
		return ConfigManager.save(name)
	end

	function Library:Load(name: string?): boolean
		local ok = ConfigManager.load(name)
		if ok then
			self:_applyConfiguredState()
		end
		return ok
	end

	--- Push stored values into rows that exist and record what should be applied to rows that do not
	--- exist yet, which is the whole reason bindings live in the config system and not in the widgets.
	function Library:_applyConfiguredState(): number
		local applied = ConfigManager.push()
		for _, window in ipairs(self.Windows) do
			for _, tab in ipairs(window.TabOrder) do
				if tab.Page ~= nil then
					for _, group in ipairs(tab.Groups) do
						group:_applyFilter()
					end
				end
			end
		end
		return applied
	end

	function Library:Config(): any
		return ConfigManager
	end

	function Library:Input(): any
		return InputManager
	end

	function Library:AddComponent(name: string, module: any): boolean
		return Container.register(name, module)
	end

	--- The system handles, for a host that wants to reach past the façade.
	function Library:System(name: string): any
		local systems = {
			theme = ThemeManager,
			icons = IconManager,
			animation = AnimationManager,
			config = ConfigManager,
			input = InputManager,
			layout = LayoutManager,
			notifications = NotificationManager,
			renderer = Renderer,
			search = SearchManager,
			tooltip = TooltipManager,
			element = Element,
			guard = Guard,
		}
		return systems[string.lower(tostring(name))]
	end

	function Library:OnClose(fn: () -> ())
		return Lifecycle.onClose(fn)
	end

	--- Every keybind the hub owns, so a script can list them in its own UI.
	function Library:Binds(): {any}
		return InputManager.list()
	end

	function Library:WindowCount(): number
		return Lifecycle.count()
	end

	--- The full teardown. Closes windows, releases every bind and listener, and drops the floating
	--- surfaces. Re-running the same loader afterwards builds a fresh hub.
	function Library:Unload()
		if self._unloaded then
			return false
		end
		self._unloaded = true

		local destroyed = Lifecycle.closeAll()

		Renderer.cancel()
		Renderer.reset()
		AnimationManager.stopAll()
		NotificationManager.destroy()
		TooltipManager.destroy()
		InputManager.unload()
		SearchManager.clear()
		LayoutManager.unwatch()

		self.Closed:Dispatch(destroyed)
		self.Closed:Destroy()
		self.Windows = {}
		self.Primary = nil
		return true
	end

	Library.Destroy = Library.Unload
	Library.Close = Library.Unload

	function Library:IsUnloaded(): boolean
		return self._unloaded == true
	end

	--- Toggle every window open or closed with one call — the behaviour a single hotkey is expected
	--- to have.
	function Library:Toggle(force: boolean?)
		local primary = self.Primary
		if primary == nil then
			return false
		end

		if force == nil then
			primary:Toggle()
		elseif force then
			primary:Show()
		else
			primary:Hide()
		end
		return primary.Open
	end

	return Library
end

-- src/Core/Lifecycle.lua
FluxRegistry["Flux/Core/Lifecycle"] = function(require)
	--[[
		Core/Lifecycle — the list of things a hub owns, and the one path that releases all of them.

		`Flux:Unload()` has to be callable from a keybind, from a menu button, and from a script that
		is being re-executed, and it has to leave the client exactly as it found it. That only works if
		every owner registers itself here instead of each widget guessing when it may be freed, and if
		teardown runs in one order: windows first (they hold the UI), then the systems they used.

		Close callbacks fire once. A hub that unloads twice must not run its save routine twice.
	]]

	local Maid = require("Flux/Utilities/Maid")

	local Lifecycle = {}

	--- A destroyed instance raises on any property read, which is the only reliable liveness test
	--- that works without holding an event connection per window.
	local function dead(instance: any): boolean
		if instance == nil then
			return true
		end
		return not pcall(function()
			return (instance :: any).Name
		end)
	end

	local windows = {}
	local closing = {}
	local closed = false
	local shared = Maid.new()

	function Lifecycle.maid(): any
		return shared
	end

	--- A window registers itself so `Unload` can destroy it without the caller keeping the handle.
	function Lifecycle.register(window: any): any
		for index = #windows, 1, -1 do
			if dead(windows[index]) then
				table.remove(windows, index)
			end
		end

		table.insert(windows, window)
		return window
	end

	function Lifecycle.unregister(window: any): number
		local removed = 0
		for index = #windows, 1, -1 do
			if windows[index] == window then
				table.remove(windows, index)
				removed += 1
			end
		end
		return removed
	end

	function Lifecycle.windows(): {any}
		return windows
	end

	function Lifecycle.count(): number
		return #windows
	end

	--- Runs immediately if the hub is already closed, so a script that tears itself down and then
	--- registers a cleanup still gets it.
	function Lifecycle.onClose(fn: () -> ()): () -> ()
		if type(fn) ~= "function" then
			return function() end
		end

		if closed then
			local ok, err = pcall(fn)
			if not ok then
				warn("[Flux] close handler: " .. tostring(err))
			end
			return function() end
		end

		table.insert(closing, fn)

		return function()
			for index = #closing, 1, -1 do
				if closing[index] == fn then
					table.remove(closing, index)
					break
				end
			end
		end
	end

	function Lifecycle.isClosed(): boolean
		return closed
	end

	--- Destroy every window, release the shared maid, then run the close handlers. Returns how many
	--- windows were torn down, which is what a host checks when it wants to know if its UI was live.
	function Lifecycle.closeAll(): number
		local destroyed = 0

		-- Iterating a copy: a window's Destroy unregisters it from the live list.
		local snapshot = {}
		for index = 1, #windows do
			snapshot[index] = windows[index]
		end

		for _, window in ipairs(snapshot) do
			local ok, err = pcall(function()
				window:Destroy()
			end)
			if ok then
				destroyed += 1
			else
				warn("[Flux] window teardown: " .. tostring(err))
			end
		end

		table.clear(windows)
		shared:cleanup()

		-- Set before the handlers run: a handler that calls Unload must not recurse into itself.
		closed = true

		local handlers = closing
		closing = {}
		for _, fn in ipairs(handlers) do
			local ok, err = pcall(fn)
			if not ok then
				warn("[Flux] close handler: " .. tostring(err))
			end
		end

		return destroyed
	end

	--- Only a test or a host that intends to reopen the same library object can be un-closed.
	function Lifecycle.reopen()
		closed = false
		shared = Maid.new()
	end

	function Lifecycle.reset()
		table.clear(windows)
		table.clear(closing)
		closed = false
		shared = Maid.new()
	end

	return Lifecycle
end

-- src/Core/Tab.lua
FluxRegistry["Flux/Core/Tab"] = function(require)
	--[[
		Core/Tab — one nav entry and the page it owns.
	
		A tab is lazy in two stages. Its page (the scrolling frame and two columns) is not created
		until the tab is first opened, and the groupboxes inside it are built through the renderer when
		the page is heavy. Both matter for the same reason: a hub with nine tabs costs one tab's worth
		of instances to open, not nine.
	
		The nav button and the page live in different parents on purpose — the strip belongs to the
		window, the content to this object — so switching tabs is two visibility writes.
	
		A pill is auto-width rather than a fixed cell: tab titles are authored by the host, and a
		30px column per character of "Configuration" is how a nav ends up truncating the one tab
		someone actually needs to find.
	]]
	
	local Maid = require("Flux/Utilities/Maid")
	local Instance = require("Flux/Utilities/Instance")
	local Element = require("Flux/Core/Element")
	local Guard = require("Flux/Utilities/Guard")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	local AnimationManager = require("Flux/Systems/AnimationManager")
	local TooltipManager = require("Flux/Systems/TooltipManager")
	local SearchManager = require("Flux/Systems/SearchManager")
	local Renderer = require("Flux/Systems/Renderer")
	
	local Tab = {}
	Tab.__index = Tab
	
	local function metric(role: string, fallback: number): number
		return ThemeManager.metric(role) or fallback
	end
	
	function Tab.new(window: any, options: {[string]: any})
		options = Element.options(options, {
			Title = "Tab",
			Icon = "dot",
			Desc = nil,
			Order = nil,
		})
	
		local self = setmetatable({
			Window = window,
			Title = tostring(options.Title),
			Icon = options.Icon,
			Desc = options.Desc,
			Groups = {},
			_deferred = {},
			Active = false,
			Built = false,
			Destroyed = false,
			SingleColumn = false,
			Matches = nil,
		}, Tab)
	
		self.Maid = Maid.new()
		window.Maid:giveFunction(function()
			self.Maid:cleanup()
		end)
	
		-- The pills go in the strip's scrolling frame, not the bar behind it: that frame is the one with
		-- the horizontal list and the automatic canvas width, so a hub with nine tabs can reach them.
		self:_buildNav(window.NavScroller or window.Nav, options)
		return self
	end
	
	function Tab:_buildNav(parent: any, options: {[string]: any})
		local maid = self.Maid
	
		local button = Instance.new("TextButton", parent, {
			Name = "Nav_" .. self.Title,
			Text = "",
			AutoButtonColor = false,
			BackgroundTransparency = 1,
			Size = UDim2.new(0, 0, 0, 34),
			BorderSizePixel = 0,
			LayoutOrder = options.Order or (#self.Window.TabOrder + 1),
			ZIndex = 5,
		})
		maid:giveFunction(function()
			button:Destroy()
		end)
		button.AutomaticSize = Enum.AutomaticSize.X
		self.NavButton = button
	
		-- The fill is a sibling rather than the button's own background, because the button auto-sizes
		-- its width from its children and a rounded fill needs to inset from that box.
		local fill = Element.panel(maid, button, "Fill", {
			Color = "Selection",
			Radius = "RadiusField",
			Size = UDim2.new(1, 0, 1, 0),
			ZIndex = 5,
			Visible = false,
		})
		self.NavFill = fill
	
		local bar = Instance.new("Frame", button, {
			Name = "ActiveBar",
			BackgroundColor3 = ThemeManager.color("Accent"),
			Size = UDim2.new(1, -16, 0, 2),
			Position = UDim2.new(0, 8, 1, 7),
			BorderSizePixel = 0,
			Visible = false,
			ZIndex = 6,
		})
		maid:give(ThemeManager.bind(bar, "BackgroundColor3", "Accent"))
		maid:giveFunction(function()
			bar:Destroy()
		end)
		Element.round(maid, bar, "RadiusChip", -2)
		self.NavBar = bar
	
		local row = Instance.new("UIListLayout", button, {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 7),
		})
		maid:giveFunction(function()
			row:Destroy()
		end)
	
		local inset = Instance.new("UIPadding", button, {
			PaddingLeft = UDim.new(0, 11),
			PaddingRight = UDim.new(0, 11),
		})
		maid:giveFunction(function()
			inset:Destroy()
		end)
	
		self.NavIcon = Element.icon(maid, button, self.Icon or "dot", {
			Role = "TextSecondary",
			Size = UDim2.fromOffset(15, 15),
			LayoutOrder = 0,
			ZIndex = 6,
		})
	
		self.NavLabel = Element.label(maid, button, "Label", {
			Text = self.Title,
			Role = "TextSecondary",
			TextSize = 13,
			AutoWidth = true,
			LayoutOrder = 1,
			Size = UDim2.new(0, 0, 1, 0),
			ZIndex = 6,
		})
	
		Element.interactive(button, {
			Maid = maid,
			OnClick = function()
				self:Open()
			end,
			OnEnter = function()
				if not self.Active then
					self.NavFill.Visible = true
				end
			end,
			OnLeave = function()
				if not self.Active then
					self.NavFill.Visible = false
				end
			end,
		})
	
		if type(self.Desc) == "string" and self.Desc ~= "" then
			TooltipManager.attach(button, self.Desc)
		end
	end
	
	--- The page is built the first time the tab is opened, not when it is declared.
	function Tab:_buildPage()
		if self.Built then
			return
		end
		self.Built = true
	
		local maid = self.Maid
		local padding = metric("ContentPadding", 18)
	
		local page = Instance.new("ScrollingFrame", self.Window.ContentHost, {
			Name = "Page_" .. self.Title,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ScrollBarThickness = 4,
			ScrollBarImageColor3 = ThemeManager.color("BorderSecondary"),
			ScrollingDirection = Enum.ScrollingDirection.Y,
			ScrollingEnabled = true,
			AutomaticCanvasSize = Enum.AutomaticSize.Y,
			CanvasSize = UDim2.new(),
			Size = UDim2.fromScale(1, 1),
			Visible = false,
			ZIndex = 3,
		})
		maid:give(ThemeManager.bind(page, "ScrollBarImageColor3", "BorderSecondary"))
		maid:giveFunction(function()
			page:Destroy()
		end)
		self.Page = page
		self.Window.Pages[self.Title] = page
	
		Instance.new("UIPadding", page, {
			PaddingTop = UDim.new(0, padding),
			PaddingBottom = UDim.new(0, padding),
			PaddingLeft = UDim.new(0, padding),
			PaddingRight = UDim.new(0, padding),
		})
	
		local list = Instance.new("UIListLayout", page, {
			Padding = UDim.new(0, metric("ColumnGap", 16)),
			FillDirection = Enum.FillDirection.Horizontal,
			HorizontalAlignment = Enum.HorizontalAlignment.Left,
			VerticalAlignment = Enum.VerticalAlignment.Top,
			SortOrder = Enum.SortOrder.LayoutOrder,
		})
		maid:giveFunction(function()
			list:Destroy()
		end)
		self.PageList = list
	
		self.ColumnLeft = self:_buildColumn("ColumnLeft", 0)
		self.ColumnRight = self:_buildColumn("ColumnRight", 1)
	
		-- Cards declared before this page existed enter it now, in the column their declaration chose.
		for _, group in ipairs(self.Groups) do
			self:_mount(group, group.Side)
		end
	
		-- Blocks parked with `tab:Defer` build here, once the columns they declare into actually exist.
		self:_runDeferred()
	
		self.EmptyNotice = Element.label(maid, page, "Empty", {
			Text = "Nothing matches that search.",
			Role = "TextMuted",
			TextSize = 13,
			Alignment = Enum.TextXAlignment.Center,
			Size = UDim2.new(1, 0, 0, 20),
			Visible = false,
			ZIndex = 4,
		})
		-- A label inside a list layout joins the column flow; pinning it to the page keeps it centred
		-- over whatever is left once every group has been filtered out.
		self.EmptyNotice.LayoutOrder = 999
	end
	
	--- Park a block of declarations until the page exists. `tab:Toggle{…}` creates instances at the
	--- moment it is called, which is the boot frame for a hub that declares every tab up front; a page
	--- built inside `Defer` is created on the tab's first open instead. A tab that is already open has
	--- nothing to wait for, so the block runs immediately.
	function Tab:Defer(build: any): boolean
		if type(build) ~= "function" then
			warn("[Flux] tab:Defer needs a function")
			return false
		end
	
		if self.Built then
			local ok, err = pcall(build, self)
			if not ok then
				warn("[Flux] deferred block on tab '" .. tostring(self.Title) .. "': " .. tostring(err))
			end
			return ok
		end
	
		table.insert(self._deferred, build)
		return true
	end
	
	function Tab:_runDeferred()
		local blocks = self._deferred
		if #blocks == 0 then
			return
		end
		self._deferred = {}
	
		for _, build in ipairs(blocks) do
			local ok, err = pcall(build, self)
			if not ok then
				warn("[Flux] deferred block on tab '" .. tostring(self.Title) .. "': " .. tostring(err))
			end
		end
	end
	
	function Tab:_buildColumn(name: string, order: number): any
		local maid = self.Maid
		local column = Element.panel(maid, self.Page, name, {
			Transparency = 1,
			Size = UDim2.new(0.5, -8, 0, 0),
			LayoutOrder = order,
			ZIndex = 3,
		})
		column.AutomaticSize = Enum.AutomaticSize.Y
	
		local list = Instance.new("UIListLayout", column, {
			Padding = UDim.new(0, metric("GroupGap", 14)),
			FillDirection = Enum.FillDirection.Vertical,
			SortOrder = Enum.SortOrder.LayoutOrder,
		})
		maid:giveFunction(function()
			list:Destroy()
		end)
		return column
	end
	
	--- Build a groupbox into this tab. `Side` picks the column; on a compact page both columns are
	--- full width and stacked, so the side becomes row order instead.
	function Tab:GroupBox(options: any)
		if type(options) == "string" then
			options = { Title = options }
		end
	
		local Groupbox = require("Flux/Core/Groupbox")
		local group = Groupbox.new(self, options or {})
	
		table.insert(self.Groups, group)
	
		-- The side is chosen at declaration, before the page exists, so the alternation the author wrote
		-- survives a tab that is opened much later.
		group.Side = self:_sideFor(options)
		if self.Built then
			self:_mount(group, group.Side)
		end
		return group
	end
	
	--- Put a card's panel into its column, through the renderer. Mounting is the expensive half of
	--- opening a page — parenting a subtree is what makes the engine lay it out — so it is queued with
	--- a cost instead of happening in the click handler.
	function Tab:_mount(group: any, side: string?): boolean
		if group == nil or group.Mounted or group.Destroyed or not self.Built then
			return false
		end
	
		local column = side == "left" and self.ColumnLeft or self.ColumnRight
		if column == nil then
			return false
		end
	
		Renderer.enqueue({
			Name = "mount/" .. tostring(self.Title) .. "/" .. tostring(group.Title),
			Cost = 6 + group:RowCount() * 6,
			Run = function()
				-- The tab can close, or the card be destroyed, while its job waits in the queue.
				if self.Destroyed or self.Page == nil then
					return
				end
				group:Mount(column)
			end,
		})
		return true
	end
	
	Tab.Section = Tab.GroupBox
	Tab.AddSection = Tab.GroupBox
	Tab.AddGroupBox = Tab.GroupBox
	
	--- Which column a card belongs in, resolved at declaration so the alternation follows the order the
	--- author wrote the sections in rather than the order their pages happened to open.
	function Tab:_sideFor(options: {[string]: any}): string
		local side = options and options.Side
		if side == nil then
			-- Unspecified sides alternate, which is what makes a page of six sections read as two
			-- columns of three rather than one long ribbon.
			self._side = self._side == "left" and "right" or "left"
			side = self._side
		end
		return string.lower(tostring(side)) == "left" and "left" or "right"
	end
	
	function Tab:_columnFor(options: {[string]: any}): any
		local side = self:_sideFor(options)
		if side == "left" then
			return self.ColumnLeft
		end
		return self.ColumnRight
	end
	
	function Tab:Open()
		if self.Destroyed then
			return
		end
	
		self:_buildPage()
		self.Window:_setActive(self)
		for _, other in ipairs(self.Window.TabOrder) do
			if other.Page ~= nil then
				other.Page.Visible = other == self
			end
			other:SetSelected(other == self)
		end
	
		self.Active = true
		if self.Page ~= nil then
			AnimationManager.play(self.Page, "FadeIn", { Duration = 0.18 })
		end
	
		self.Window:onViewportChanged()
		if self.Window._onTabChanged ~= nil then
			self.Window._onTabChanged(self)
		end
	end
	
	Tab.SetActive = Tab.Open
	
	function Tab:SetSelected(selected: boolean)
		self.Active = selected
		if self.NavButton == nil then
			return
		end
	
		self.NavFill.Visible = selected
		self.NavBar.Visible = selected
	
		-- Re-bound rather than written: a plain colour assignment here is exactly what the next theme
		-- swap would repaint away.
		Element.tint(self.Maid, self.NavLabel, "TextColor3", selected and "TextPrimary" or "TextSecondary")
		self.NavIcon:setRole(selected and "Accent" or "TextSecondary")
	end
	
	--- A phone-sized window stacks the page into one column. The strip is unaffected — it already
	--- scrolls sideways — so this is the only responsive write a tab makes.
	function Tab:SetSingleColumn(single: boolean)
		self.SingleColumn = single
		if not self.Built then
			return
		end
	
		if single then
			self.PageList.FillDirection = Enum.FillDirection.Vertical
			self.ColumnLeft.Size = UDim2.new(1, 0, 0, 0)
			self.ColumnRight.Size = UDim2.new(1, 0, 0, 0)
		else
			self.PageList.FillDirection = Enum.FillDirection.Horizontal
			self.ColumnLeft.Size = UDim2.new(0.5, -8, 0, 0)
			self.ColumnRight.Size = UDim2.new(0.5, -8, 0, 0)
		end
	end
	
	--
	-- Search
	--
	
	--- Called by `Window:Search` after the index has filtered every row. Rows and groups already hid
	--- themselves through their match callbacks, so what is left are the two decisions only a tab can
	--- make: whether its page has anything to show, and whether its pill should stay clickable.
	function Tab:Filter(query: string): boolean
		local has = query == "" or self:AnyGroupVisible()
	
		if self.NavButton ~= nil then
			self.NavButton.Visible = has
		end
	
		-- An unopened page has no visible notice to speak of, and hiding a pill the user can still
		-- open would strand them on a page they cannot reach.
		if query == "" then
			self:SetEmptyNotice(false)
		elseif self.Active then
			self:SetEmptyNotice(not has)
		end
	
		return has
	end
	
	function Tab:RefreshSearch(): boolean
		local visible = 0
		for _, group in ipairs(self.Groups) do
			if group:IsVisibleToSearch() then
				visible += 1
			end
		end
	
		if self.NavButton ~= nil then
			local query = SearchManager.term()
			self.NavButton.Visible = query == "" or visible > 0
		end
	
		return visible > 0
	end
	
	function Tab:AnyGroupVisible(): boolean
		for _, group in ipairs(self.Groups) do
			if group:IsVisibleToSearch() then
				return true
			end
		end
		return false
	end
	
	--- The page has nothing to show but is still the open tab, so say so instead of rendering a void.
	function Tab:SetEmptyNotice(state: boolean)
		if self.EmptyNotice == nil then
			return
		end
		self.EmptyNotice.Visible = state == true
	end
	
	function Tab:GroupCount(): number
		return #self.Groups
	end
	
	function Tab:Rows(): number
		local rows = 0
		for _, group in ipairs(self.Groups) do
			rows += group:RowCount()
		end
		return rows
	end
	
	return Tab
end

-- src/Core/Window.lua
FluxRegistry["Flux/Core/Window"] = function(require)
	--[[
		Core/Window — the shell: chrome, drag, navigation, and the content area a tab builds into.

		Three decisions here shape the rest of the library:

		  * The window is positioned by an offset of its own centre, in the layout's authored units,
		    with AnchorPoint (0.5, 0.5). A drag accumulates the pointer delta divided by the live
		    UIScale (LayoutManager.toLocal), because a screen pixel moves a window 1/scale authored
		    units — multiply the raw mouse delta instead and the window drifts away from the cursor on
		    any device that is not rendering at the authored size.
		  * Navigation is a horizontal strip under the header, not a left rail. A rail spends 196px of
		    a 900px window on nine words, and the page is what people read; the strip scrolls sideways
		    when it overflows instead of reflowing into a second layout.
		  * A tab's rows are not built until the tab is opened. The window itself is about forty
		    instances; the first page is the cost, so that is what gets sliced across frames.
	]]

	local Maid = require("Flux/Utilities/Maid")
	local Instance = require("Flux/Utilities/Instance")
	local Element = require("Flux/Core/Element")
	local Guard = require("Flux/Utilities/Guard")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	local LayoutManager = require("Flux/Systems/LayoutManager")
	local AnimationManager = require("Flux/Systems/AnimationManager")
	local NotificationManager = require("Flux/Systems/NotificationManager")
	local TooltipManager = require("Flux/Systems/TooltipManager")
	local InputManager = require("Flux/Systems/InputManager")
	local SearchManager = require("Flux/Systems/SearchManager")
	local Lifecycle = require("Flux/Core/Lifecycle")
	local Math = require("Flux/Utilities/Math")

	local UserInputService = Guard.service("UserInputService")

	local Window = {}
	Window.__index = Window

	local SEARCH_WIDTH = 210
	local SEARCH_HEIGHT = 30
	local CLUSTER_WIDTH = 300

	local function metric(role: string, fallback: number): number
		return ThemeManager.metric(role) or fallback
	end

	local function headerHeight(): number
		return metric("HeaderHeight", 72)
	end

	local function footerHeight(): number
		return metric("FooterHeight", 40)
	end

	--- A 28px square icon button in the header: minimise and close, and nothing else. The reference
	--- design keeps the chrome quiet, so these never carry a border.
	local function iconButton(maid: any, parent: any, name: string, glyph: string, onClick: () -> ()): any
		local button = Instance.new("TextButton", parent, {
			Name = name,
			Text = "",
			AutoButtonColor = false,
			BackgroundColor3 = ThemeManager.color("PanelSecondary"),
			Size = UDim2.fromOffset(28, 28),
			BorderSizePixel = 0,
			ZIndex = 6,
		})

		Element.round(maid, button, "RadiusChip")
		maid:give(ThemeManager.bind(button, "BackgroundColor3", "PanelSecondary"))

		Element.icon(maid, button, glyph, {
			Role = "TextSecondary",
			Size = UDim2.fromOffset(13, 13),
			Position = UDim2.fromScale(0.5, 0.5),
			AnchorPoint = Vector2.new(0.5, 0.5),
			ZIndex = 7,
		})

		Element.interactive(button, { Maid = maid, OnClick = onClick })
		return button
	end

	function Window.new(owner: any, options: {[string]: any}?)
		options = Element.options(options, {
			Title = "Flux Hub",
			Subtitle = "",
			Icon = "layers",
			ToggleKey = Enum.KeyCode.RightControl,
			DisplayOrder = 1000,
		})

		-- A host that authors its UI larger or smaller than 900x560 says so here; the responsive
		-- layer derives everything else from that one number.
		local size = options.Size
		if type(size) == "number" then
			LayoutManager.setBase(size, size * 0.62)
		elseif type(size) == "table" and (size.X ~= nil or size.width ~= nil) then
			local width = size.X or size.width
			local height = size.Y or size.height or (width * 0.62)
			LayoutManager.setBase(math.max(320, width :: any), math.max(240, height :: any))
		end
		options.Size = nil

		LayoutManager.watch()

		local base = LayoutManager.base()
		local viewport = LayoutManager.viewport()

		local self = setmetatable({
			Owner = owner,
			Title = options.Title,
			Subtitle = options.Subtitle,
			TabOrder = {},
			Tabs = {},
			Active = nil,
			Open = true,
			Minimised = false,
			Destroyed = false,
			_offset = Vector2.new(viewport.X * 0.5, viewport.Y * 0.5),
			_fullHeight = base.Y,
		}, Window)

		local maid = Maid.new()
		self.Maid = maid
		Lifecycle.register(self)

		local gui = Element.root(maid, {
			Name = options.Name or "FluxHub",
			Order = options.DisplayOrder,
			ResetOnSpawn = options.ResetOnSpawn == true,
		})
		self.Gui = gui
		LayoutManager.apply(gui)

		self.Root = Element.panel(maid, gui, "Root", {
			Color = "WindowBackground",
			Radius = "RadiusWindow",
			Stroke = "BorderPrimary",
			Size = UDim2.fromOffset(base.X, base.Y),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromOffset(self._offset.X, self._offset.Y),
			Clips = true,
			ZIndex = 2,
		})

		self:_buildHeader(maid, options)
		self:_buildBody(maid)
		self:_buildFooter(maid)
		self:_applyResponsive(LayoutManager.isMobile())

		maid:give(LayoutManager.Changed:Connect(function()
			self:onViewportChanged()
		end))

		NotificationManager.attach(gui)

		-- `ToggleKey = false` is how a host says "I own my own hotkey"; an omitted one takes the default
		-- from the options table, so the two cases must not be collapsed into `~= nil`.
		if options.ToggleKey ~= nil and options.ToggleKey ~= false then
			self._toggle = InputManager.bind({
				Name = "window:" .. tostring(options.Title),
				Key = options.ToggleKey,
				AllowWhileTyping = true,
				Callback = function()
					self:Toggle()
				end,
			})
		end

		AnimationManager.play(self.Root, "PopIn", { Duration = 0.22 })
		return self
	end

	function Window:_buildHeader(maid: any, options: {[string]: any})
		local header = Element.panel(maid, self.Root, "Header", {
			Transparency = 1,
			Size = UDim2.new(1, 0, 0, headerHeight()),
			ZIndex = 5,
		})
		self.Header = header

		-- One hairline separates the title block from the page. The window reads as a single surface,
		-- so this is a line rather than a second panel.
		local separator = Instance.new("Frame", header, {
			Name = "Separator",
			BackgroundColor3 = ThemeManager.color("BorderPrimary"),
			BackgroundTransparency = 0.4,
			Size = UDim2.new(1, -32, 0, 1),
			Position = UDim2.new(0, 16, 1, -1),
			BorderSizePixel = 0,
			ZIndex = 5,
		})
		maid:give(ThemeManager.bind(separator, "BackgroundColor3", "BorderPrimary"))
		maid:giveFunction(function()
			separator:Destroy()
		end)

		local brand = Element.panel(maid, header, "Brand", {
			Color = "AccentSoft",
			Radius = "RadiusField",
			Size = UDim2.fromOffset(34, 34),
			Position = UDim2.new(0, 16, 0.5, 0),
			AnchorPoint = Vector2.new(0, 0.5),
			ZIndex = 6,
		})
		Element.icon(maid, brand, options.Icon or "layers", {
			Role = "Accent",
			Size = UDim2.fromOffset(16, 16),
			Position = UDim2.fromScale(0.5, 0.5),
			AnchorPoint = Vector2.new(0.5, 0.5),
			ZIndex = 7,
		})

		local titleBlock = Instance.new("Frame", header, {
			Name = "TitleBlock",
			BackgroundTransparency = 1,
			-- 34 brand + 12 gap on the left, the control cluster on the right, 16px of air between.
			Size = UDim2.new(1, -(58 + CLUSTER_WIDTH + 16), 1, 0),
			Position = UDim2.new(0, 58, 0, 0),
			BorderSizePixel = 0,
			ZIndex = 6,
		})
		maid:giveFunction(function()
			titleBlock:Destroy()
		end)
		Instance.new("UIListLayout", titleBlock, {
			FillDirection = Enum.FillDirection.Vertical,
			SortOrder = Enum.SortOrder.LayoutOrder,
		})
		self.TitleBlock = titleBlock

		self.TitleLabel = Element.label(maid, titleBlock, "Title", {
			Text = self.Title,
			Role = "TextPrimary",
			Font = "Title",
			TextSize = 17,
			Size = UDim2.new(1, 0, 0, 21),
			ZIndex = 6,
		})

		self.SubtitleLabel = Element.label(maid, titleBlock, "Subtitle", {
			Text = self.Subtitle,
			Role = "TextMuted",
			TextSize = 12,
			LayoutOrder = 1,
			Size = UDim2.new(1, 0, 0, 15),
			ZIndex = 6,
		})

		local controls = Instance.new("Frame", header, {
			Name = "Controls",
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(CLUSTER_WIDTH, 30),
			Position = UDim2.new(1, -16, 0.5, 0),
			AnchorPoint = Vector2.new(1, 0.5),
			BorderSizePixel = 0,
			ZIndex = 6,
		})
		maid:giveFunction(function()
			controls:Destroy()
		end)
		Instance.new("UIListLayout", controls, {
			FillDirection = Enum.FillDirection.Horizontal,
			HorizontalAlignment = Enum.HorizontalAlignment.Right,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 6),
			SortOrder = Enum.SortOrder.LayoutOrder,
		})

		-- The search field is part of the chrome, not of the page: it filters whatever is open. It is
		-- held as `SearchHost` because `Window:Search` is the filtering method and an instance field of
		-- that name would shadow it on the object.
		self.SearchHost = self:_buildSearch(maid, controls)

		self.MinimizeButton = iconButton(maid, controls, "Minimize", "minus", function()
			self:Minimize()
		end)
		self.CloseButton = iconButton(maid, controls, "Close", "close", function()
			self:Close()
		end)
		self.MinimizeButton.LayoutOrder = 1
		self.CloseButton.LayoutOrder = 2

		TooltipManager.attach(self.MinimizeButton, "Minimise the window")
		TooltipManager.attach(self.CloseButton, "Close the hub")

		self:_enableDrag(header)
	end

	--- The header is the grab handle. Movement is tracked on UserInputService rather than the frame
	--- so a fast drag that outruns the header keeps following the pointer instead of dropping.
	function Window:_enableDrag(handle: any)
		local dragging = false
		local last: Vector2? = nil

		local function remember(input: any): Vector2?
			local point = Guard.get(input, "Position")
			if point == nil then
				return nil
			end
			return LayoutManager.toLocal(point)
		end

		local function begin(input: any)
			if self.Minimised then
				return
			end
			dragging = true
			last = remember(input)
		end

		local function move(input: any)
			if not dragging then
				return
			end
			local now = remember(input)
			if now == nil or last == nil then
				return
			end
			self:_move(self._offset.X + (now.X - last.X), self._offset.Y + (now.Y - last.Y))
			last = now
		end

		local function finish()
			dragging = false
			last = nil
		end

		local down = Guard.get(handle, "MouseButton1Down")
		local up = Guard.get(handle, "MouseButton1Up")
		if down ~= nil and up ~= nil then
			self.Maid:giveConnection(down:Connect(begin))
			self.Maid:giveConnection(up:Connect(finish))
		end

		if UserInputService ~= nil then
			local changed = Guard.get(UserInputService, "InputChanged")
			if changed ~= nil then
				self.Maid:giveConnection(changed:Connect(function(input)
					if Guard.get(input, "EnumType") == Enum.UserInputType.MouseMovement then
						move(input)
					end
				end))
			end

			local ended = Guard.get(UserInputService, "InputEnded")
			if ended ~= nil then
				self.Maid:giveConnection(ended:Connect(function(input)
					local kind = Guard.get(input, "EnumType")
					if kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch then
						finish()
					end
				end))
			end
		end

		-- Touch has no separate movement stream on the service in the way a mouse does, so the
		-- gesture is also handled on the frame itself.
		local inputChanged = Guard.get(handle, "InputChanged")
		local inputBegan = Guard.get(handle, "InputBegan")
		local inputEnded = Guard.get(handle, "InputEnded")

		if inputBegan ~= nil and inputChanged ~= nil and inputEnded ~= nil then
			self.Maid:giveConnection(inputBegan:Connect(function(input)
				if Guard.get(input, "EnumType") == Enum.UserInputType.Touch then
					begin(input)
				end
			end))
			self.Maid:giveConnection(inputChanged:Connect(function(input)
				if Guard.get(input, "EnumType") == Enum.UserInputType.Touch then
					move(input)
				end
			end))
			self.Maid:giveConnection(inputEnded:Connect(function(input)
				if Guard.get(input, "EnumType") == Enum.UserInputType.Touch then
					finish()
				end
			end))
		end
	end

	--- Place the window's centre at (x, y) authored units, kept inside the viewport with a margin so
	--- a drag can never park the whole menu off screen.
	function Window:_move(x: number, y: number)
		local base = LayoutManager.base()
		local viewport = LayoutManager.viewport()
		local margin = 12

		local minX = margin + base.X * 0.35
		local maxX = math.max(minX, viewport.X - margin - base.X * 0.35)
		local minY = margin + headerHeight() * 0.5
		local maxY = math.max(minY, viewport.Y - margin - headerHeight() * 0.5)

		self._offset = Vector2.new(Math.clamp(x, minX, maxX), Math.clamp(y, minY, maxY))
		self.Root.Position = UDim2.fromOffset(self._offset.X, self._offset.Y)
	end

	function Window:_clampIntoView()
		self:_move(self._offset.X, self._offset.Y)
	end

	function Window:_buildBody(maid: any)
		local top = headerHeight()
		local bottom = footerHeight()
		local strip = metric("NavHeight", 52)

		local body = Element.panel(maid, self.Root, "Body", {
			Transparency = 1,
			Size = UDim2.new(1, 0, 1, -(top + bottom)),
			Position = UDim2.new(0, 0, 0, top),
			ZIndex = 3,
		})
		self.Body = body

		local bar = Element.panel(maid, body, "TabBar", {
			Transparency = 1,
			Size = UDim2.new(1, 0, 0, strip),
			ZIndex = 4,
		})
		self.Nav = bar

		-- Nine tabs will not fit a 900px strip, and a wrapped second row would put the active tab out
		-- of reach of the eye. The strip scrolls sideways instead, so it keeps one baseline.
		local scroller = Instance.new("ScrollingFrame", bar, {
			Name = "Tabs",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ScrollBarThickness = 0,
			ScrollingEnabled = true,
			ScrollingDirection = Enum.ScrollingDirection.X,
			AutomaticCanvasSize = Enum.AutomaticSize.X,
			CanvasSize = UDim2.new(),
			Size = UDim2.new(1, 0, 1, 0),
			ZIndex = 4,
		})
		maid:giveFunction(function()
			scroller:Destroy()
		end)
		self.NavScroller = scroller

		self.NavStack = Instance.new("UIListLayout", scroller, {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 2),
		})
		maid:giveFunction(function()
			self.NavStack:Destroy()
		end)

		local inset = Instance.new("UIPadding", scroller, {
			PaddingLeft = UDim.new(0, 14),
			PaddingRight = UDim.new(0, 14),
		})
		maid:giveFunction(function()
			inset:Destroy()
		end)

		-- The strip is told apart from the page by a hairline, the same device the header uses; a fill
		-- difference alone disappears on a panel that is already two steps off black.
		local edge = Instance.new("Frame", bar, {
			Name = "Edge",
			BackgroundColor3 = ThemeManager.color("BorderPrimary"),
			BackgroundTransparency = 0.4,
			Size = UDim2.new(1, -28, 0, 1),
			Position = UDim2.new(0, 14, 1, -1),
			BorderSizePixel = 0,
			ZIndex = 5,
		})
		maid:give(ThemeManager.bind(edge, "BackgroundColor3", "BorderPrimary"))
		maid:giveFunction(function()
			edge:Destroy()
		end)

		local host = Element.panel(maid, body, "ContentHost", {
			Transparency = 1,
			Size = UDim2.new(1, 0, 1, -strip),
			Position = UDim2.new(0, 0, 0, strip),
			ZIndex = 3,
		})
		self.ContentHost = host

		-- Each tab owns a page inside this host. Sharing one scrolling frame across tabs would mean
		-- re-parenting groupboxes on every click, which throws away their scroll position, re-runs
		-- their entrance animations and, on a big page, re-creates the instances the lazy build was
		-- written to avoid.
		self.Pages = {}
	end

	--- The box filters the page that is open. It lives in the header so the strip and the page each
	--- get the window's full width, and because a field at the head of the chrome is where a person
	--- looks for one; a rail-internal box is a second layout to keep in sync for no gain.
	function Window:_buildSearch(maid: any, parent: any): any
		local field = Element.panel(maid, parent, "Search", {
			Color = "Field",
			Radius = "RadiusField",
			Size = UDim2.fromOffset(SEARCH_WIDTH, SEARCH_HEIGHT),
			LayoutOrder = 0,
			ZIndex = 6,
		})

		local box = Instance.new("TextBox", field, {
			Name = "Input",
			BackgroundTransparency = 1,
			Text = "",
			ClearTextOnFocus = false,
			PlaceholderText = "Search",
			Font = ThemeManager.font("Body"),
			TextSize = 13,
			TextColor3 = ThemeManager.color("TextPrimary"),
			PlaceholderColor = ThemeManager.color("TextMuted"),
			Size = UDim2.new(1, -34, 1, 0),
			Position = UDim2.new(0, 30, 0, 0),
			BorderSizePixel = 0,
			ZIndex = 7,
		})
		maid:give(ThemeManager.bind(box, "TextColor3", "TextPrimary"))
		maid:give(ThemeManager.bind(box, "PlaceholderColor", "TextMuted"))

		Element.icon(maid, field, "search", {
			Role = "TextMuted",
			Size = UDim2.fromOffset(13, 13),
			Position = UDim2.new(0, 10, 0.5, 0),
			AnchorPoint = Vector2.new(0, 0.5),
			ZIndex = 7,
		})

		local onInput = Guard.get(box, "GetPropertyChangedSignal")
		if onInput ~= nil then
			maid:giveConnection(onInput(box, "Text"):Connect(function()
				self:Search(box.Text)
			end))
		end

		self.SearchBox = box
		return field
	end

	function Window:_buildFooter(maid: any)
		local height = footerHeight()

		local footer = Element.panel(maid, self.Root, "Footer", {
			Transparency = 1,
			Size = UDim2.new(1, 0, 0, height),
			Position = UDim2.new(0, 0, 1, -height),
			ZIndex = 4,
		})
		self.Footer = footer

		local edge = Instance.new("Frame", footer, {
			Name = "Edge",
			BackgroundColor3 = ThemeManager.color("BorderPrimary"),
			Size = UDim2.new(1, -32, 0, 1),
			Position = UDim2.new(0, 16, 0, 0),
			BorderSizePixel = 0,
			ZIndex = 4,
		})
		maid:give(ThemeManager.bind(edge, "BackgroundColor3", "BorderPrimary"))
		maid:giveFunction(function()
			edge:Destroy()
		end)

		self.StatusLabel = Element.label(maid, footer, "Status", {
			Text = "",
			Role = "TextMuted",
			TextSize = 11,
			Size = UDim2.new(1, -180, 1, 0),
			Position = UDim2.new(0, 16, 0, 0),
			ZIndex = 5,
		})

		Element.label(maid, footer, "Version", {
			Text = "Flux " .. tostring(self.Owner and self.Owner.Version or "0.0.0"),
			Role = "TextMuted",
			TextSize = 11,
			Alignment = Enum.TextXAlignment.Right,
			Size = UDim2.fromOffset(150, 0),
			Position = UDim2.new(1, -16, 0, 0),
			AnchorPoint = Vector2.new(1, 0),
			ZIndex = 5,
		})
	end

	--
	-- Building
	--

	function Window:Tab(options: any)
		if self.Destroyed then
			-- The strip this pill would join no longer exists, so building it would leak a tab nobody
			-- can ever open.
			warn("[Flux] tab added to a destroyed window")
			return nil
		end

		if type(options) == "string" then
			options = { Title = options }
		end

		-- Imported late to break the cycle: a tab creates components, and a component asks its
		-- container (which is a tab or a groupbox) for the window it belongs to.
		local Tab = require("Flux/Core/Tab")
		local tab = Tab.new(self, options)

		table.insert(self.TabOrder, tab)
		self.Tabs[tab.Title] = tab

		if self.Active == nil then
			tab:Open()
		end
		return tab
	end

	Window.CreateTab = Window.Tab
	Window.AddTab = Window.Tab

	function Window:GetTab(title: string): any
		return self.Tabs[title]
	end

	function Window:ListTabs(): {any}
		return self.TabOrder
	end

	function Window:SetTitle(title: string)
		self.Title = title
		if self.TitleLabel ~= nil then
			self.TitleLabel.Text = title
		end
	end

	function Window:SetSubtitle(text: string)
		self.Subtitle = text
		if self.SubtitleLabel ~= nil then
			self.SubtitleLabel.Text = text
		end
	end

	--- A line of state in the footer: what the hub is doing, without interrupting with a toast.
	function Window:SetStatus(text: string)
		if self.StatusLabel ~= nil then
			self.StatusLabel.Text = text
		end
	end

	function Window:Notify(options: any)
		return NotificationManager.notify(options)
	end

	--- Runs the search over every registered control and asks each tab to hide what did not match.
	--- Returns how many controls matched.
	function Window:Search(term: string): number
		local query = tostring(term or "")
		-- `set` is the entry point that moves the live term; `apply` re-runs whatever term is already
		-- stored and would filter the UI against the previous keystroke.
		local matched = SearchManager.set(query)

		for _, tab in ipairs(self.TabOrder) do
			tab:Filter(query)
		end

		if self.Active ~= nil then
			self.Active:SetEmptyNotice(query ~= "" and matched == 0)
		end

		return matched
	end

	function Window:OpenTab(titleOrTab: any): boolean
		local tab = titleOrTab
		if type(titleOrTab) == "string" then
			tab = self.Tabs[titleOrTab]
		end
		if tab == nil then
			return false
		end
		tab:Open()
		return true
	end

	function Window:_setActive(tab: any)
		self.Active = tab
		for _, other in ipairs(self.TabOrder) do
			other:SetSelected(other == tab)
		end
	end

	--
	-- Visibility
	--

	function Window:Show()
		self.Open = true
		self.Gui.Enabled = true
		AnimationManager.play(self.Root, "FadeIn", { Duration = 0.16 })
	end

	function Window:Hide()
		self.Open = false
		AnimationManager.cancel(self.Root)
		self.Gui.Enabled = false
	end

	function Window:Toggle()
		if self.Open then
			self:Hide()
		else
			self:Show()
		end
	end

	--- Minimising hides everything below the header and shrinks the window to it. The centre is
	--- nudged up by half the height that went away so the header stays exactly where it was —
	--- otherwise the bar the person is aiming for jumps under their cursor.
	function Window:Minimize()
		self.Minimised = not self.Minimised
		local base = LayoutManager.base()

		if self.Minimised then
			self._restoreHeight = base.Y
			self.Body.Visible = false
			self.Footer.Visible = false
			local collapsed = headerHeight()
			self.Root.Size = UDim2.fromOffset(base.X, collapsed)
			self:_move(self._offset.X, self._offset.Y - (base.Y - collapsed) * 0.5)
		else
			self.Body.Visible = true
			self.Footer.Visible = true
			self.Root.Size = UDim2.fromOffset(base.X, base.Y)
			self:_move(self._offset.X, self._offset.Y + (base.Y - headerHeight()) * 0.5)
		end

		if self.MinimizeButton ~= nil then
			self.MinimizeButton.LayoutOrder = 0
		end

		return self.Minimised
	end

	function Window:_applyResponsive(mobile: boolean)
		if self.Nav == nil or self.ContentHost == nil then
			return
		end

		-- A narrow window cannot show a 210px field and two chrome buttons beside a title, so the
		-- search gives up width before anything else does.
		if self.SearchHost ~= nil then
			self.SearchHost.Size = UDim2.fromOffset(mobile and 132 or SEARCH_WIDTH, SEARCH_HEIGHT)
		end

		-- Each tab owns its page, so the column collapse is the tab's business, not the window's.
		for _, tab in ipairs(self.TabOrder) do
			tab:SetSingleColumn(mobile)
		end
	end

	function Window:onViewportChanged()
		if self.Destroyed then
			return
		end

		LayoutManager.apply(self.Gui)

		local base = LayoutManager.base()
		local top = headerHeight()
		local bottom = footerHeight()

		self.Root.Size = UDim2.fromOffset(base.X, self.Minimised and top or base.Y)
		self.Header.Size = UDim2.new(1, 0, 0, top)
		local strip = metric("NavHeight", 52)
		self.Body.Size = UDim2.new(1, 0, 1, -(top + bottom))
		self.Body.Position = UDim2.new(0, 0, 0, top)
		self.Nav.Size = UDim2.new(1, 0, 0, strip)
		self.ContentHost.Size = UDim2.new(1, 0, 1, -strip)
		self.ContentHost.Position = UDim2.new(0, 0, 0, strip)
		self.Footer.Size = UDim2.new(1, 0, 0, bottom)
		self.Footer.Position = UDim2.new(0, 0, 1, -bottom)

		self:_clampIntoView()
		self:_applyResponsive(LayoutManager.isMobile())
	end

	function Window:Close()
		self:Destroy()
	end

	function Window:Destroy()
		if self.Destroyed then
			return
		end
		self.Destroyed = true

		if self._toggle ~= nil then
			self._toggle:Destroy()
			self._toggle = nil
		end

		-- The tabs share this maid, so they do not each need destroying; the flag stops a deferred
		-- row builder from mounting into a panel that no longer exists.
		for _, tab in ipairs(self.TabOrder) do
			tab.Destroyed = true
		end

		TooltipManager.hide()
		NotificationManager.detach(self.Gui)
		Lifecycle.unregister(self)
		self.Maid:cleanup()

		if self.Gui ~= nil then
			self.Gui:Destroy()
		end
	end

	--- Every connection this window made, for a test that asserts closing really does let go.
	function Window:connections(): number
		local count = 0
		for _, task in ipairs(self.Maid._tasks) do
			if type(task) == "table" and (task.type == "connection" or task.type == "thread") then
				count += 1
			end
		end
		return count
	end

	return Window
end

-- src/Systems/AnimationManager.lua
FluxRegistry["Flux/Systems/AnimationManager"] = function(require)
	--[[
		Systems/AnimationManager — hand-interpolated motion on one shared RenderStepped loop.

		Why not TweenService: several of the clients this library runs on either lack it or
		leave a created tween that never completes, and a stalled tween is worse than no
		motion — the element stays half-faded forever. Interpolating here means the resting
		state is always correct, motion is layered on top, and a missing engine feature can
		never decide whether something is visible.

		Two rules the rest of the library depends on:
		  * the loop exists only while something is animating, so an idle menu costs nothing;
		  * a new tween for the same (instance, property) replaces the running one, so hover
		    spam cannot stack into a fight between two interpolations.
	]]

	local Guard = require("Flux/Utilities/Guard")
	local Math = require("Flux/Utilities/Math")

	local RunService = Guard.service("RunService")

	local AnimationManager = {}

	local active = {}
	local running = false
	local connection: RBXScriptConnection? = nil
	local speed = 1
	local reducedMotion = false

	AnimationManager.easing = {
		linear = function(t: number): number
			return t
		end,
		outQuad = function(t)
			return 1 - (1 - t) * (1 - t)
		end,
		outQuint = function(t)
			return 1 - (1 - t) ^ 5
		end,
		outExpo = function(t)
			if t >= 1 then
				return 1
			end
			return 1 - 2 ^ (-10 * t)
		end,
		inOutQuad = function(t)
			if t < 0.5 then
				return 2 * t * t
			end
			return 1 - (-2 * t + 2) ^ 2 / 2
		end,
		outBack = function(t)
			local c1 = 1.70158
			local c3 = c1 + 1
			return 1 + c3 * (t - 1) ^ 3 + c1 * (t - 1) ^ 2
		end,
		outElastic = function(t)
			if t == 0 or t == 1 then
				return t
			end
			local c4 = (2 * math.pi) / 3
			return 2 ^ (-10 * t) * math.sin((t * 10 - 0.75) * c4) + 1
		end,
	}

	--- Motion presets. Duration is in seconds; `style` names an easing above.
	---
	--- Fade targets both transparency properties a GuiObject can carry. `Transparency` is a part
	--- member and does not exist on a Frame, so writing it would silently create an expando that
	--- renders as nothing — which is exactly the kind of motion that "works" on screen and does not.
	AnimationManager.presets = {
		FadeIn = { duration = 0.16, easing = "outQuad", goals = { BackgroundTransparency = 0, ImageTransparency = 0 } },
		FadeOut = { duration = 0.12, easing = "outQuad", goals = { BackgroundTransparency = 1, ImageTransparency = 1 } },
		SlideIn = { duration = 0.2, easing = "outQuint" },
		PopIn = { duration = 0.22, easing = "outBack", scaleFrom = 0.92 },
		PopOut = { duration = 0.14, easing = "outQuad", scaleTo = 0.94 },
		Hover = { duration = 0.12, easing = "outQuad" },
		Press = { duration = 0.08, easing = "outQuad", scaleTo = 0.975 },
		Release = { duration = 0.14, easing = "outBack" },
		Collapse = { duration = 0.18, easing = "inOutQuad" },
		Expand = { duration = 0.2, easing = "outQuint" },
	}

	local function kindsFor(property: string): string
		if property == "Size" or property == "Position" then
			return "udim2"
		elseif property == "AnchorPoint" then
			return "vector2"
		elseif property == "BackgroundColor3"
			or property == "TextColor3"
			or property == "ImageColor3"
			or property == "BorderColor3"
			or property == "StrokeColor" then
			return "color"
		end
		return "number"
	end

	local function interpolate(kind: string, from: any, to: any, alpha: number): any
		if kind == "color" then
			return from:Lerp(to, alpha)
		elseif kind == "udim2" then
			return UDim2.new(
				Math.lerp(from.X.Scale, to.X.Scale, alpha),
				Math.lerp(from.X.Offset, to.X.Offset, alpha),
				Math.lerp(from.Y.Scale, to.Y.Scale, alpha),
				Math.lerp(from.Y.Offset, to.Y.Offset, alpha)
			)
		elseif kind == "vector2" then
			return Vector2.new(Math.lerp(from.X, to.X, alpha), Math.lerp(from.Y, to.Y, alpha))
		end
		return Math.lerp(from, to, alpha)
	end

	local function stopLoop()
		if connection ~= nil then
			connection:Disconnect()
			connection = nil
		end
		running = false
	end

	local function step(delta: number)
		local multiplier = speed
		if reducedMotion then
			multiplier = 8
		end

		local index = 1
		while index <= #active do
			local entry = active[index]
			entry.elapsed += delta * multiplier

			local progress = Math.clamp(entry.elapsed / entry.duration, 0, 1)
			local alpha = entry.easing(progress)

			-- The last frame writes the goal itself rather than the maths: `from + (to - from) * 1` is
			-- not `to` in floating point (0.2 lands as 0.19999999999999996), and a resting value a hair
			-- off the caller's request is exactly the half-faded element this module exists to avoid.
			-- The branch is on progress, not alpha, so an overshooting curve still peaks mid-flight.
			local value = entry.to
			if progress < 1 then
				value = interpolate(entry.kind, entry.from, entry.to, alpha)
			end

			if not Guard.set(entry.instance, entry.property, value) then
				-- The property does not exist on this client; drop the entry rather than
				-- re-attempting it every frame for the rest of the animation.
				table.remove(active, index)
				if entry.onEnd ~= nil then
					entry.onEnd(false)
				end
				continue
			end

			if progress >= 1 then
				table.remove(active, index)
				if entry.onEnd ~= nil then
					entry.onEnd(true)
				end
			else
				index += 1
			end
		end

		if #active == 0 then
			stopLoop()
		end
	end

	local function ensureLoop()
		if running or RunService == nil then
			return
		end

		running = true
		connection = RunService.RenderStepped:Connect(step)
	end

	--- Animate one or more properties. `goals` maps a property to its target value.
	--- Returns how many properties are actually running, and how many in-flight tweens were
	--- replaced. A caller that must know whether motion happened (a preset, an entrance) uses the
	--- first value; nothing should treat a zero there as success.
	function AnimationManager.to(instance: any, goals: {[string]: any}, options: {
		Duration: number?,
		Easing: string?,
		OnEnd: ((boolean) -> ())?,
		Restart: boolean?,
	}): (number, number)
		options = options or {}
		local skipped = {}

		local function reportSkipped(ranAnything: boolean)
			-- A property this client cannot animate still owes the caller its completion callback:
			-- callers gate follow-up state on OnEnd, and staying silent would hang them forever.
			-- When at least one property did queue, that tween's own completion is the report.
			if ranAnything or #skipped == 0 or options.OnEnd == nil then
				return
			end
			task.defer(options.OnEnd, false)
		end

		local duration = options.Duration or 0.16
		local easing = AnimationManager.easing[options.Easing or "outQuint"] or AnimationManager.easing.outQuint

		if duration <= 0 or reducedMotion then
			for property, value in pairs(goals) do
				if not Guard.set(instance, property, value) then
					table.insert(skipped, property)
				end
			end
			if options.OnEnd ~= nil then
				task.defer(options.OnEnd, #skipped == 0)
			end
			return 0, 0
		end

		local queued = 0
		local replaced = 0

		for property, target in pairs(goals) do
			local kind = kindsFor(property)

			if kind == "number" and type(target) ~= "number" then
				table.insert(skipped, property)
				continue
			end

			-- Replace any running interpolation of the same property on the same object. The outgoing
			-- entry is told it was superseded: callers that chain state onto OnEnd must not be left
			-- waiting for a tween that no longer exists.
			for index = #active, 1, -1 do
				local entry = active[index]
				if entry.instance == instance and entry.property == property then
					table.remove(active, index)
					replaced += 1
					if entry.onEnd ~= nil then
						task.defer(entry.onEnd, false)
					end
				end
			end

			-- Reading first is what proves the client has the member: writing an unknown property to
			-- an Instance does not raise, it silently creates an expando that renders as nothing.
			local from = Guard.get(instance, property)
			if from == nil then
				table.insert(skipped, property)
				continue
			end

			table.insert(active, {
				instance = instance,
				property = property,
				kind = kind,
				from = from,
				to = target,
				elapsed = 0,
				duration = duration,
				easing = easing,
				onEnd = options.OnEnd,
			})
			queued += 1
		end

		ensureLoop()
		reportSkipped(queued > 0)
		return queued, replaced
	end

	--- Play a named preset against a known geometry. Returns whether it played.
	function AnimationManager.play(instance: any, presetName: string, options: {[string]: any}?): boolean
		local preset = AnimationManager.presets[presetName]
		if preset == nil then
			warn("[Flux] animation: unknown preset " .. tostring(presetName))
			return false
		end

		options = options or {}
		local duration = options.Duration or preset.duration
		local easing = preset.easing

		-- Every branch reports what `to` actually queued. A preset that found no animatable property
		-- on this client has not played, and saying otherwise is how a menu ends up with transitions
		-- that are configured, reported as working, and never happen.
		if preset.goals ~= nil then
			local queued = AnimationManager.to(instance, preset.goals, {
				Duration = duration,
				Easing = easing,
				OnEnd = options.OnEnd,
			})
			return queued > 0
		end

		-- Hover, Collapse and Expand describe timing, not a destination: the caller owns what the
		-- element animates toward. Without Goals there is nothing to run.
		if options.Goals ~= nil then
			local queued = AnimationManager.to(instance, options.Goals, {
				Duration = duration,
				Easing = easing,
				OnEnd = options.OnEnd,
			})
			return queued > 0
		end

		if presetName == "SlideIn" then
			local target = options.TargetPosition
			if target == nil then
				warn("[Flux] animation: SlideIn needs options.TargetPosition")
				return false
			end

			local offset = options.Offset or 10
			instance.Position = UDim2.new(target.X.Scale, target.X.Offset, target.Y.Scale, target.Y.Offset + offset)

			local moved = AnimationManager.to(instance, { Position = target }, {
				Duration = duration,
				Easing = easing,
				OnEnd = options.OnEnd,
			})
			AnimationManager.to(instance, { BackgroundTransparency = 0 }, { Duration = duration, Easing = easing })
			return moved > 0
		end

		if preset.scaleFrom ~= nil or preset.scaleTo ~= nil then
			local size = instance.Size
			if size.X.Scale == 0 and size.Y.Scale == 0 then
				-- A pure-offset size has no scale term to interpolate; fall back to a fade so the
				-- element still arrives with motion instead of snapping.
				local faded = AnimationManager.to(instance, { BackgroundTransparency = 0 }, {
					Duration = duration,
					Easing = easing,
					OnEnd = options.OnEnd,
				})
				return faded > 0
			end

			local factor = preset.scaleFrom or preset.scaleTo or 1
			local goal

			if preset.scaleFrom ~= nil then
				instance.Size = UDim2.new(size.X.Scale * factor, size.X.Offset * factor, size.Y.Scale, size.Y.Offset)
				goal = UDim2.new(size.X.Scale, size.X.Offset, size.Y.Scale, size.Y.Offset)
			else
				goal = UDim2.new(size.X.Scale * factor, size.X.Offset * factor, size.Y.Scale, size.Y.Offset)
			end

			local grew = AnimationManager.to(instance, { Size = goal }, {
				Duration = duration,
				Easing = easing,
				OnEnd = options.OnEnd,
			})
			return grew > 0
		end

		warn("[Flux] animation: preset " .. presetName .. " has no goals; pass options.Goals")
		return false
	end

	--- Stop every interpolation owned by an instance (a destroyed row must not keep ticking).
	function AnimationManager.cancel(instance: any)
		for index = #active, 1, -1 do
			if active[index].instance == instance then
				table.remove(active, index)
			end
		end

		if #active == 0 then
			stopLoop()
		end
	end

	function AnimationManager.activeCount(): number
		return #active
	end

	function AnimationManager.setSpeed(multiplier: number)
		speed = math.max(0.05, multiplier)
	end

	function AnimationManager.getSpeed(): number
		return speed
	end

	--- Global switch: with motion reduced every tween lands on its resting value immediately.
	function AnimationManager.setReducedMotion(enabled: boolean)
		reducedMotion = enabled == true
	end

	function AnimationManager.isReducedMotion(): boolean
		return reducedMotion
	end

	function AnimationManager.stopAll()
		table.clear(active)
		stopLoop()
	end

	return AnimationManager
end

-- src/Systems/ConfigManager.lua
FluxRegistry["Flux/Systems/ConfigManager"] = function(require)
	--[[
		Systems/ConfigManager — save, restore, and the ordering problem in between.

		The hard part is not JSON, it is that this library builds rows lazily while a config is loaded
		once at startup. A value read before its row exists would be dropped, and a row built after a
		load would show the default. So the store and the bindings are separate: values live in `data`
		first, bindings only observe them, and a row that registers late is handed the stored value
		immediately.

		The file api is optional. A client without writefile keeps everything in memory for the session
		and reports why through `Config.reason()` — the UI says "saving is unavailable here" instead of
		failing on a save button.
	]]

	local Signal = require("Flux/Utilities/Signal")
	local Guard = require("Flux/Utilities/Guard")
	local Table = require("Flux/Utilities/Table")
	local ThemeManager = require("Flux/Systems/ThemeManager")

	local HttpService = Guard.service("HttpService")

	local ConfigManager = {}

	--- Fired (key, value) after a load or a reset changes something a bound row is showing.
	ConfigManager.Changed = Signal.new()
	--- Fired (path, ok, reason) whenever a write is attempted.
	ConfigManager.Saved = Signal.new()

	local settings = {
		Name = "default",
		Folder = "FluxHub/Configs",
		Version = 1,
		Debounce = 0.5,
		AutoSave = true,
		SaveTheme = true,
	}

	--- Values by key. Lives here rather than in the widgets so a value exists before its row does.
	local data: {[string]: any} = {}
	local bindings: {[string]: {any}} = {}

	local loaded = false
	local dirty = false
	local saveThread: thread? = nil
	local lastReason: string? = nil
	local lastError: string? = nil

	--- Whether this client can actually be asked for a file. Some executors define the names and then
	--- raise on every call, so a type check alone would promise a disk that is not there; the probe is
	--- the same question `save` would ask.
	local function hasFileApi(): boolean
		if type(isfile) ~= "function" or type(writefile) ~= "function" or type(readfile) ~= "function" then
			return false
		end
		return pcall(isfile, ConfigManager.path(".probe")) == true
	end

	function ConfigManager.available(): boolean
		return hasFileApi()
	end

	function ConfigManager.configure(options: { Name: string?, Folder: string?, Debounce: number?, AutoSave: boolean?, SaveTheme: boolean? })
		options = options or {}
		if type(options.Name) == "string" and options.Name:match("%S") ~= nil then
			-- A name of only spaces would produce a path the file api cannot be trusted with.
			settings.Name = options.Name
		end
		if type(options.Folder) == "string" then
			settings.Folder = options.Folder
		end
		if type(options.Debounce) == "number" then
			settings.Debounce = math.max(0, options.Debounce)
		end
		if options.AutoSave ~= nil then
			settings.AutoSave = options.AutoSave == true
		end
		if options.SaveTheme ~= nil then
			settings.SaveTheme = options.SaveTheme == true
		end
		return settings
	end

	function ConfigManager.name(): string
		return settings.Name
	end

	function ConfigManager.path(name: string?): string
		return settings.Folder .. "/" .. (name or settings.Name) .. ".json"
	end

	--- Why the last save or load did not happen. nil means nothing went wrong.
	function ConfigManager.reason(): string?
		return lastReason
	end

	function ConfigManager.error(): string?
		return lastError
	end

	--- A value must be JSON-representable or a config written today will not read back tomorrow.
	local function encodable(value: any): boolean
		local kind = type(value)
		return kind == "nil" or kind == "boolean" or kind == "number" or kind == "string" or kind == "table"
	end

	--- Stage a value. Rows call this on every interaction; the disk sees one write per burst.
	function ConfigManager.set(key: string, value: any, options: { Immediate: boolean? }): boolean
		if type(key) ~= "string" or key == "" then
			warn("[Flux] config: a key must be a non-empty string")
			return false
		end
		if not encodable(value) then
			warn(("[Flux] config: '%s' holds a %s, which cannot be stored"):format(tostring(key), type(value)))
			return false
		end

		data[key] = value

		dirty = true
		if settings.AutoSave then
			ConfigManager.scheduleSave(options)
		end
		return true
	end

	function ConfigManager.get(key: string, fallback: any): any
		local value = data[key]
		if value == nil then
			return fallback
		end
		return value
	end

	function ConfigManager.has(key: string): boolean
		return data[key] ~= nil
	end

	function ConfigManager.keys(): {string}
		local out = {}
		for key in pairs(data) do
			table.insert(out, key)
		end
		table.sort(out)
		return out
	end

	function ConfigManager.data(): {[string]: any}
		return Table.deepCopy(data)
	end

	--- Re-arm the debounce timer. A slider dragged across two hundred values produces one write.
	function ConfigManager.scheduleSave(options: { Immediate: boolean? })
		if options ~= nil and options.Immediate then
			ConfigManager.save()
			return
		end

		if not hasFileApi() then
			-- A timer that would only fail to write is worse than no timer: the store stays dirty and
			-- an explicit save carries the reason.
			return
		end

		if saveThread ~= nil then
			task.cancel(saveThread)
		end

		if settings.Debounce <= 0 then
			saveThread = task.defer(function()
				saveThread = nil
				ConfigManager.save()
			end)
			return
		end

		saveThread = task.delay(settings.Debounce, function()
			saveThread = nil
			ConfigManager.save()
		end)
	end

	function ConfigManager.pendingSave(): boolean
		return saveThread ~= nil
	end

	local function encode(payload: {[string]: any}): string?
		if HttpService == nil then
			return nil
		end
		local ok, json = pcall(function()
			return HttpService:JSONEncode(payload)
		end)
		if ok and type(json) == "string" then
			return json
		end
		lastError = "the client could not encode JSON"
		return nil
	end

	local function decode(json: string): {[string]: any}?
		if HttpService == nil then
			return nil
		end
		local ok, payload = pcall(function()
			return HttpService:JSONDecode(json)
		end)
		if ok and type(payload) == "table" then
			return payload
		end
		lastError = "the file is not valid JSON"
		return nil
	end

	--- Write the staged values. Returns whether a file changed.
	function ConfigManager.save(name: string?): (boolean, string?)
		if not hasFileApi() then
			lastReason = "this client has no file api, so the config lives in memory for the session"
			ConfigManager.Saved:Dispatch(ConfigManager.path(name), false, lastReason)
			return false, lastReason
		end

		if name ~= nil then
			settings.Name = name
		end

		if settings.SaveTheme then
			data["__theme"] = ThemeManager.snapshot()
		end

		local payload = {
			__flux = true,
			__version = settings.Version,
			__saved = os.time(),
			values = data,
		}

		local json = encode(payload)
		if json == nil then
			lastReason = "the client could not encode the config"
			return false, lastReason
		end

		local path = ConfigManager.path()
		local ok, err = pcall(function()
			if not isfile(settings.Folder) and not isfolder(settings.Folder) then
				makefolder(settings.Folder)
			end
			writefile(path, json)
		end)

		if not ok then
			lastReason = "the write was refused"
			lastError = tostring(err)
			ConfigManager.Saved:Dispatch(path, false, lastReason)
			return false, lastReason
		end

		dirty = false
		lastReason = nil
		ConfigManager.Saved:Dispatch(path, true, nil)
		return true, path
	end

	--- Read a file into the store and push every value its rows care about.
	--- Returns (ok, reason).
	function ConfigManager.load(name: string?): (boolean, string?)
		if name ~= nil and type(name) == "string" and name:match("%S") ~= nil then
			settings.Name = name
		end

		if not hasFileApi() then
			lastReason = "this client has no file api"
			return false, lastReason
		end

		local path = ConfigManager.path()
		local ok, contents = pcall(function()
			if not isfile(path) then
				return nil
			end
			return readfile(path)
		end)

		if not ok then
			lastReason = "the read was refused"
			lastError = tostring(contents)
			return false, lastReason
		end

		if contents == nil or contents == "" then
			lastReason = "no config saved under that name yet"
			return false, lastReason
		end

		local payload = decode(tostring(contents))
		if payload == nil then
			lastReason = "the config could not be parsed"
			return false, lastReason
		end

		if payload.__flux ~= true then
			lastReason = "the file is not a Flux config"
			return false, lastReason
		end

		if payload.__version ~= nil and payload.__version ~= settings.Version then
			-- Reported, not fatal: a config from an older build should still restore what it can.
			lastReason = "saved by version " .. tostring(payload.__version)
		end

		local values = type(payload.values) == "table" and payload.values or {}
		table.clear(data)
		for key, value in pairs(values) do
			data[key] = value
		end

		if type(data.__theme) == "table" then
			ThemeManager.restore(data.__theme)
		end

		loaded = true
		dirty = false
		ConfigManager.push()
		return true, path
	end

	--- Push every stored value into the rows bound to it. Called after a load and after a bind, so a
	--- row built after the file was read still shows the saved state.
	function ConfigManager.push(key: string?): number
		local applied = 0
		local targets = key ~= nil and { [key] = bindings[key] } or bindings

		for boundKey, list in pairs(targets) do
			local value = data[boundKey]
			if list ~= nil then
				for _, binding in ipairs(list) do
					if value ~= nil then
						local ok, err = pcall(binding.apply, value)
						if ok then
							applied += 1
						else
							warn(("[Flux] config: '%s' could not apply to a row: %s"):format(boundKey, tostring(err)))
						end
					end
				end
			end
		end

		return applied
	end

	--- Bind a row to a key. Returns an unbind, and applies the stored value now if there is one.
	---   Apply — set the widget from the restored value.
	---   Read  — report the widget's current value for saving.
	function ConfigManager.bind(key: string, handlers: { Apply: (any) -> (), Read: (() -> any)? }): () -> ()
		local binding = { key = key, apply = handlers.Apply, read = handlers.Read }
		local list = bindings[key]
		if list == nil then
			list = {}
			bindings[key] = list
		end
		table.insert(list, binding)

		if data[key] ~= nil then
			local ok, err = pcall(handlers.Apply, data[key])
			if not ok then
				warn(("[Flux] config: bind '%s' threw: %s"):format(key, tostring(err)))
			end
		end

		local unbound = false
		return function()
			if unbound then
				return
			end
			unbound = true
			for index = #list, 1, -1 do
				if list[index] == binding then
					table.remove(list, index)
				end
			end
		end
	end

	--- Pull every row's live value into the store. Called before an explicit save so a save button
	--- writes what the user sees, not what they saw when the page was built.
	function ConfigManager.collect(): number
		local collected = 0
		for key, list in pairs(bindings) do
			local binding = list[#list]
			if binding ~= nil and binding.read ~= nil then
				local ok, value = pcall(binding.read)
				if ok then
					data[key] = value
					collected += 1
				end
			end
		end
		return collected
	end

	--- Forget everything: the store, the file, and what the rows are showing.
	function ConfigManager.reset(options: { DeleteFile: boolean?, Defaults: {[string]: any}? })
		options = options or {}
		table.clear(data)

		if type(options.Defaults) == "table" then
			for key, value in pairs(options.Defaults) do
				data[key] = value
			end
		end

		if options.DeleteFile and hasFileApi() then
			pcall(function()
				local path = ConfigManager.path()
				if isfile(path) then
					delfile(path)
				end
			end)
		end

		dirty = false
		ConfigManager.push()
		return true
	end

	function ConfigManager.loaded(): boolean
		return loaded
	end

	function ConfigManager.dirty(): boolean
		return dirty
	end

	--- Names of the configs saved on this machine, for a "load profile" dropdown.
	function ConfigManager.names(): {string}
		local out = {}
		if not hasFileApi() or type(listfiles) ~= "function" then
			return out
		end

		-- Executors disagree about the shape of listfiles: some return an array of paths, some take a
		-- callback and return nothing, and generalized iteration is newer Luau than several of these
		-- clients run. Both callable shapes are tried; neither is required.
		local function collect(entry: any)
			local name = tostring(entry)
			if name:sub(-5) == ".json" then
				table.insert(out, name:match("([^/\\]+)%.json$") or name)
			end
		end

		local ok, result = pcall(listfiles, settings.Folder)
		if ok and type(result) == "table" then
			for _, entry in ipairs(result) do
				collect(entry)
			end
		else
			local called = pcall(function()
				listfiles(settings.Folder, collect)
			end)
			if not called then
				lastError = "listfiles is not usable on this client"
			end
		end

		table.sort(out)
		return out
	end

	function ConfigManager.exists(name: string?): boolean
		if not hasFileApi() then
			return false
		end
		local ok, found = pcall(isfile, ConfigManager.path(name))
		return ok and found == true
	end

	--- The JSON the config file would hold right now, for a clipboard export on a client without one.
	function ConfigManager.export(): string?
		local payload = {
			__flux = true,
			__version = settings.Version,
			values = data,
		}
		return encode(payload)
	end

	--- Restore from a JSON string the user pasted, which is how a config moves between machines.
	function ConfigManager.import(json: string): (boolean, string?)
		if type(json) ~= "string" or json == "" then
			return false, "nothing to import"
		end
		local payload = decode(json)
		if payload == nil or payload.__flux ~= true then
			return false, "not a Flux config"
		end

		table.clear(data)
		for key, value in pairs(type(payload.values) == "table" and payload.values or {}) do
			data[key] = value
		end
		if type(data.__theme) == "table" then
			ThemeManager.restore(data.__theme)
		end
		ConfigManager.push()
		return true, "imported"
	end

	return ConfigManager
end

-- src/Systems/IconManager.lua
FluxRegistry["Flux/Systems/IconManager"] = function(require)
	--[[
		Systems/IconManager — name -> paintable glyph, with the fallback chain made explicit.

		Routes, tried in this order:
		  1. an asset id the host registered with Icons.configure{ Assets = … } (the path for a
		     client that uploaded assets/icons/*.png to Roblox);
		  2. the embedded atlas: base64 -> writefile -> getcustomasset. This is the route that
		     works in a client with a file API and no network, and it is decoded per glyph on
		     first use, so a menu that shows nine icons never decodes forty-nine;
		  3. Assets/GlyphFallback primitives;
		  4. nothing (the icon slot collapses and the label shifts left).

		`rbxthumb://` is deliberately absent: it only resolves in Studio, so a library consumed
		from a client would paint blank squares.
	]]

	local Instance = require("Flux/Utilities/Instance")
	local Base64 = require("Flux/Utilities/Base64")
	local IconAtlas = require("Flux/Assets/IconAtlas")
	local GlyphFallback = require("Flux/Assets/GlyphFallback")

	local Icons = {}

	local resolved: {[string]: string} = {}
	local routes: {[string]: string} = {}
	local uploaded: {[string]: string} = {}
	local aliases: {[string]: string} = {}
	local failures: {[string]: string} = {}

	local folder = "FluxHub/Icons"

	-- Set by Icons.configure{ Mode = "fallback" } to keep a client off the file api even when it
	-- has one. It is a switch, not a report; what is actually happening is `Icons.route`.
	local forced: string? = nil

	--- The glyph mode() reports on. One stable name answers "is this client painting real PNGs or
	--- primitive dots?" without having to aggregate every glyph that happens to be on screen.
	local MODE_PROBE = "search"

	-- Atlas keys are camelCase. Callers type "gear", "Gear" or "chevrondown" in a config, so a
	-- lowercased index is built once at load rather than every lookup scanning forty-nine names.
	local byLower: {[string]: string} = {}
	for glyph in pairs(IconAtlas.glyphs) do
		byLower[tostring(glyph):lower()] = glyph
	end

	--- Map whatever the caller wrote to a key the registry actually holds, or nil.
	--- Aliases resolve first, because an alias may point at a glyph this name is not.
	--- Declared before every user below: a `local function` is invisible to code above it.
	local function canonical(name: string?): string?
		if name == nil or name == "" then
			return nil
		end

		local aliased = aliases[name]
		if aliased ~= nil then
			name = aliased
		end

		if IconAtlas.glyphs[name] ~= nil or uploaded[name] ~= nil then
			return name
		end

		-- A raw id passes straight through, so Icons.attach(parent, "rbxassetid://123") works.
		if name:find("^rbxassetid://") or name:find("^rbxasset://") or name:find("^http") then
			return name
		end

		return byLower[name:lower()]
	end

	function Icons.names(): {string}
		local out = {}
		for name in pairs(IconAtlas.glyphs) do
			table.insert(out, name)
		end
		table.sort(out)
		return out
	end

	function Icons.has(name: string): boolean
		if name == nil then
			return false
		end
		return canonical(name) ~= nil
	end

	function Icons.alias(pairs_: {[string]: string})
		for from, to in pairs(pairs_) do
			aliases[from] = to
		end
	end

	--- Register real uploaded asset ids, or change the cache folder / force a route.
	function Icons.configure(options: { Folder: string?, Assets: {[string]: string}?, Mode: string? })
		options = options or {}

		if type(options.Folder) == "string" then
			folder = options.Folder
		end

		if type(options.Assets) == "table" then
			for name, asset in pairs(options.Assets) do
				local key = tostring(name)
				uploaded[key] = tostring(asset)
				resolved[key] = uploaded[key]
				routes[key] = "uploaded"
				byLower[key:lower()] = key
			end
		end

		if options.Mode ~= nil then
			if options.Mode == "fallback" then
				forced = "fallback"
			else
				forced = nil
			end
		end
	end

	--- Decode and one-time cache a glyph. Returns the content string, or nil plus the reason.
	local function materialise(name: string): (string?, string?)
		local encoded = IconAtlas.glyphs[name]
		if encoded == nil then
			return nil, "no such glyph"
		end

		local bytes = Base64.decode(encoded)
		if bytes == nil or #bytes == 0 then
			return nil, "atlas decode failed"
		end

		local path = folder .. "/" .. name .. ".png"

		local ok, content = pcall(function()
			if not isfile(path) then
				makefolder(folder)
				writefile(path, bytes)
			end
			return getcustomasset(path)
		end)

		if not ok then
			return nil, "client has no file api"
		end

		if type(content) ~= "string" or content == "" then
			return nil, "getcustomasset returned nothing"
		end

		return content, nil
	end

	--- Resolve a name to something an ImageLabel can display, or nil to mean "use primitives".
	function Icons.content(name: string): string?
		local key = canonical(name)
		if key == nil then
			return nil
		end

		local cached = resolved[key]
		if cached ~= nil then
			return cached
		end

		-- An id that was cached as unresolvable must not be re-decoded on every frame the widget
		-- is visible, so failures are remembered in `routes`/`failures` rather than retried.
		if routes[key] == "fallback" then
			return nil
		end

		local direct = uploaded[key]
		if direct ~= nil then
			resolved[key] = direct
			routes[key] = "uploaded"
			return direct
		end

		if IconAtlas.glyphs[key] == nil then
			-- A raw id is its own content, so attach(parent, "rbxassetid://123") paints the caller's
			-- image instead of falling through to the primitive dot.
			if key:find("^rbxassetid://") or key:find("^rbxasset://") or key:find("^http") then
				resolved[key] = key
				routes[key] = "uploaded"
				return key
			end
			return nil
		end

		if forced == "fallback" then
			routes[key] = "fallback"
			failures[key] = "the file api was turned off by configuration"
			return nil
		end

		local content, reason = materialise(key)
		if content ~= nil then
			resolved[key] = content
			routes[key] = "file"
			return content
		end

		failures[key] = reason
		routes[key] = "fallback"
		return nil
	end

	--- Which route served this glyph: "uploaded", "file", "fallback", or nil for a name the
	--- registry does not hold. Resolving is lazy, so asking costs one decode the first time.
	function Icons.route(name: string): string?
		local key = canonical(name)
		if key == nil then
			return nil
		end

		if routes[key] == nil then
			Icons.content(name)
		end

		return routes[key]
	end

	--- Which route is serving the menu overall. Reported so a reduced icon set is visible in
	--- diagnostics instead of being mistaken for a broken atlas.
	function Icons.mode(): string
		return Icons.route(MODE_PROBE) or "probe"
	end

	function Icons.failureReason(name: string): string?
		local key = canonical(name)
		if key == nil then
			return nil
		end
		return failures[key]
	end

	local handle = {}
	handle.__index = handle

	function handle.setColor(self: any, color: Color3)
		if self.kind == "image" then
			self.instance.ImageColor3 = color
		else
			-- Primitive children carry the colour directly; there is no tint to apply.
			for _, child in ipairs(self.instance:GetChildren()) do
				if child:IsA("Frame") then
					child.BackgroundColor3 = color
				end
			end
		end
	end

	--- Multiplies the size the icon was created at. Scaling against the parent instead would make
	--- a 16 px glyph in a 30 px row jump to 15 px the first time anything called this.
	function handle.setScale(self: any, factor: number)
		local base = self.baseSize
		self.instance.Size = UDim2.new(
			base.X.Scale * factor,
			base.X.Offset * factor,
			base.Y.Scale * factor,
			base.Y.Offset * factor
		)
	end

	--- Attach a glyph. Returns a handle with `instance`, `kind`, `setColor`, `setScale`.
	function Icons.attach(parent: any, name: string, options: {
		Size: UDim2?,
		Position: UDim2?,
		AnchorPoint: Vector2?,
		Color: Color3?,
		LayoutOrder: number?,
		Name: string?,
		Transparency: number?,
	}): any
		options = options or {}
		local color = options.Color or Color3.fromRGB(231, 231, 237)

		local key = canonical(name)
		local content = Icons.content(name)

		if content ~= nil then
			local image = Instance.new("ImageLabel", parent, {
				Name = options.Name or ("Icon_" .. tostring(name)),
				Image = content,
				BackgroundTransparency = 1,
				ImageColor3 = color,
				ImageTransparency = options.Transparency or 0,
				Size = options.Size or UDim2.fromOffset(16, 16),
				Position = options.Position or UDim2.new(),
				AnchorPoint = options.AnchorPoint or Vector2.new(0, 0),
				LayoutOrder = options.LayoutOrder or 0,
			})

			return setmetatable({
				instance = image,
				kind = "image",
				name = name,
				baseSize = image.Size,
			}, handle)
		end

		local container = GlyphFallback.draw(parent, key or "dot", color)
		container.Name = options.Name or ("Icon_" .. tostring(name))
		if options.Size ~= nil then
			container.Size = options.Size
		end
		if options.Position ~= nil then
			container.Position = options.Position
		end
		if options.AnchorPoint ~= nil then
			container.AnchorPoint = options.AnchorPoint
		end
		container.LayoutOrder = options.LayoutOrder or 0

		return setmetatable({
			instance = container,
			kind = "fallback",
			name = name,
			baseSize = container.Size,
		}, handle)
	end

	return Icons
end

-- src/Systems/InputManager.lua
FluxRegistry["Flux/Systems/InputManager"] = function(require)
	--[[
		Systems/InputManager — the keybind layer: registration, chords, capture, release.
	
		Three things this has to get right that a naive version does not:
	
		  * A HOLD binding is pulled, not pushed. The engine's InputEnded is unreliable for a key
		    released while the game window does not have focus, so a hold-style feature (boost while
		    held) reads `binding:GetState()` on its own frame loop and cannot get stuck on. The
		    down/up callbacks are still dispatched for callers that want them.
		  * A chord must match the modifier set exactly. A bind on Ctrl+G that also fires on a bare G
		    is worse than no bind, and the reverse (a bare bind that fires while a modifier is down) is
		    how "I pressed it and nothing happened" bug reports start.
		  * Releasing everything on unload has to be idempotent, because the cleanup path runs from a
		    Maid, from the keybind picker's cancel, and from the window's destroy.
	]]
	
	local Signal = require("Flux/Utilities/Signal")
	local Guard = require("Flux/Utilities/Guard")
	local String = require("Flux/Utilities/String")
	local Table = require("Flux/Utilities/Table")
	
	local UserInputService = Guard.service("UserInputService")
	
	local InputManager = {}
	
	--- Keys the capture session refuses to bind, because the UI needs them to stay reachable.
	InputManager.forbidden = {
		Escape = true,
		Home = true,
	}
	
	local bindings = {}
	local captureSessions = {}
	local held = {}
	local connections = {}
	
	InputManager.Changed = Signal.new()
	
	local function inputName(input: any): string?
		if input == nil then
			return nil
		end
	
		-- A UserInput object has no Name: the member that identifies the press is its KeyCode (a key)
		-- or its UserInputType (a mouse button, touch). Names are compared rather than the objects
		-- because a restored config carries the same trigger as a string.
		local code = Guard.get(input, "KeyCode")
		-- Unknown is what the engine puts on a press that has no key, so it is not a name.
		if code ~= nil and code ~= Enum.KeyCode.Unknown then
			local name = Guard.get(code, "Name")
			if type(name) == "string" then
				return name
			end
		end
	
		local kind = Guard.get(input, "UserInputType")
		if kind ~= nil then
			local name = Guard.get(kind, "Name")
			if type(name) == "string" then
				return name
			end
		end
	
		local direct = Guard.get(input, "Name")
		return type(direct) == "string" and direct or nil
	end
	
	--- Does this engine input fire this binding? A binding stores an Enum member and the engine hands
	--- over a UserInput object, so the two are never equal and the comparison has to go through the
	--- object's own KeyCode / UserInputType member.
	local function matchesInput(binding: any, input: any): boolean
		if binding == nil or binding.input == nil or input == nil then
			return false
		end
		local wanted = binding.input
		if Guard.get(input, "KeyCode") == wanted or Guard.get(input, "UserInputType") == wanted then
			return true
		end
		return inputName(input) == inputName(wanted)
	end
	
	--- A binding's trigger can be a KeyCode, a UserInputType (mouse buttons), or the name of either
	--- as typed in a config file.
	local function resolve(value: any): any
		local enumItem = Guard.get(value, "Name")
		if enumItem ~= nil and typeof(value) == "EnumItem" then
			return value
		end
	
		if type(value) == "string" then
			local byKey = Guard.get(Enum.KeyCode, value)
			if byKey ~= nil then
				return byKey
			end
			return Guard.get(Enum.UserInputType, value)
		end
	
		if type(value) == "table" then
			-- A config restores { Name = "G", Enum = "KeyCode" }.
			local name = value.Name
			if type(name) == "string" then
				local wanted = value.Enum == "UserInputType" and Enum.UserInputType or Enum.KeyCode
				return Guard.get(wanted, name) or Guard.get(Enum.KeyCode, name) or Guard.get(Enum.UserInputType, name)
			end
		end
	
		return nil
	end
	
	--- Which modifiers are down right now, as a name-keyed set.
	function InputManager.modifiers(): {[string]: boolean}
		local out = { Ctrl = false, Shift = false, Alt = false }
		if UserInputService == nil then
			return out
		end
	
		local ok, mods = pcall(function()
			return UserInputService:GetModifiersState()
		end)
	
		if ok and mods ~= nil then
			out.Ctrl = Guard.get(mods, "Ctrl") == true
			out.Shift = Guard.get(mods, "Shift") == true
			out.Alt = Guard.get(mods, "Alt") == true
			out.Meta = Guard.get(mods, "Meta") == true
			return out
		end
	
		-- Older clients have no GetModifiersState. Keycode polling is not exactly the same (it misses
		-- the synthetic modifier some emulated inputs produce) but a chord that never matches is
		-- worse than one that occasionally over-matches.
		local lctrl = Guard.get(Enum.KeyCode, "LeftControl")
		local rctrl = Guard.get(Enum.KeyCode, "RightControl")
		out.Ctrl = (lctrl and InputManager.isDown(lctrl)) or (rctrl and InputManager.isDown(rctrl)) or false
	
		local lshift = Guard.get(Enum.KeyCode, "LeftShift")
		local rshift = Guard.get(Enum.KeyCode, "RightShift")
		out.Shift = (lshift and InputManager.isDown(lshift)) or (rshift and InputManager.isDown(rshift)) or false
	
		local lalt = Guard.get(Enum.KeyCode, "LeftAlt")
		local ralt = Guard.get(Enum.KeyCode, "RightAlt")
		out.Alt = (lalt and InputManager.isDown(lalt)) or (ralt and InputManager.isDown(ralt)) or false
	
		return out
	end
	
	--- A key that is itself a modifier has to be excused from the modifier check when it is the
	--- trigger, or the classic `ToggleKey = RightControl` could never fire: holding the right control
	--- key down is exactly what makes `GetModifiersState().Ctrl` read true.
	local MODIFIER_KEYS = {
		Ctrl = { LeftControl = true, RightControl = true },
		Shift = { LeftShift = true, RightShift = true },
		Alt = { LeftAlt = true, RightAlt = true },
		Meta = { LeftMeta = true, RightMeta = true },
	}
	
	local function effectiveMods(mods: {[string]: boolean}, trigger: any): {[string]: boolean}
		local name = trigger ~= nil and inputName(trigger) or nil
		if name == nil then
			return mods
		end
	
		local out = {}
		for key, down in pairs(mods) do
			local family = MODIFIER_KEYS[key]
			out[key] = down == true and (family == nil or family[name] ~= true)
		end
		return out
	end
	
	--- Match a requested modifier set against what is down. Keys are compared case-insensitively and
	--- Left/Right variants collapse, so a config written as { Ctrl = true } works.
	local function modifiersMatch(requested: {[string]: boolean}?, mods: {[string]: boolean}): boolean
		if requested == nil or next(requested) == nil then
			-- A bare bind must not fire while a modifier is held: Ctrl+S reaching a "S" bind would
			-- fight the browser-style save the user expects.
			return not (mods.Ctrl or mods.Shift or mods.Alt or mods.Meta)
		end
	
		-- The names a caller may ask for are normalised by InputManager.modifiers(), so Ctrl matches
		-- either control key. Mods the caller did not list are not checked: a Shift+G bind still fires
		-- with Ctrl held, which is the least surprising rule once a config file is hand-written.
		for name, wanted in pairs(requested) do
			if wanted ~= (mods[name] == true) then
				return false
			end
		end
		return true
	end
	
	--- Poll the engine for a key or mouse button.
	function InputManager.isDown(input: any): boolean
		local resolved = resolve(input)
		if resolved == nil then
			return false
		end
		if UserInputService == nil then
			return false
		end
		local ok, down = pcall(function()
			return UserInputService:IsKeyDown(resolved)
		end)
		if ok then
			return down == true
		end
		return false
	end
	
	--- A released binding is a table with these fields; every method is safe to call twice.
	local handle = {}
	handle.__index = handle
	
	function handle.Set(self: any, input: any, mods: {[string]: boolean}?)
		local resolved = resolve(input)
		if resolved == nil then
			warn("[Flux] input: cannot bind " .. tostring(input))
			return false
		end
		self.input = resolved
		self.mods = mods
		held[self] = false
		InputManager.Changed:Dispatch(self)
		return true
	end
	
	function handle.GetInput(self: any): any
		return self.input
	end
	
	--- The text a keybind row shows.
	function handle.GetLabel(self: any): string
		if self.input == nil then
			return "Unbound"
		end
		local base = String.keyName(self.input)
		if self.mods == nil or next(self.mods) == nil then
			return base
		end
	
		local parts = {}
		for _, name in ipairs({ "Ctrl", "Shift", "Alt" }) do
			if self.mods[name] then
				table.insert(parts, name)
			end
		end
		table.insert(parts, base)
		return table.concat(parts, " + ")
	end
	
	--- True while the key is physically down. A hold-style feature reads this each frame.
	function handle.GetState(self: any): boolean
		if self.input == nil then
			return false
		end
		if not InputManager.isDown(self.input) then
			return false
		end
		return modifiersMatch(self.mods, effectiveMods(InputManager.modifiers(), self.input))
	end
	
	function handle.IsHeld(self: any): boolean
		return held[self] == true
	end
	
	--- Force the binding off. Called when the feature it gates is switched off, so a key held across
	--- the toggle does not leave the effect running.
	function handle.Release(self: any)
		if held[self] then
			held[self] = false
			if self.onUp ~= nil then
				self.onUp(self)
			end
		end
	end
	
	function handle.Destroy(self: any)
		if self.destroyed then
			return
		end
		self.destroyed = true
		held[self] = nil
	
		for index = #bindings, 1, -1 do
			if bindings[index] == self then
				table.remove(bindings, index)
			end
		end
	end
	
	--- Register a keybind.
	---   Key     — Enum.KeyCode / Enum.UserInputType member, its name, or a restored config table.
	---   OnDown / OnUp / Callback — Callback fires on press for a toggle bind, and on both edges for
	---           a hold bind (so the caller can drive either style from one registration).
	---   Mode    — "toggle" (default) or "hold".
	function InputManager.bind(options: {
		Name: string?,
		Key: any,
		Mods: {[string]: boolean}?,
		Mode: string?,
		Callback: ((boolean) -> ())?,
		OnDown: ((any) -> ())?,
		OnUp: ((any) -> ())?,
		AllowWhileTyping: boolean?,
	}): any
		local input = resolve(options.Key)
	
		local binding = setmetatable({
			name = options.Name or "bind",
			mode = options.Mode or "toggle",
			input = input,
			mods = options.Mods,
			callback = options.Callback,
			onDown = options.OnDown,
			onUp = options.OnUp,
			allowWhileTyping = options.AllowWhileTyping == true,
			enabled = true,
		}, handle)
	
		InputManager.listen()
		table.insert(bindings, binding)
		return binding
	end
	
	function InputManager.list(): {any}
		return Table.copy(bindings)
	end
	
	--- How many bindings currently point at this key, which is what a conflict warning counts.
	function InputManager.conflictsFor(input: any): {any}
		local resolved = resolve(input)
		local out = {}
		if resolved == nil then
			return out
		end
		for _, binding in ipairs(bindings) do
			if not binding.destroyed and binding.input == resolved then
				table.insert(out, binding)
			end
		end
		return out
	end
	
	--- Release every held binding without unregistering them: the window hid, the game lost focus.
	function InputManager.releaseAll(reason: string?)
		for _, binding in ipairs(Table.copy(bindings)) do
			if not binding.destroyed then
				binding:Release()
			end
		end
		return reason
	end
	
	function InputManager.clear()
		for index = #bindings, 1, -1 do
			bindings[index]:Destroy()
		end
		table.clear(bindings)
	end
	
	local function focused(): boolean
		if UserInputService == nil then
			return false
		end
		local ok, box = pcall(function()
			return UserInputService:GetFocusedTextBox()
		end)
		return ok and box ~= nil
	end
	
	--- One capture session per picker. Resolves with { Input, Mods, Cancelled }.
	function InputManager.capture(options: { OnCancel: (() -> ())?, ClearOnDelete: boolean?, Timeout: number? }): any
		local result = Signal.new()
	
		local session = { finished = false, options = options or {} }
	
		local function finish(payload: {[string]: any})
			if session.finished then
				return
			end
			session.finished = true
	
			if session.inputConnection ~= nil then
				session.inputConnection:Disconnect()
			end
			if session.endedConnection ~= nil then
				session.endedConnection:Disconnect()
			end
			if session.thread ~= nil then
				task.cancel(session.thread)
			end
	
			for index = #captureSessions, 1, -1 do
				if captureSessions[index] == session then
					table.remove(captureSessions, index)
				end
			end
	
			if payload.cancelled and options ~= nil and options.OnCancel ~= nil then
				options.OnCancel()
			end
			result:Dispatch(payload)
		end
	
		table.insert(captureSessions, session)
	
		if UserInputService == nil or #captureSessions > 1 then
			-- Two pickers open at once is not a thing in this UI, and a client without the input
			-- service cannot capture at all. Fail the session rather than hang the picker: a session
			-- with no listener behind it has no way to end on its own.
			if UserInputService == nil then
				task.defer(finish, { cancelled = true, blocked = "no-input-service" })
			else
				task.defer(finish, { cancelled = true, blocked = "another-session" })
			end
			return {
				Done = result,
				Cancel = function()
					finish({ cancelled = true })
				end,
			}
		end
	
		session.inputConnection = UserInputService.InputBegan:Connect(function(input, processed)
			if session.finished then
				return
			end
	
			local name = inputName(input)
	
			if name == "Escape" then
				finish({ cancelled = true })
				return
			end
	
			if name == "Backspace" or name == "Delete" then
				if session.options.ClearOnDelete ~= false then
					finish({ cleared = true })
				end
				return
			end
	
			-- A mouse button is a legitimate bind even when the click also hit UI, so `processed`
			-- only filters keys the game already consumed through a TextBox.
			local code = Guard.get(input, "KeyCode")
			if processed and code ~= nil and code ~= Enum.KeyCode.Unknown then
				return
			end
	
			if InputManager.forbidden[name] then
				return
			end
	
			if focused() then
				return
			end
	
			-- Hand back the Enum member, not the UserInput object: the payload goes straight into
			-- handle.Set, which stores what resolve() can turn back into a trigger later.
			local trigger = code ~= nil and code ~= Enum.KeyCode.Unknown and code or Guard.get(input, "UserInputType")
			finish({ input = trigger, mods = effectiveMods(InputManager.modifiers(), trigger) })
		end)
	
		if type(session.options.Timeout) == "number" then
			session.thread = task.delay(session.options.Timeout, function()
				finish({ cancelled = true, timedOut = true })
			end)
		end
	
		return {
			Done = result,
			Cancel = function()
				finish({ cancelled = true })
			end,
		}
	end
	
	--- Any open capture sessions, for tests and for the picker's own "is someone else listening" check.
	function InputManager.capturing(): number
		return #captureSessions
	end
	
	--- Install the engine listeners. Idempotent, and called by `bind` as well as at load: `unload`
	--- disconnects these, and a host that runs the loader again after `Flux:Unload()` expects its
	--- hotkeys to work in the new hub without restarting the client.
	function InputManager.listen()
		if UserInputService == nil or #connections > 0 then
			return false
		end
	
		connections[#connections + 1] = UserInputService.InputBegan:Connect(function(input, processed)
			if processed then
				return
			end
	
			-- A key the game already consumed (typing in a TextBox) only reaches bindings that asked
			-- for it, which is what AllowWhileTyping is for.
			local typing = focused()
			local mods = InputManager.modifiers()
			for _, binding in ipairs(bindings) do
				if not binding.destroyed and binding.enabled and matchesInput(binding, input)
					and modifiersMatch(binding.mods, effectiveMods(mods, binding.input))
					and (binding.allowWhileTyping or not typing) then
					if not held[binding] then
						held[binding] = true
						if binding.mode == "hold" then
							if binding.onDown ~= nil then
								binding.onDown(binding)
							end
							if binding.callback ~= nil then
								binding.callback(true)
							end
						else
							if binding.callback ~= nil then
								binding.callback(true)
							end
							if binding.onDown ~= nil then
								binding.onDown(binding)
							end
						end
					end
				end
			end
		end)
	
		connections[#connections + 1] = UserInputService.InputEnded:Connect(function(input)
			for _, binding in ipairs(bindings) do
				if not binding.destroyed and matchesInput(binding, input) and held[binding] then
					held[binding] = false
					if binding.mode == "hold" then
						if binding.onUp ~= nil then
							binding.onUp(binding)
						end
						if binding.callback ~= nil then
							binding.callback(false)
						end
					end
				end
			end
		end)
	
		-- Focus loss is the case InputEnded misses: alt-tab with a hold key down and the engine never
		-- reports the release.
		local blur = Guard.get(UserInputService, "WindowFocusReleased")
		if blur ~= nil then
			connections[#connections + 1] = blur:Connect(function()
				InputManager.releaseAll("focus")
			end)
		end
	
		return true
	end
	
	InputManager.listen()
	
	function InputManager.connections(): number
		return #connections
	end
	
	--- Tear down the engine listeners. Only used by the hub's own unload.
	function InputManager.unload()
		for _, connection in ipairs(connections) do
			connection:Disconnect()
		end
		table.clear(connections)
		InputManager.clear()
	end
	
	return InputManager
end

-- src/Systems/LayoutManager.lua
FluxRegistry["Flux/Systems/LayoutManager"] = function(require)
	--[[
		Systems/LayoutManager — one place decides how big the UI is and where it may sit.

		The problem this solves: a menu authored at 900x560 fills a phone screen and a 1080p window
		looks tiny, and both are the same client. Rather than size every widget against the viewport
		(the usual way a UI ends up unreadable on one of the two), the library is authored once at a
		base size and the whole window carries a single UIScale.

		Scale is capped at 1. Letting it grow past one is how a library "supports" ultrawide monitors
		by rendering blurry text at 1.4x; a large viewport should show more content, which is the
		column-count job, not the font-size job.
	]]

	local Signal = require("Flux/Utilities/Signal")
	local Guard = require("Flux/Utilities/Guard")
	local Math = require("Flux/Utilities/Math")

	local RunService = Guard.service("RunService")
	local UserInputService = Guard.service("UserInputService")
	local GuiService = Guard.service("GuiService")
	local Workspace = Guard.service("Workspace")

	local LayoutManager = {}

	--- The size the UI is authored at. Components use offsets against this, never the viewport.
	local base = Vector2.new(900, 560)

	local state = {
		scale = 1,
		viewport = Vector2.new(1280, 720),
		mode = "desktop",
		mobile = false,
		inset = Vector2.new(0, 0),
	}

	local forcedMode: string? = nil
	local watched = false

	--- Fires (scale, viewport, mode) whenever the answer changes. Windows re-clamp their position on
	--- this; nothing else needs to react, which is the point of scaling one instance.
	LayoutManager.Changed = Signal.new()

	--- A viewport this small, or a touch device, gets the compact layout: nav becomes a top strip and
	--- the content column stops trying to be two columns wide.
	LayoutManager.breakpoints = {
		compact = 760,
		phone = 560,
	}

	local function readViewport(): Vector2
		local camera = Workspace and Workspace.CurrentCamera
		local size = camera and Guard.get(camera, "ViewportSize")
		if type(size) == "userdata" or type(size) == "table" then
			if type(size.X) == "number" and type(size.Y) == "number" then
				return size
			end
		end
		return state.viewport
	end

	local function readInset(): Vector2
		-- Safe-area insets only exist on a touch device; the two APIs are alternatives, not both.
		if GuiService ~= nil then
			local safe = Guard.get(GuiService, "SafeAreaInsets")
			if safe ~= nil then
				return Vector2.new(math.max(safe.Left, safe.Right), math.max(safe.Top, safe.Bottom))
			end

			local ok, x, y = pcall(function()
				return GuiService:GetGuiInsets()
			end)
			if ok then
				return Vector2.new(math.max(x or 0, 0), math.max(y or 0, 0))
			end
		end

		return state.inset
	end

	local function touchOnly(): boolean
		if UserInputService == nil then
			return false
		end
		local touch = Guard.get(UserInputService, "TouchEnabled")
		local keyboard = Guard.get(UserInputService, "KeyboardEnabled")
		if touch == true and keyboard == false then
			return true
		end
		return false
	end

	local function modeFor(width: number): string
		if forcedMode ~= nil then
			return forcedMode
		end
		if width <= LayoutManager.breakpoints.phone then
			return "phone"
		end
		if width <= LayoutManager.breakpoints.compact then
			return "compact"
		end
		return "desktop"
	end

	--- A window that fills the screen edge to edge is what makes a hub look amateur on a laptop, so
	--- the fit is measured against a viewport with breathing room removed.
	local margin = 24

	local function recompute(): boolean
		local viewport = readViewport()
		local mode = modeFor(viewport.X)
		local mobile = forcedMode ~= nil and (forcedMode ~= "desktop") or (mode == "phone") or touchOnly()
		local scale = Math.fitScale(base, Vector2.new(math.max(160, viewport.X - margin), math.max(120, viewport.Y - margin)), 0.55)
		local inset = readInset()

		if viewport.X == state.viewport.X and viewport.Y == state.viewport.Y and mode == state.mode and scale == state.scale and inset.X == state.inset.X and inset.Y == state.inset.Y then
			return false
		end

		state.viewport = viewport
		state.mode = mode
		state.mobile = mobile
		state.scale = scale
		state.inset = inset
		return true
	end

	--- Call once per resize, or on demand. Dispatches Changed only when the answer moved, so a
	--- window does not re-clamp itself on every frame.
	function LayoutManager.refresh(): boolean
		local changed = recompute()
		if changed then
			LayoutManager.Changed:Dispatch(state.scale, state.viewport, state.mode)
		end
		return changed
	end

	--- Start listening. Deliberately separate from require: a hub that never opens a window should
	--- not hold a RenderStepped connection.
	function LayoutManager.watch()
		if watched then
			return false
		end

		local camera = Workspace and Workspace.CurrentCamera
		local getter = camera and Guard.get(camera, "GetPropertyChangedSignal")
		if type(getter) == "function" then
			-- GetPropertyChangedSignal hands back a signal, not a connection; only what Connect
			-- returns can be disconnected, so the connection is what gets stored.
			local ok, signal = pcall(getter, camera, "ViewportSize")
			if ok and signal ~= nil then
				local connected, connection = pcall(function()
					-- Deferred rather than handled inline: during a device rotation ViewportSize moves
					-- several times and the window's absolute size is only settled on the next frame.
					return signal:Connect(function()
						task.defer(LayoutManager.refresh)
					end)
				end)
				if connected and connection ~= nil then
					watched = true
					LayoutManager._resizeConnection = connection
					return true
				end
			end
		end

		-- No camera signal available (no camera yet, or a client without the member): fall back to a
		-- cheap poll on RenderStepped. recompute() early-returns when nothing moved, so the idle cost
		-- is one userdata read.
		if RunService ~= nil then
			watched = true
			LayoutManager._frameConnection = RunService.RenderStepped:Connect(function()
				LayoutManager.refresh()
			end)
			return true
		end

		-- Left unset so a host that watches again after the camera appears actually attaches.
		return false
	end

	function LayoutManager.unwatch()
		for _, key in ipairs({ "_resizeConnection", "_frameConnection" }) do
			local connection = LayoutManager[key]
			if connection ~= nil then
				connection:Disconnect()
				LayoutManager[key] = nil
			end
		end
		watched = false
	end

	--- Apply the current scale to a top-level gui (each window carries its own UIScale).
	function LayoutManager.apply(gui: any)
		if gui == nil then
			return
		end
		Guard.set(gui, "UIScale", state.scale)
	end

	function LayoutManager.scale(): number
		return state.scale
	end

	function LayoutManager.viewport(): Vector2
		return state.viewport
	end

	function LayoutManager.base(): Vector2
		return base
	end

	function LayoutManager.setBase(width: number, height: number)
		base = Vector2.new(width, height)
		LayoutManager.refresh()
	end

	function LayoutManager.mode(): string
		return state.mode
	end

	function LayoutManager.isMobile(): boolean
		return state.mobile
	end

	--- Force a layout for testing or for a host that knows better than the breakpoint guess.
	function LayoutManager.setMode(mode: string?)
		if mode == nil or mode == "auto" then
			forcedMode = nil
		else
			forcedMode = mode
		end
		LayoutManager.refresh()
	end

	function LayoutManager.inset(): Vector2
		return state.inset
	end

	--- Convert a screen point (mouse position) into the window's own scaled coordinates. Dragging and
	--- cursor-anchored tooltips both need this, and getting it wrong by the scale factor is the usual
	--- reason a tooltip appears a finger-width away from the pointer on a phone.
	function LayoutManager.toLocal(point: Vector2): Vector2
		return Vector2.new(point.X / state.scale, point.Y / state.scale)
	end

	--- Keep a window inside the viewport after a resize, preserving its size in offset terms.
	function LayoutManager.clamp(position: UDim2, size: UDim2, anchor: Vector2?): UDim2
		local viewport = state.viewport
		local scale = state.scale
		local width = (size.X.Scale * viewport.X + size.X.Offset) * scale
		local height = (size.Y.Scale * viewport.Y + size.Y.Offset) * scale

		local anchorX = (anchor and anchor.X or 0) * width
		local anchorY = (anchor and anchor.Y or 0) * height

		local left = (position.X.Scale * viewport.X + position.X.Offset) * scale - anchorX
		local top = (position.Y.Scale * viewport.Y + position.Y.Offset) * scale - anchorY

		local margin = 8 * scale
		local maxLeft = math.max(margin, viewport.X - width - margin)
		local maxTop = math.max(margin, viewport.Y - height - margin)

		local clampedLeft = Math.clamp(left, margin, maxLeft)
		local clampedTop = Math.clamp(top, margin, maxTop)

		return UDim2.new(0, clampedLeft / scale + anchorX / scale, 0, clampedTop / scale + anchorY / scale)
	end

	--- Two-column content fits at this width; below it, a single column reads better than a squashed
	--- pair. Components ask rather than measuring, so the rule lives once.
	function LayoutManager.columns(available: number?, minimum: number?): (number, number)
		local width = available or (state.viewport.X * state.scale)
		local columnMinimum = minimum or 300
		local count = Math.clamp(math.floor((width - 48) / columnMinimum), 1, 3)
		return count, columnMinimum
	end

	--- A page taller than the viewport gets a scrolling canvas sized to what is left of the chrome.
	function LayoutManager.contentHeight(chrome: number?): number
		local used = chrome or 0
		return math.max(120, (state.viewport.Y / state.scale) - used)
	end

	LayoutManager.refresh()

	return LayoutManager
end

-- src/Systems/NotificationManager.lua
FluxRegistry["Flux/Systems/NotificationManager"] = function(require)
	--[[
		Systems/NotificationManager — the toast stack.

		One instance per notification (about six), a shared UIListLayout for ordering, and a
		dismissal timer driven by task.delay so the stack costs nothing between events. The queue
		cap exists because an unbounded stack on a phone viewport pushes its own top item off
		screen, which is the opposite of a notification.

		A notification whose text is updated re-times itself: a progress toast that finishes at 80 %
		because nobody refreshed the timer is a lie the UI tells about the work.
	]]

	local Signal = require("Flux/Utilities/Signal")
	local Instance = require("Flux/Utilities/Instance")
	local Maid = require("Flux/Utilities/Maid")
	local Guard = require("Flux/Utilities/Guard")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	local AnimationManager = require("Flux/Systems/AnimationManager")
	local IconManager = require("Flux/Systems/IconManager")
	local Element = require("Flux/Core/Element")
	local String = require("Flux/Utilities/String")
	local Math = require("Flux/Utilities/Math")

	local Notifications = {}

	local settings = {
		Max = 4,
		Duration = 5,
		Width = 288,
		Anchor = "TopRight",
		Padding = 10,
	}

	local stack: any = nil
	local owner: Maid? = nil
	local visible = {}
	local dropped = 0

	Notifications.Added = Signal.new()
	Notifications.Removed = Signal.new()

	--- Which role paints the accent strip for a kind. Unknown kinds read as info rather than failing.
	Notifications.kinds = {
		info = "Info",
		success = "Success",
		warning = "Warning",
		error = "Error",
	}

	Notifications.icons = {
		info = "info",
		success = "check",
		warning = "warning",
		error = "error",
	}

	function Notifications.configure(options: { Max: number?, Duration: number?, Width: number?, Anchor: string? })
		options = options or {}
		if type(options.Max) == "number" then
			settings.Max = math.max(1, math.floor(options.Max))
		end
		if type(options.Duration) == "number" then
			settings.Duration = math.max(0.5, options.Duration)
		end
		if type(options.Width) == "number" then
			settings.Width = math.max(160, options.Width)
		end
		if type(options.Anchor) == "string" then
			settings.Anchor = options.Anchor
		end
		return settings
	end

	--- Attach the stack to an existing ScreenGui. Called by the library when a window is built; if it
	--- is never called, the first notification creates its own collector so a hub that only notifies
	--- still works.
	function Notifications.attach(gui: any)
		if gui == nil or stack == gui then
			return
		end

		if stack ~= nil then
			-- Re-attaching is a second window opening. The frame moves to the new host instead of being
			-- rebuilt in it: the toasts already on screen belong to the hub, not to whichever window was
			-- open when they fired, and a card the user can see but no longer reach is worse than one
			-- that jumped sides.
			if stack.Parent ~= gui then
				stack.Parent = gui
			end
			return
		end

		if owner ~= nil then
			owner:cleanup()
		end

		owner = Maid.new()
		stack = Instance.new("Frame", gui, {
			Name = "NotificationStack",
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(settings.Width, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Position = UDim2.new(1, -settings.Width - settings.Padding, 0, settings.Padding),
			AnchorPoint = Vector2.new(1, 0),
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		})

		Element.stack(owner, stack, { Gap = "GroupGap" })
	end

	--- Let go of a stack whose host is going away. A window that is destroyed with the stack still
	--- attached would otherwise hand the next notification to a ScreenGui no longer in the tree, which
	--- shows nothing and warns about nothing.
	function Notifications.detach(gui: any): boolean
		if gui == nil or stack == nil or stack.Parent ~= gui then
			return false
		end

		Notifications.clear()
		if owner ~= nil then
			owner:cleanup()
			owner = nil
		end
		stack:Destroy()
		stack = nil
		return true
	end

	local function ensureStack()
		if stack ~= nil then
			return
		end
		local maid = Maid.new()
		Notifications.attach(Element.root(maid, { Name = "FluxHub/Notifications", Order = 1001 }))
		-- attach() replaces the maid it was given with its own, so the collector's owner is the one
		-- that outlives the notification it was created for.
		Notifications._collectorMaid = maid
	end

	local handle = {}
	handle.__index = handle

	function handle.GetText(self: any): string
		return self.text
	end

	--- Replace text and/or progress. Re-times the dismissal unless the caller says otherwise.
	function handle.Update(self: any, options: { Title: string?, Text: string?, Progress: number?, Retime: boolean? })
		if self.destroyed then
			return false
		end

		options = options or {}

		if type(options.Text) == "string" then
			self.text = options.Text
			Guard.set(self.textLabel, "Text", String.escape(options.Text))
		end

		if type(options.Title) == "string" then
			Guard.set(self.title, "Text", String.escape(options.Title))
		end

		if type(options.Progress) == "number" then
			local amount = Math.clamp(options.Progress, 0, 1)
			self.bar.Size = UDim2.fromScale(amount, 1)
			self.progress = amount
		end

		if options.Retime ~= false then
			self:retime()
		end

		return true
	end

	function handle.Dismiss(self: any, instant: boolean?)
		if self.destroyed then
			return
		end
		self.destroyed = true

		for index = #visible, 1, -1 do
			if visible[index] == self then
				table.remove(visible, index)
			end
		end

		if self.timer ~= nil then
			task.cancel(self.timer)
			self.timer = nil
		end

		local function remove()
			if self.instance ~= nil then
				self.instance:Destroy()
			end
			if self.maid ~= nil then
				self.maid:cleanup()
			end
			Notifications.Removed:Dispatch(self.id)
			Notifications.pump()
		end

		if instant or AnimationManager.isReducedMotion() then
			remove()
		else
			-- GroupTransparency fades the whole card including its text; on a client without the
			-- member AnimationManager skips it and only the fill fades, which is why it is listed
			-- alongside rather than instead of BackgroundTransparency.
			AnimationManager.to(self.instance, {
				BackgroundTransparency = 1,
				GroupTransparency = 1,
			}, { Duration = 0.12, Easing = "outQuad", OnEnd = remove })
		end
	end

	--- Restart the countdown.
	function handle.retime(self: any)
		if self.timer ~= nil then
			task.cancel(self.timer)
		end
		if self.duration <= 0 then
			return
		end
		self.timer = task.delay(self.duration, function()
			self:Dismiss()
		end)
	end

	local nextId = 0

	--- Show a notification. Returns a handle with Update/Dismiss/GetText.
	function Notifications.notify(options: {
		Title: string?,
		Text: string?,
		Duration: number?,
		Kind: string?,
		Icon: string?,
		Progress: number?,
		Persistent: boolean?,
	}): any
		ensureStack()

		options = options or {}
		local kind = Notifications.kinds[options.Kind] and options.Kind or "info"
		local role = Notifications.kinds[kind]
		local duration = options.Duration or settings.Duration
		if options.Persistent then
			duration = 0
		end

		nextId += 1
		local maid = Maid.new()

		local card = Element.panel(maid, stack, "Notification_" .. nextId, {
			Color = "Panel",
			Radius = "RadiusPanel",
			Stroke = "BorderPrimary",
			Size = UDim2.fromOffset(settings.Width, 0),
			Clips = true,
		})
		card.AutomaticSize = Enum.AutomaticSize.Y

		local accent = Instance.new("Frame", card, {
			Name = "Accent",
			BackgroundColor3 = ThemeManager.color(role),
			BorderSizePixel = 0,
			Size = UDim2.new(0, 3, 1, -16),
			Position = UDim2.fromOffset(8, 8),
		})
		maid:give(ThemeManager.bind(accent, "BackgroundColor3", role))
		Element.round(maid, accent, "RadiusChip")

		-- The glyph is what makes a kind readable without reading the sentence. A host that names one
		-- overrides the kind's default, and a name the atlas does not hold leaves the accent strip to
		-- carry the meaning on its own rather than showing a box.
		local glyph = options.Icon or Notifications.icons[kind]
		local inset = 26
		if glyph ~= nil and IconManager.has(glyph) then
			Element.icon(maid, card, glyph, {
				Role = role,
				Size = UDim2.fromOffset(14, 14),
				Position = UDim2.fromOffset(20, 10),
				ZIndex = 6,
			})
			inset = 42
		end

		local body = Instance.new("Frame", card, {
			Name = "Body",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, -(inset + 8), 1, 0),
			Position = UDim2.fromOffset(inset, 0),
		})

		local title = Element.label(maid, body, "Title", {
			Text = String.escape(options.Title or "Flux"),
			Role = "TextPrimary",
			Font = "Subtitle",
			TextSize = 14,
			Size = UDim2.new(1, 0, 0, 18),
		})

		local textLabel = Element.label(maid, body, "Text", {
			Text = String.escape(options.Text or ""),
			Role = "TextSecondary",
			TextSize = 13,
			Wrap = true,
			Size = UDim2.new(1, 0, 0, 16),
			Position = UDim2.fromOffset(0, 20),
		})

		local barHost = Instance.new("Frame", card, {
			Name = "ProgressTrack",
			BackgroundColor3 = ThemeManager.color("Field"),
			BorderSizePixel = 0,
			Size = UDim2.new(1, -(inset + 8), 0, 3),
			Position = UDim2.fromOffset(inset, 44),
			Visible = type(options.Progress) == "number",
		})
		maid:give(ThemeManager.bind(barHost, "BackgroundColor3", "Field"))
		Element.round(maid, barHost, "RadiusChip")

		local bar = Instance.new("Frame", barHost, {
			Name = "Progress",
			BackgroundColor3 = ThemeManager.color(role),
			BorderSizePixel = 0,
			Size = UDim2.fromScale(type(options.Progress) == "number" and math.max(0, math.min(1, options.Progress)) or 0, 1),
		})
		maid:give(ThemeManager.bind(bar, "BackgroundColor3", role))
		Element.round(maid, bar, "RadiusChip")

		local self = setmetatable({
			id = nextId,
			instance = card,
			title = title,
			textLabel = textLabel,
			bar = bar,
			barHost = barHost,
			kind = kind,
			text = options.Text or "",
			duration = duration,
			progress = options.Progress,
			maid = maid,
			destroyed = false,
		}, handle)

		table.insert(visible, self)
		Notifications.Added:Dispatch(self.id)

		if duration > 0 then
			self:retime()
		end

		-- Entrance motion after the card exists, so the first frame renders at its resting state if
		-- the client cannot animate.
		card.BackgroundTransparency = 1
		AnimationManager.to(card, { BackgroundTransparency = 0 }, { Duration = 0.16, Easing = "outQuad" })

		Notifications.pump()
		return self
	end

	--- Trim the stack to the cap, oldest first. The pushed-out toast is gone rather than queued: its
	--- card is destroyed with it, so a list of what the cap dropped is the only honest bookkeeping.
	function Notifications.pump()
		while #visible > settings.Max do
			local oldest = table.remove(visible, 1)
			if oldest ~= nil then
				dropped += 1
				oldest:Dismiss()
			end
		end
	end

	function Notifications.count(): number
		return #visible
	end

	--- How many toasts this session the cap dismissed before their own duration was up.
	function Notifications.dropped(): number
		return dropped
	end

	function Notifications.clear()
		for index = #visible, 1, -1 do
			visible[index]:Dismiss(true)
		end
		table.clear(visible)
		dropped = 0
	end

	--- Tear the stack down with the hub.
	function Notifications.destroy()
		Notifications.clear()
		if stack ~= nil then
			stack:Destroy()
			stack = nil
		end
		if owner ~= nil then
			owner:cleanup()
			owner = nil
		end
		if Notifications._collectorMaid ~= nil then
			Notifications._collectorMaid:cleanup()
			Notifications._collectorMaid = nil
		end
	end

	return Notifications
end

-- src/Systems/Renderer.lua
FluxRegistry["Flux/Systems/Renderer"] = function(require)
	--[[
		Systems/Renderer — build what is visible now, spread the rest over frames.

		Why this exists: a hub that constructs its whole UI on execute pays for every row the user
		has not looked at. On a real device a page of ~30 rows built in one synchronous pass is where
		"executes and freezes" comes from — the cost is instances, not code. So a page asks to be
		built, and the build is sliced across RenderStepped frames with a cost ceiling.

		Two rules the rest of the library relies on:
		  * the loop runs only while work is queued, same contract as AnimationManager;
		  * a job is a closure that creates a bounded number of instances and declares its cost, so
		    the ceiling is in units the device actually feels rather than in milliseconds the test
		    harness cannot measure.

		Jobs run in enqueue order. A job that enqueues more work while the queue is draining is
		appended to the same pass it is running in, which is what lets a groupbox build its rows and
		then have those rows register themselves.
	]]

	local Signal = require("Flux/Utilities/Signal")
	local Guard = require("Flux/Utilities/Guard")

	local RunService = Guard.service("RunService")

	local Renderer = {}

	--- Fires when the queue empties, with the number of jobs that ran. Callers use it to reveal a
	--- page only once its rows exist, instead of showing an empty panel for a few frames.
	Renderer.Idle = Signal.new()

	local budget = {
		-- Instances a single frame may create. Measured on the reference device: a row is roughly
		-- six instances, so this is about twenty rows a frame, which stays inside 16 ms.
		CostPerFrame = 120,
		-- A second ceiling so a queue of cost-1 jobs cannot occupy a frame forever.
		JobsPerFrame = 32,
	}

	local queue = {}
	local connection: RBXScriptConnection? = nil
	local draining = false
	local stats = {
		passes = 0,
		ran = 0,
		lastPassJobs = 0,
		lastPassCost = 0,
		peakPassCost = 0,
	}

	local function stopLoop()
		if connection ~= nil then
			connection:Disconnect()
			connection = nil
		end
	end

	function Renderer.configure(options: { CostPerFrame: number?, JobsPerFrame: number? })
		options = options or {}
		if type(options.CostPerFrame) == "number" then
			budget.CostPerFrame = math.max(1, options.CostPerFrame)
		end
		if type(options.JobsPerFrame) == "number" then
			budget.JobsPerFrame = math.max(1, options.JobsPerFrame)
		end
		return budget
	end

	function Renderer.budget(): { CostPerFrame: number, JobsPerFrame: number }
		return budget
	end

	--- Queue a unit of work.
	---   Name  — optional; a later enqueue with the same name replaces this one, which is how a
	---           filter that runs on every keystroke does not rebuild a list four times.
	---   Cost  — instances it will create (default 1).
	---   Run   — the build itself.
	---   OnDone— called with (ok, err) after Run. A job that throws is reported and dropped: one
	---           broken row must not stop the rest of the page from appearing.
	function Renderer.enqueue(job: { Name: string?, Cost: number?, Run: () -> (), OnDone: ((boolean, any) -> ())? }): any
		local entry = {
			name = job.Name,
			cost = math.max(1, job.Cost or 1),
			run = job.Run,
			onDone = job.OnDone,
		}

		if entry.name ~= nil then
			for index = #queue, 1, -1 do
				if queue[index].name == entry.name then
					table.remove(queue, index)
				end
			end
		end

		table.insert(queue, entry)

		if connection == nil and RunService ~= nil then
			connection = RunService.RenderStepped:Connect(Renderer.step)
		end

		return entry
	end

	--- A list of items built one job per item, so a long table arrives in frames rather than a freeze.
	function Renderer.batch(items: {any}, make: (any, number) -> (), options: { Prefix: string?, Cost: number? })
		options = options or {}
		local prefix = options.Prefix or "batch"
		local cost = options.Cost or 6

		for index, item in ipairs(items) do
			Renderer.enqueue({
				Name = prefix .. "/" .. tostring(index),
				Cost = cost,
				Run = function()
					make(item, index)
				end,
			})
		end

		return prefix
	end

	function Renderer.cancel(name: string?): number
		if name == nil then
			local count = #queue
			table.clear(queue)
			stopLoop()
			return count
		end

		local removed = 0
		for index = #queue, 1, -1 do
			if queue[index].name == name then
				table.remove(queue, index)
				removed += 1
			end
		end

		if #queue == 0 then
			stopLoop()
		end
		return removed
	end

	function Renderer.pending(): number
		return #queue
	end

	function Renderer.isDraining(): boolean
		return draining
	end

	--- Drain one frame's worth of work. Called by RenderStepped; a spec (or a host that wants the
	--- page complete before it fades in) can call it directly.
	function Renderer.step(_delta: number?)
		if draining or #queue == 0 then
			return 0
		end

		draining = true
		local ran = 0
		local spent = 0

		while #queue > 0 and ran < budget.JobsPerFrame do
			local entry = queue[1]

			-- The queue is a priority order, so the head is not skipped over to find something that
			-- fits: a pass ends at the ceiling and the blocked job leads the next one. A job larger
			-- than a whole pass still runs on a fresh frame, because refusing it would stall the
			-- queue forever.
			if spent > 0 and entry.cost > budget.CostPerFrame - spent then
				break
			end

			table.remove(queue, 1)
			spent += entry.cost
			ran += 1

			local ok, err = pcall(entry.run)
			if entry.onDone ~= nil then
				local reportedOk, reportedErr = pcall(entry.onDone, ok, err)
				if not reportedOk then
					warn("[Flux] renderer: onDone threw: " .. tostring(reportedErr))
				end
			elseif not ok then
				warn("[Flux] renderer: job threw: " .. tostring(err))
			end
		end

		draining = false

		stats.passes += 1
		stats.ran += ran
		stats.lastPassJobs = ran
		stats.lastPassCost = spent
		stats.peakPassCost = math.max(stats.peakPassCost, spent)

		if #queue == 0 then
			stopLoop()
			Renderer.Idle:Dispatch(stats.ran)
		end

		return ran
	end

	--- Run everything now, ignoring the ceiling. Used when the window is opening and the alternative
	--- is a visible half-built page — and by tests that want the end state without pumping frames.
	function Renderer.flush(): number
		local total = 0
		local guard = 0
		while #queue > 0 do
			total += Renderer.step(0)
			guard += 1
			-- A job that re-enqueues itself would otherwise spin here forever; the queue is at worst
			-- one pass per item the library knows about, so this only trips on a caller bug.
			if guard > 100000 then
				warn("[Flux] renderer: flush did not converge; a job re-enqueues itself")
				break
			end
		end
		return total
	end

	function Renderer.stats(): {[string]: number}
		local out = {}
		for key, value in pairs(stats) do
			out[key] = value
		end
		out.queued = #queue
		return out
	end

	function Renderer.reset()
		table.clear(queue)
		stopLoop()
		for key in pairs(stats) do
			stats[key] = 0
		end
	end

	return Renderer
end

-- src/Systems/SearchManager.lua
FluxRegistry["Flux/Systems/SearchManager"] = function(require)
	--[[
		Systems/SearchManager — the index the search box queries.

		Rows register themselves when they are built and unregister when they are destroyed, so the
		index cannot drift away from what is on screen — a stale entry is the usual reason a search
		highlights something the user can then not click.

		Scoring is tiered rather than fuzzy-weighted: the order people expect out of a hub search is
		"exact name, then names starting with it, then anything containing it", and a scored edit
		distance reliably produces something else. Subsequence matching is kept at the bottom because
		it is what makes `hnds` find `Headless`, and it should never outrank a real prefix.

		Hiding is the caller's job: the manager says which entries matched, and the row decides whether
		that means Visible=false or being removed from its layout, because only the row knows.
	]]

	local Signal = require("Flux/Utilities/Signal")
	local String = require("Flux/Utilities/String")

	local SearchManager = {}

	--- Fired (term, matches) whenever the term changes. Tabs listen so a re-typed query re-slices the
	--- rows they own rather than leaving a filtered page showing everything.
	SearchManager.Changed = Signal.new()

	local entries = {}
	local order = {}
	local term = ""

	--- A row's searchable text is its label plus whatever the author adds: a description, the tab name,
	--- and the words a user might type instead ("esp" for "Chams").
	function SearchManager.register(entry: {
		Id: any,
		Label: string,
		Text: string?,
		Keywords: {string}?,
		Tab: string?,
		OnMatch: ((any, boolean) -> ())?,
	}): boolean
		if entry == nil or entry.Id == nil or type(entry.Label) ~= "string" then
			warn("[Flux] search: an entry needs an Id and a Label")
			return false
		end

		local haystack = string.lower(entry.Label)
		if type(entry.Text) == "string" then
			haystack = haystack .. " " .. string.lower(entry.Text)
		end
		if type(entry.Tab) == "string" then
			haystack = haystack .. " " .. string.lower(entry.Tab)
		end
		if type(entry.Keywords) == "table" then
			for _, keyword in ipairs(entry.Keywords) do
				haystack = haystack .. " " .. string.lower(tostring(keyword))
			end
		end

		if entries[entry.Id] ~= nil then
			-- Re-registering under a live term must re-apply the filter, or a renamed row would show
			-- while the search says it does not match.
			SearchManager.unregister(entry.Id)
		end

		entries[entry.Id] = {
			id = entry.Id,
			label = entry.Label,
			haystack = haystack,
			onMatch = entry.OnMatch,
			tab = entry.Tab,
			score = 0,
			matched = false,
		}
		table.insert(order, entry.Id)

		-- Registration position is the tie-break, recorded once instead of searched for on every
		-- comparison.
		entries[entry.Id].slot = #order

		if term ~= "" then
			SearchManager.apply()
		end

		return true
	end

	function SearchManager.unregister(id: any): boolean
		if entries[id] == nil then
			return false
		end
		entries[id] = nil
		for index = #order, 1, -1 do
			if order[index] == id then
				table.remove(order, index)
			end
		end
		return true
	end

	function SearchManager.clear()
		table.clear(entries)
		table.clear(order)
		-- The term goes with the index: a hub rebuilt after unload starts with nothing filtered, and a
		-- stale term would silently hide the rows the next window registers.
		term = ""
	end

	function SearchManager.size(): number
		return #order
	end

	--- Tiered score for one entry, 0 meaning no match.
	local function scoreFor(haystack: string, label: string, query: string): number
		if query == "" then
			return 1
		end

		if label == query then
			return 100
		end

		if String.startsWith(label, query) then
			return 80
		end

		-- A word boundary inside a multi-word label ("chams esp" matching "esp") is as good as a
		-- prefix on the whole label.
		if haystack:find("%f[%w]" .. String.escapePattern(query), 1, false) ~= nil then
			return 70
		end

		if haystack:find(String.escapePattern(query), 1, false) ~= nil then
			return 50
		end

		-- Subsequence, cheapest useful fallback: every character appears in order.
		local cursor = 1
		for index = 1, #query do
			local char = query:sub(index, index)
			local found = haystack:find(char, cursor, true)
			if found == nil then
				return 0
			end
			cursor = found + 1
		end

		return 20
	end

	--- Rank the index against `query` without touching state. Returns entries with score > 0.
	function SearchManager.rank(query: string?): {{entry: any, score: number}}
		local needle = string.lower(String.trim(query or term))
		local out = {}

		for _, id in ipairs(order) do
			local entry = entries[id]
			if entry ~= nil then
				local score = scoreFor(entry.haystack, string.lower(entry.label), needle)
				if score > 0 then
					table.insert(out, { entry = entry, score = score })
				end
			end
		end

		-- Best first, then registration order, so two equally good rows keep the order the author put
		-- them in instead of shuffling by table iteration.
		table.sort(out, function(a, b)
			if a.score ~= b.score then
				return a.score > b.score
			end
			return a.entry.slot < b.entry.slot
		end)

		return out
	end

	--- Apply the current term to every row and report what matched.
	function SearchManager.apply(): number
		local needle = string.lower(String.trim(term))
		local matched = 0

		for _, id in ipairs(order) do
			local entry = entries[id]
			if entry ~= nil then
				local score = needle == "" and 1 or scoreFor(entry.haystack, string.lower(entry.label), needle)
				local isMatch = score > 0
				entry.score = score
				entry.matched = isMatch

				if isMatch then
					matched += 1
				end

				if entry.onMatch ~= nil then
					local ok, err = pcall(entry.onMatch, entry, isMatch)
					if not ok then
						warn("[Flux] search: row callback threw: " .. tostring(err))
					end
				end
			end
		end

		return matched
	end

	--- The entry point a search box calls on every keystroke.
	function SearchManager.set(nextTerm: string?): number
		term = type(nextTerm) == "string" and nextTerm or ""
		local matched = SearchManager.apply()
		SearchManager.Changed:Dispatch(term, SearchManager.results())
		return matched
	end

	function SearchManager.term(): string
		return term
	end

	--- Matches for the live term, in rank order.
	function SearchManager.results(): {any}
		local out = SearchManager.rank(term)
		local entries_ = {}
		for _, hit in ipairs(out) do
			table.insert(entries_, hit.entry)
		end
		return entries_
	end

	function SearchManager.matched(): number
		local count = 0
		for _, id in ipairs(order) do
			local entry = entries[id]
			if entry ~= nil and entry.matched then
				count += 1
			end
		end
		return count
	end

	--- HTML-safe label with the matching run wrapped in the accent colour, for the row to render.
	function SearchManager.highlight(id: any, colorHex: string?): string?
		local entry = entries[id]
		if entry == nil then
			return nil
		end

		local needle = String.trim(term)
		if needle == "" then
			return String.escape(entry.label)
		end

		return String.highlight(String.escape(entry.label), needle, colorHex or "#FF4F68")
	end

	--- Was this row filtered out by the live term? Rows ask this when they are built mid-search, so a
	--- page sliced in later frames still respects the query.
	function SearchManager.passes(id: any): boolean
		if String.trim(term) == "" then
			return true
		end
		local entry = entries[id]
		return entry ~= nil and entry.matched == true
	end

	return SearchManager
end

-- src/Systems/ThemeManager.lua
FluxRegistry["Flux/Systems/ThemeManager"] = function(require)
	--[[
		Systems/ThemeManager — the live token table and the rebind list that makes a theme swap
		restyle the UI without rebuilding it.

		Components never store a Color3; they bind an instance property to a role name. A theme
		change walks the bindings and writes. That is what lets `Flux:SetTheme` repaint a menu
		that is already open, and it is why no component hardcodes a hex anywhere.
	]]

	local Signal = require("Flux/Utilities/Signal")
	local Guard = require("Flux/Utilities/Guard")
	local String = require("Flux/Utilities/String")
	local Theme = require("Flux/Assets/Theme")

	local ThemeManager = {}

	local current = {
		colors = {},
		metrics = {},
		fonts = {},
		name = Theme.defaultPreset,
	}

	local bindings = {}
	local callbacks = {}
	local validRoles = {}

	--- Values the host pinned on top of a preset, kept so a preset switch can re-apply them.
	--- Only spacing and fonts belong here: a colour preset owns its palette, so `SetTheme("Purple")`
	--- must be able to move the accent the host previously tuned. Assets/Theme builds every colour
	--- preset from Dark's metric table, so without this layer a colour change would silently undo
	--- `SetTheme{RadiusPanel=4}`.
	local pinned = {
		metrics = {},
		fonts = {},
	}

	for _, role in ipairs(Theme.colorRoles) do
		validRoles[role] = "color"
	end
	for _, role in ipairs(Theme.metricRoles) do
		validRoles[role] = "metric"
	end

	ThemeManager.Changed = Signal.new()
	ThemeManager.presets = Theme.presets

	local function cloneInto(target: {[string]: any}, source: {[string]: any})
		for key, value in pairs(source) do
			target[key] = value
		end
	end

	local function loadPreset(name: string): boolean
		local preset = Theme.presets[name]
		if preset == nil then
			return false
		end

		table.clear(current.colors)
		table.clear(current.metrics)
		table.clear(current.fonts)
		cloneInto(current.colors, preset.colors)
		cloneInto(current.metrics, preset.metrics)
		cloneInto(current.fonts, preset.fonts)

		-- The host's spacing and fonts win over the preset's; its colours do not, because the palette
		-- is exactly what a preset is for.
		cloneInto(current.metrics, pinned.metrics)
		cloneInto(current.fonts, pinned.fonts)

		current.name = name
		return true
	end

	--- Bind an instance property to a colour/metric role. Returns an unbind function, which
	--- every component hands to its Maid so a destroyed row cannot linger in the list.
	function ThemeManager.bind(instance: any, property: string, role: string): () -> ()
		if validRoles[role] == nil then
			warn(("[Flux] theme: unknown role '%s' (check Theme.colorRoles / Theme.metricRoles)"):format(tostring(role)))
			return function() end
		end

		local entry = { instance = instance, property = property, role = role }
		table.insert(bindings, entry)

		-- Paint immediately as well as registering: a component binds while it is being built, and
		-- without this the widget shows the engine default until the next theme change repaints it.
		local kind = validRoles[role]
		local value = nil
		if kind == "color" then
			value = current.colors[role]
		else
			value = current.metrics[role]
		end

		if value ~= nil then
			Guard.set(instance, property, value)
		end

		return function()
			for index = #bindings, 1, -1 do
				if bindings[index] == entry then
					table.remove(bindings, index)
					break
				end
			end
		end
	end

	--- For anything a single property write cannot express: gradients, stroke colour paired
	--- with transparency, a size that depends on two roles.
	---
	--- `roles` is an optimisation hint, not a subscription filter that can silence the callback: a
	--- function bound to { "Accent" } still runs whenever Accent moves, and one bound to nothing runs
	--- on every repaint.
	function ThemeManager.bindFn(fn: (current: {[string]: any}) -> (), roles: {string}?): () -> ()
		local entry = { fn = fn, roles = roles, seen = nil }

		if roles ~= nil then
			entry.seen = {}
			for _, role in ipairs(roles) do
				entry.seen[role] = ThemeManager.valueOf(role)
			end
		end

		table.insert(callbacks, entry)
		fn(current)

		return function()
			for index = #callbacks, 1, -1 do
				if callbacks[index] == entry then
					table.remove(callbacks, index)
					break
				end
			end
		end
	end

	function ThemeManager.valueOf(role: string): any
		if validRoles[role] == "color" then
			return current.colors[role]
		end
		if validRoles[role] == "metric" then
			return current.metrics[role]
		end
		return current.fonts[role]
	end

	--- Write every binding now. Instances whose parent is gone are dropped instead of
	--- accumulating, which is how a theme swap stays O(alive UI) rather than O(everything built).
	local function repaint()
		local index = 1
		while index <= #bindings do
			local entry = bindings[index]
			local instance = entry.instance

			local alive = false
			if instance ~= nil then
				local ok, parent = pcall(function()
					return instance.Parent
				end)
				alive = ok and parent ~= nil
			end

			if not alive then
				table.remove(bindings, index)
			else
				local role = entry.role
				local kind = validRoles[role]
				local value = nil
				if kind == "color" then
					value = current.colors[role]
				else
					value = current.metrics[role]
				end

				if value ~= nil then
					if not Guard.set(instance, entry.property, value) then
						table.remove(bindings, index)
					else
						index += 1
					end
				else
					index += 1
				end
			end
		end

		for _, entry in ipairs(callbacks) do
			local run = entry.roles == nil
			if not run then
				-- A role list means "only wake me when one of these moves", which is why the previous
				-- values are remembered: without it, a hovered row re-paints on every unrelated token.
				for _, role in ipairs(entry.roles) do
					local now = ThemeManager.valueOf(role)
					if now ~= nil and entry.seen[role] ~= now then
						run = true
						entry.seen[role] = now
					end
				end
			end

			if run then
				entry.fn(current)
			end
		end

		ThemeManager.Changed:Dispatch(current)
	end

	--- `Flux:SetTheme({ Accent = Color3.fromRGB(...) })` — overrides on top of the live table.
	---
	--- Values are normalised rather than type-tested with `type()`: a Color3 is userdata, so
	--- `type(value) == "Color3"` is never true on the engine. A theme payload can arrive from a
	--- config file, where colours are hex strings or number triples, so all three are accepted.
	function ThemeManager.coerceColor(value: any): Color3?
		if typeof(value) == "Color3" then
			return value
		end

		if type(value) == "string" then
			return String.hexToColor(value)
		end

		if type(value) == "table" then
			if type(value.R) == "number" then
				return Color3.fromRGB(math.floor(value.R * 255 + 0.5), math.floor(value.G * 255 + 0.5), math.floor(value.B * 255 + 0.5))
			end
			if type(value[1]) == "number" then
				return Color3.fromRGB(value[1], value[2] or 0, value[3] or 0)
			end
		end

		return nil
	end

	function ThemeManager.coerceFont(value: any): Enum.Font?
		if typeof(value) == "EnumItem" then
			return value :: any
		end

		local name = nil
		if type(value) == "table" and type(value.Name) == "string" then
			name = value.Name
		elseif type(value) == "string" then
			name = value
		end

		if name == nil then
			return nil
		end

		-- Enum.Font has no member for a name this client's font list does not carry, and indexing a
		-- missing one raises; Guard.get returns nil instead, which is what font() then floors to Gotham.
		local found = Guard.get(Enum.Font, name)
		if found == nil then
			return nil
		end
		return found :: any
	end

	function ThemeManager.set(overrides: {[string]: any})
		for key, value in pairs(overrides) do
			local color = ThemeManager.coerceColor(value)
			if color ~= nil then
				current.colors[key] = color
			elseif type(value) == "number" then
				current.metrics[key] = value
				pinned.metrics[key] = value
			elseif key == "colors" and type(value) == "table" then
				-- A restored palette arrives as hex strings and 0-255 triples, not live Color3s, so
				-- the group is coerced entry by entry: cloning it raw would leave a table sitting
				-- where every component expects a Color3.
				local missed = false
				for role, stored in pairs(value) do
					local coerced = ThemeManager.coerceColor(stored)
					if coerced ~= nil then
						current.colors[tostring(role)] = coerced
					else
						missed = true
					end
				end
				if missed then
					warn("[Flux] theme: some entries in the colors group were not colours")
				end
			elseif key == "metrics" and type(value) == "table" then
				for role, number in pairs(value) do
					if type(number) == "number" then
						current.metrics[tostring(role)] = number
						pinned.metrics[tostring(role)] = number
					else
						warn(("[Flux] theme: metric '%s' is not a number"):format(tostring(role)))
					end
				end
			elseif key == "fonts" and type(value) == "table" then
				for role, font in pairs(value) do
					local coerced = ThemeManager.coerceFont(font)
					if coerced ~= nil then
						current.fonts[role] = coerced
						pinned.fonts[role] = coerced
					end
				end
			else
				local font = ThemeManager.coerceFont(value)
				if font ~= nil then
					current.fonts[key] = font
					pinned.fonts[key] = font
				else
					warn(("[Flux] theme: '%s' is not a colour, a number, a font, or one of colors/metrics/fonts"):format(tostring(key)))
				end
			end
		end

		repaint()
		return current
	end

	--- Switch wholesale to a named preset. Unknown names are a caller error, not a silent no-op.
	function ThemeManager.use(presetName: string): boolean
		if not loadPreset(presetName) then
			warn("[Flux] theme: no preset named " .. tostring(presetName))
			return false
		end
		repaint()
		return true
	end

	function ThemeManager.name(): string
		return current.name
	end

	function ThemeManager.color(role: string): Color3
		return current.colors[role]
	end

	function ThemeManager.metric(role: string): number
		return current.metrics[role]
	end

	function ThemeManager.font(role: string): Enum.Font
		local font = current.fonts[role]
		if font == nil then
			return Enum.Font.Gotham
		end

		-- A font enum member can be absent on an older client; Gotham is the floor.
		if not Guard.has(Enum.Font, font.Name) then
			return Enum.Font.Gotham
		end
		return font
	end

	function ThemeManager.snapshot(): {[string]: any}
		return {
			name = current.name,
			colors = ThemeManager.exportColors(),
			metrics = ThemeManager.exportMetrics(),
			fonts = ThemeManager.exportFonts(),
		}
	end

	--- Colours leave as 0-255 triples, not the engine's 0-1 floats, because that is the shape a
	--- person writes by hand in a config file and the shape restore() and coerceColor() expect.
	--- Feeding Color3.R straight into Color3.fromRGB is how a theme round-trips to black.
	function ThemeManager.exportColors(): {[string]: {number}}
		local out = {}
		for role, color in pairs(current.colors) do
			local r, g, b = Guard.get(color, "R"), Guard.get(color, "G"), Guard.get(color, "B")
			if r ~= nil then
				out[role] = {
					math.floor(r * 255 + 0.5),
					math.floor((g or 0) * 255 + 0.5),
					math.floor((b or 0) * 255 + 0.5),
				}
			end
		end
		return out
	end

	function ThemeManager.exportMetrics(): {[string]: number}
		local out = {}
		for role, value in pairs(current.metrics) do
			out[role] = value
		end
		return out
	end

	function ThemeManager.exportFonts(): {[string]: string}
		local out = {}
		for role, font in pairs(current.fonts) do
			local name = Guard.get(font, "Name")
			if type(name) == "string" then
				out[role] = name
			end
		end
		return out
	end

	--- Restores a snapshot taken by exportColors/exportMetrics; used by the config system.
	function ThemeManager.restore(snapshot: {[string]: any})
		if snapshot == nil then
			return false
		end

		-- A snapshot is the whole look, so the pins it was taken alongside are dropped first:
		-- otherwise a value the file no longer carries would survive the restore and re-appear on
		-- the next preset switch.
		ThemeManager.forgetOverrides()

		if type(snapshot.name) == "string" then
			loadPreset(snapshot.name)
		end

		-- Routed through set(), which coerces hex strings and 0-255 triples, validates the metric
		-- group, and pins spacing and fonts the way an in-session SetTheme call does.
		local payload: {[string]: any} = {}
		if type(snapshot.colors) == "table" then
			payload.colors = snapshot.colors
		end
		if type(snapshot.metrics) == "table" then
			payload.metrics = snapshot.metrics
		end
		if type(snapshot.fonts) == "table" then
			payload.fonts = snapshot.fonts
		end

		if next(payload) ~= nil then
			ThemeManager.set(payload)
		end

		repaint()
		return true
	end

	--- Forgets the spacing and fonts the host pinned over its presets.
	function ThemeManager.forgetOverrides()
		table.clear(pinned.metrics)
		table.clear(pinned.fonts)
	end

	function ThemeManager.bindingCount(): number
		return #bindings
	end

	loadPreset(Theme.defaultPreset)

	return ThemeManager
end

-- src/Systems/TooltipManager.lua
FluxRegistry["Flux/Systems/TooltipManager"] = function(require)
	--[[
		Systems/TooltipManager — one hover surface for the whole UI.

		A tooltip per widget is the obvious design and the wrong one: a page with forty rows would
		carry forty frames and forty MouseEnter connections, and they would all still be there when
		the tab is swapped. This keeps a single instance, moves it, and changes its text.

		Two behaviours that are easy to get wrong and are the reason a tooltip feels broken rather
		than absent:

		  * It appears after a delay and disappears immediately. Appealing instantly makes the surface
		    flash across the screen while the pointer crosses a list; lingering after the pointer
		    leaves makes it outlive the thing it described.
		  * It is positioned against the pointer, not the widget, and clamped to the viewport — a
		    tooltip whose right edge is off-screen is unreadable, and on a phone the whole surface is
		    near an edge.
	]]

	local Instance = require("Flux/Utilities/Instance")
	local Guard = require("Flux/Utilities/Guard")
	local Maid = require("Flux/Utilities/Maid")
	local ThemeManager = require("Flux/Systems/ThemeManager")
	local LayoutManager = require("Flux/Systems/LayoutManager")
	local Element = require("Flux/Core/Element")
	local String = require("Flux/Utilities/String")

	local Players = Guard.service("Players")

	local TooltipManager = {}

	local settings = {
		Delay = 0.35,
		Offset = 12,
		MaxWidth = 240,
	}

	local owner: Maid? = nil
	local host: any = nil
	local label: any = nil
	local timer: thread? = nil
	local shown = false
	local attached = 0

	--- Attach a tooltip to an instance. Returns an unbind function, which every component hands to
	--- its maid — the count below is what proves a destroyed row released its tooltip.
	function TooltipManager.attach(instance: any, text: string, options: { Delay: number?, MaxWidth: number? })
		if instance == nil or type(text) ~= "string" or text == "" then
			return function() end
		end

		options = options or {}
		local maid = Maid.new()
		attached += 1

		local enter = Guard.get(instance, "MouseEnter")
		local leave = Guard.get(instance, "MouseLeave")

		if enter ~= nil then
			maid:giveConnection(enter:Connect(function()
				TooltipManager.request(text, options.Delay or settings.Delay)
			end))
		end

		if leave ~= nil then
			maid:giveConnection(leave:Connect(function()
				TooltipManager.hide()
			end))
		end

		-- A row can be destroyed while hovered; without this the surface stays on screen with nobody
		-- left to move it.
		local destroyed = Guard.get(instance, "Destroyed")
		if destroyed ~= nil then
			maid:giveConnection(destroyed:Connect(function()
				TooltipManager.hide()
			end))
		end

		local unbound = false
		return function()
			if unbound then
				return
			end
			unbound = true
			attached -= 1
			maid:cleanup()
			TooltipManager.hide()
		end
	end

	function TooltipManager.attached(): number
		return attached
	end

	function TooltipManager.configure(options: { Delay: number?, Offset: number?, MaxWidth: number? })
		options = options or {}
		if type(options.Delay) == "number" then
			settings.Delay = math.max(0, options.Delay)
		end
		if type(options.Offset) == "number" then
			settings.Offset = options.Offset
		end
		if type(options.MaxWidth) == "number" then
			settings.MaxWidth = options.MaxWidth
		end
		return settings
	end

	local function ensureHost()
		if host ~= nil then
			return
		end

		owner = Maid.new()
		local root = Element.root(owner, { Name = "FluxHub/Tooltips", Order = 1003 })

		host = Instance.new("Frame", root, {
			Name = "Tooltip",
			BackgroundColor3 = ThemeManager.color("PanelSecondary"),
			BorderSizePixel = 0,
			Size = UDim2.fromOffset(0, 0),
			AutomaticSize = Enum.AutomaticSize.XY,
			Visible = false,
			ZIndex = 10,
		})

		Instance.corner(host, UDim.new(0, ThemeManager.metric("RadiusField") or 8))
		Instance.pad(host, {
			Top = UDim.new(0, 6),
			Bottom = UDim.new(0, 6),
			Left = UDim.new(0, 8),
			Right = UDim.new(0, 8),
		})

		label = Element.label(owner, host, "Text", {
			Text = "",
			Role = "TextSecondary",
			TextSize = 12,
			Size = UDim2.fromScale(0, 1),
		})
		label.AutomaticSize = Enum.AutomaticSize.XY
		label.TextWrapped = false

		owner:give(ThemeManager.bind(host, "BackgroundColor3", "PanelSecondary"))
		owner:giveFunction(function()
			if host ~= nil then
				host:Destroy()
			end
			host = nil
			label = nil
		end)
	end

	local function mousePosition(): (number, number)
		if Players == nil then
			return 0, 0
		end
		local player = Players.LocalPlayer
		if player == nil then
			return 0, 0
		end
		local ok, mouse = pcall(function()
			return player:GetMouse()
		end)
		if not ok or mouse == nil then
			return 0, 0
		end
		return Guard.get(mouse, "X") or 0, Guard.get(mouse, "Y") or 0
	end

	--- Place the surface beside the pointer, flipping sides and clamping so it stays readable.
	function TooltipManager.place()
		local x, y = mousePosition()
		local viewport = LayoutManager.viewport()
		-- AutomaticSize has not resolved for the frame we just changed the text of, so the width is
		-- read after a frame rather than guessed here.
		local size = Guard.get(host, "AbsoluteSize") or Vector2.new(0, 0)
		local width = size.X
		local height = size.Y

		local left = x + settings.Offset
		local top = y + settings.Offset

		if left + width > viewport.X - 8 then
			left = x - width - settings.Offset
		end
		if top + height > viewport.Y - 8 then
			top = math.max(8, viewport.Y - height - 8)
		end
		left = math.max(8, left)
		top = math.max(8, top)

		host.Position = UDim2.fromOffset(left, top)
	end

	--- Ask for the surface to appear after `delay` seconds of continued hover.
	function TooltipManager.request(text: string, delay: number?)
		ensureHost()

		if timer ~= nil then
			task.cancel(timer)
		end

		local wait = delay or settings.Delay
		label.Text = String.escape(text)

		if wait <= 0 then
			TooltipManager.show()
			return
		end

		timer = task.delay(wait, function()
			timer = nil
			TooltipManager.show()
		end)
	end

	function TooltipManager.show()
		if host == nil then
			return
		end
		host.Visible = true
		shown = true
		TooltipManager.place()
	end

	function TooltipManager.hide()
		if timer ~= nil then
			task.cancel(timer)
			timer = nil
		end
		if host ~= nil then
			host.Visible = false
		end
		shown = false
	end

	function TooltipManager.isShown(): boolean
		return shown
	end

	--- Follow the pointer while open. Called by the hub's frame loop; a tooltip that does not move
	--- after a scroll reads as a rendering bug.
	function TooltipManager.tick()
		if shown and host ~= nil and host.Visible then
			TooltipManager.place()
		end
	end

	function TooltipManager.destroy()
		TooltipManager.hide()
		if owner ~= nil then
			owner:cleanup()
			owner = nil
		end
		host = nil
		label = nil
		shown = false
		attached = 0
	end

	return TooltipManager
end

-- src/Utilities/Base64.lua
FluxRegistry["Flux/Utilities/Base64"] = function(require)
	--[[
		Base64 — decode for the embedded icon atlas.

		Roblox exposes no base64 helper, so the atlas bytes are decoded here with bit32, which
		is part of the engine rather than an executor addition.
	]]

	local ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

	local lookup = {}
	for index = 1, 64 do
		lookup[string.byte(ALPHABET, index)] = index - 1
	end

	local Base64 = {}

	--- Returns the raw byte string. Padding and whitespace are ignored; an unknown byte stops
	--- the decode at that point rather than producing garbage.
	function Base64.decode(encoded: string): string?
		local length = #encoded
		local out = table.create(length)
		local count = 0

		local buffer = 0
		local bits = 0

		for index = 1, length do
			local byte = string.byte(encoded, index)
			if byte == 61 then -- '='
				break
			end

			local value = lookup[byte]
			if value == nil then
				if byte == 10 or byte == 13 or byte == 32 or byte == 9 then
					continue
				end
				return nil
			end

			buffer = bit32.lshift(buffer, 6) + value
			bits += 6

			if bits >= 8 then
				bits -= 8
				count += 1
				out[count] = string.char(bit32.band(bit32.rshift(buffer, bits), 0xFF))
				buffer = bit32.band(buffer, bit32.lshift(1, bits) - 1)
			end
		end

		return table.concat(out, "", 1, count)
	end

	--- Encode is needed only by the config export path, which writes a portable text blob.
	local function slotAt(triplet: number, shift: number): string
		local slot = bit32.rshift(triplet, shift) % 64 + 1
		return string.sub(ALPHABET, slot, slot)
	end

	function Base64.encode(raw: string): string
		local out = {}
		local length = #raw

		local index = 1
		while index <= length do
			local a = string.byte(raw, index)

			local b: number? = nil
			if index + 1 <= length then
				b = string.byte(raw, index + 1)
			end

			local c: number? = nil
			if index + 2 <= length then
				c = string.byte(raw, index + 2)
			end

			local triplet = bit32.lshift(a, 16) + bit32.lshift(b or 0, 8) + (c or 0)

			out[#out + 1] = slotAt(triplet, 18)
			out[#out + 1] = slotAt(triplet, 12)
			if b ~= nil then
				out[#out + 1] = slotAt(triplet, 6)
			else
				out[#out + 1] = "="
			end
			if c ~= nil then
				out[#out + 1] = slotAt(triplet, 0)
			else
				out[#out + 1] = "="
			end

			index += 3
		end

		return table.concat(out)
	end

	return Base64
end

-- src/Utilities/Guard.lua
FluxRegistry["Flux/Utilities/Guard"] = function(require)
	--[[
		Guard — the single place optional engine members are touched.

		The clients this library targets are older than the engine: `ScreenGui.ResetOnDestroyed`,
		`DisplayOrderOnTop`, `CanvasGroup`, `GroupTransparency`, `TextLabel.LetterSpacing` and
		`Frame.AbsoluteCenter` all raise instead of being absent. An unguarded write on the boot
		path aborts the whole library, so nothing outside this module assigns a recent member
		directly, and every cosmetic-only construction block goes through `Guard.try`.
	]]

	local Guard = {}

	local warned = {}

	--- Assign a property that may not exist on this client. Returns whether it took.
	function Guard.set(instance: any, property: string, value: any): boolean
		if instance == nil then
			return false
		end

		local ok = pcall(function()
			instance[property] = value
		end)

		if not ok and not warned[property] then
			warned[property] = true
		end

		return ok
	end

	--- Read a property that may not exist. Returns nil instead of raising.
	function Guard.get(instance: any, property: string): any
		if instance == nil then
			return nil
		end

		local ok, value = pcall(function()
			return instance[property]
		end)

		if ok then
			return value
		end
		return nil
	end

	--- Does this client actually have the member? Used to pick a code path, never to skip work silently.
	function Guard.has(instance: any, property: string): boolean
		return Guard.get(instance, property) ~= nil
	end

	--- Run a cosmetic construction step; a failure degrades to "not shown" instead of aborting.
	function Guard.try(fn: () -> ...any): (boolean, ...any)
		local ok, first, rest = pcall(fn)
		if ok then
			return true, first, rest
		end
		return false, first
	end

	--- Drawn centre of an instance. `AbsoluteCenter` raises on this client, so derive it.
	function Guard.absoluteCenter(instance: any): Vector2
		local position = instance.AbsolutePosition
		local size = instance.AbsoluteSize
		return Vector2.new(position.X + size.X * 0.5, position.Y + size.Y * 0.5)
	end

	--- Global service lookup that tolerates a service missing from an older client.
	function Guard.service(className: string): any
		local ok, found = pcall(function()
			return game:GetService(className)
		end)
		if ok then
			return found
		end
		return nil
	end

	function Guard.wasWarned(property: string): boolean
		return warned[property] == true
	end

	return Guard
end

-- src/Utilities/Instance.lua
FluxRegistry["Flux/Utilities/Instance"] = function(require)
	--[[
		Instance — element factory.

		Every GUI object in the library is built through this module so that:
		  * optional properties route through Guard instead of raising;
		  * layout helpers (corner/stroke/pad/list) are applied in one call;
		  * a rounded panel actually clips its children, which is what makes the corner visible;
		  * the harness can count objects, because the execute-time instance budget decides
		    whether a large menu freezes a low-end device.
	]]

	-- Captured before the module table below shadows the global class name.
	local RBXInstance = Instance

	local Guard = require("Flux/Utilities/Guard")

	local TweenService = Guard.service("TweenService")
	local Instance = {}

	local created = 0

	--- Properties that only exist on recent engines; assigned through pcall.
	local OPTIONAL_PROPERTIES = {
		DisplayOrderOnTop = true,
		ResetOnDestroyed = true,
		LetterSpacing = true,
		GroupTransparency = true,
		AutoLocalize = true,
		SelectionImageObject = true,
		BorderMode = true,
		TextTruncated = true,
		-- CaretColor and CursorPosition are textbox members that older executors do not carry;
		-- writing them unguarded aborts the widget build over a cosmetic detail.
		CaretColor = true,
		CaretTransparency = true,
		CursorPosition = true,
		CanvasPosition = true,
	}

	local function applyProperty(instance: any, key: string, value: any)
		if OPTIONAL_PROPERTIES[key] then
			Guard.set(instance, key, value)
		else
			instance[key] = value
		end
	end

	--- Create, then apply a property table, then parent. Parenting last means the object is
	--- fully configured before the engine lays it out, which avoids a visible reflow frame.
	function Instance.new(className: string, parent: any?, properties: {[string]: any}?)
		local instance = RBXInstance.new(className)
		created += 1

		if properties ~= nil then
			for key, value in pairs(properties) do
				applyProperty(instance, key, value)
			end
		end

		if parent ~= nil then
			instance.Parent = parent
		end

		return instance
	end

	function Instance.count(): number
		return created
	end

	function Instance.resetCount()
		created = 0
	end

	local function helper(className: string, parent: any, properties: {[string]: any})
		return Instance.new(className, parent, properties)
	end

	function Instance.corner(parent: any, radius: UDim)
		return helper("UICorner", parent, { CornerRadius = radius })
	end

	function Instance.stroke(parent: any, color: Color3, thickness: number, transparency: number?)
		return helper("UIStroke", parent, {
			Color = color,
			Thickness = thickness,
			Transparency = transparency or 0,
			ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		})
	end

	function Instance.pad(parent: any, spec: { Top: UDim?, Bottom: UDim?, Left: UDim?, Right: UDim? })
		return helper("UIPadding", parent, {
			PaddingTop = spec.Top or UDim.new(0, 0),
			PaddingBottom = spec.Bottom or UDim.new(0, 0),
			PaddingLeft = spec.Left or UDim.new(0, 0),
			PaddingRight = spec.Right or UDim.new(0, 0),
		})
	end

	function Instance.list(parent: any, spec: {
		FillDirection: Enum.FillDirection?,
		SortOrder: Enum.SortOrder?,
		Padding: UDim?,
		Wrap: boolean?,
		VerticalAlignment: Enum.VerticalAlignment?,
		HorizontalAlignment: Enum.HorizontalAlignment?,
	})
		return helper("UIListLayout", parent, {
			FillDirection = spec.FillDirection or Enum.FillDirection.Vertical,
			SortOrder = spec.SortOrder or Enum.SortOrder.LayoutOrder,
			Padding = spec.Padding or UDim.new(0, 0),
			Wrap = spec.Wrap == true,
			VerticalAlignment = spec.VerticalAlignment or Enum.VerticalAlignment.Top,
			HorizontalAlignment = spec.HorizontalAlignment or Enum.HorizontalAlignment.Left,
		})
	end

	function Instance.grid(parent: any, spec: { CellSize: UDim?, Padding: UDim?, FillDirection: Enum.FillDirection? })
		return helper("UIGridLayout", parent, {
			CellSize = spec.CellSize or UDim.new(0, 100),
			CellPadding = spec.Padding or UDim.new(0, 8),
			SortOrder = Enum.SortOrder.LayoutOrder,
			FillDirection = spec.FillDirection or Enum.FillDirection.Horizontal,
		})
	end

	--- A rounded, clipped container. `ClipsDescendants` is applied here rather than at every
	--- call site: without it a child painted to the edge covers the rounded corner.
	function Instance.panel(parent: any, name: string, properties: {[string]: any}?)
		local spec = {}
		for key, value in pairs(properties or {}) do
			spec[key] = value
		end

		spec.Name = name
		if spec.BackgroundColor3 == nil then
			spec.BackgroundColor3 = Color3.fromRGB(24, 24, 30)
		end
		spec.BorderSizePixel = 0

		local radius = spec.CornerRadius or UDim.new(0, 8)
		spec.CornerRadius = nil

		local frame = Instance.new("Frame", parent, spec)
		frame.ClipsDescendants = true
		Instance.corner(frame, radius)
		return frame
	end

	--- Remove content children but keep the layout helpers already parented to this container.
	function Instance.clear(parent: any)
		for _, child in ipairs(parent:GetChildren()) do
			if not child:IsA("UIComponent") then
				child:Destroy()
			end
		end
	end

	function Instance.tween(instance: any, info: TweenInfo, goals: {[string]: any})
		if TweenService == nil then
			return nil
		end

		local ok, track = pcall(function()
			return TweenService:Create(instance, info, goals)
		end)

		if ok then
			return track
		end
		return nil
	end

	return Instance
end

-- src/Utilities/Maid.lua
FluxRegistry["Flux/Utilities/Maid"] = function(require)
	--[[
		Maid — ownership list for everything a component must release.

		`Flux:Unload()` walks the maid tree, so a component that forgot to register a
		connection is the only way a leak can happen. Tasks are accepted in every shape the
		library produces: RBXScriptConnection, Signal connection, Instance, thread, function.
	]]

	type Maid = {
		giveTask: (Maid, any) -> any,
		giveFunction: (Maid, () -> ()) -> (),
		giveConnection: (Maid, any) -> any,
		giveInstance: (Maid, any) -> any,
		giveThread: (Maid, thread) -> any,
		chain: (Maid, Maid) -> Maid,
		cleanup: (Maid) -> (),
		Destroy: (Maid) -> (),
	}

	local Maid = {}
	Maid.__index = Maid

	function Maid.new(): Maid
		return setmetatable({ _tasks = {} }, Maid) :: any
	end

	function Maid.giveTask(self: Maid, item: any): any
		if item == nil then
			return nil
		end

		table.insert(self._tasks, item)
		return item
	end

	function Maid.giveFunction(self: Maid, fn: () -> ())
		return Maid.giveTask(self, { type = "function", fn = fn })
	end

	function Maid.giveConnection(self: Maid, connection: any)
		return Maid.giveTask(self, { type = "connection", instance = connection })
	end

	function Maid.giveInstance(self: Maid, instance: any)
		return Maid.giveTask(self, { type = "instance", instance = instance })
	end

	function Maid.giveThread(self: Maid, thread: thread)
		return Maid.giveTask(self, { type = "thread", instance = thread })
	end

	--- The short name component code uses; giveTask is the same thing under its explicit name.
	Maid.give = Maid.giveTask

	--- A child maid that is cleaned up with this one but can be cleaned up early on its own.
	function Maid.chain(self: Maid, child: Maid): Maid
		Maid.giveTask(self, { type = "maid", instance = child })
		return child
	end

	-- The parameter is `item`, never `task`: a name collision with the global task library
	-- would break thread cancellation.
	local function runItem(item: any)
		if type(item) == "function" then
			local ok, err = pcall(item)
			if not ok then
				warn("[Flux] cleanup: " .. tostring(err))
			end
			return
		end

		if type(item) ~= "table" then
			return
		end

		local kind = item.type

		if kind == "maid" then
			item.instance:cleanup()
			return
		end

		if kind == "function" then
			local ok, err = pcall(item.fn)
			if not ok then
				warn("[Flux] cleanup: " .. tostring(err))
			end
			return
		end

		local instance = item.instance
		if instance == nil then
			return
		end

		if kind == "thread" then
			if coroutine.status(instance) ~= "dead" then
				task.cancel(instance)
			end
			return
		end

		-- Connections and Instances both expose Destroy.
		local ok, err = pcall(function()
			instance:Destroy()
		end)
		if not ok then
			warn("[Flux] cleanup (" .. typeof(instance) .. "): " .. tostring(err))
		end
	end

	function Maid.cleanup(self: Maid)
		local tasks = self._tasks
		self._tasks = {}

		for index = #tasks, 1, -1 do
			local ok, err = pcall(runItem, tasks[index])
			if not ok then
				warn("[Flux] cleanup: " .. tostring(err))
			end
		end
	end

	Maid.Destroy = Maid.cleanup

	return Maid
end

-- src/Utilities/Math.lua
FluxRegistry["Flux/Utilities/Math"] = function(require)
	--[[
		Math — numeric helpers shared by sliders, the colour picker, easing and layout fitting.
	]]

	local Math = {}

	function Math.clamp(value: number, minimum: number, maximum: number): number
		if value < minimum then
			return minimum
		end
		if value > maximum then
			return maximum
		end
		return value
	end

	function Math.lerp(a: number, b: number, alpha: number): number
		return a + (b - a) * alpha
	end

	--- Snap to a step, then to the decimal places the step implies. Used so a slider never
	--- reports 0.30000000000000004.
	function Math.snap(value: number, minimum: number, step: number, decimals: number?): number
		if step <= 0 then
			return value
		end

		local snapped = minimum + math.floor((value - minimum) / step + 0.5) * step
		local scale = 10 ^ (decimals or Math.decimalsForStep(step))
		-- A value below the minimum snaps to one step below it, never to itself, so the floor has
		-- to be applied after rounding. Callers clamp the ceiling, which snap cannot know.
		return math.max(math.floor(snapped * scale + 0.5) / scale, minimum)
	end

	--- How many decimal places a step size implies (0.1 -> 1, 0.25 -> 2, 5 -> 0).
	function Math.decimalsForStep(step: number): number
		for decimals = 0, 6 do
			local scale = 10 ^ decimals
			if math.abs(step * scale - math.floor(step * scale + 0.5)) < 1e-6 then
				return decimals
			end
		end
		return 6
	end

	function Math.round(value: number, decimals: number?): number
		local scale = 10 ^ (decimals or 0)
		return math.floor(value * scale + 0.5) / scale
	end

	function Math.mapRange(value: number, fromMin: number, fromMax: number, toMin: number, toMax: number): number
		if fromMax == fromMin then
			return toMin
		end
		return toMin + (toMax - toMin) * ((value - fromMin) / (fromMax - fromMin))
	end

	function Math.inverseLerp(value: number, a: number, b: number): number
		if b == a then
			return 0
		end
		return Math.clamp((value - a) / (b - a), 0, 1)
	end

	function Math.sign(value: number): number
		if value > 0 then
			return 1
		end
		if value < 0 then
			return -1
		end
		return 0
	end

	--- Shortest signed angular difference in degrees, for rotation tweens.
	function Math.deltaAngle(from: number, to: number): number
		local delta = (to - from) % 360
		if delta > 180 then
			delta -= 360
		end
		return delta
	end

	--- Largest scale no greater than 1 that keeps a window of `baseSize` inside `viewport`,
	--- floored at `minimum` so a tiny window stays legible rather than vanishing.
	function Math.fitScale(baseSize: Vector2, viewport: Vector2, minimum: number): number
		local byWidth = 1
		local byHeight = 1

		if baseSize.X > 0 then
			byWidth = viewport.X / baseSize.X
		end
		if baseSize.Y > 0 then
			byHeight = viewport.Y / baseSize.Y
		end

		return Math.clamp(math.min(byWidth, byHeight, 1), minimum, 1)
	end

	return Math
end

-- src/Utilities/Signal.lua
FluxRegistry["Flux/Utilities/Signal"] = function(require)
	--[[
		Signal — a minimal, allocation-light event.

		Used by every component for its public `Changed`/`Clicked` events and internally by
		the theme and lifecycle systems. Dispatch iterates a snapshot so a handler may
		connect or disconnect during the same dispatch without corrupting the loop.
	]]

	type Connection = {
		Disconnect: (Connection) -> (),
		Destroy: (Connection) -> (),
	}

	export type Signal = {
		Connect: (Signal, (...any) -> ()) -> Connection,
		Once: (Signal, (...any) -> ()) -> Connection,
		Dispatch: (Signal, ...any) -> (),
		Wait: (Signal) -> ...any,
		GetConnectionCount: (Signal) -> number,
		Destroy: (Signal) -> (),
	}

	local Signal = {}
	Signal.__index = Signal

	local function newConnection(fn: (...any) -> (), once: boolean, signal)
		local self: Connection
		local connected = true

		local function disconnect()
			if not connected then
				return
			end
			connected = false
			local list = signal._connections
			for index = #list, 1, -1 do
				if list[index] == self then
					table.remove(list, index)
					break
				end
			end
		end

		self = {
			_fn = fn,
			_once = once,
			_connected = function()
				return connected
			end,
			Disconnect = disconnect,
			-- Maid releases connections through Destroy, the same name an RBXScriptConnection
			-- answers with. Without it, a component torn down through its maid would keep firing.
			Destroy = disconnect,
		}

		table.insert(signal._connections, self)
		return self
	end

	function Signal.new(): Signal
		local self = setmetatable({ _connections = {} }, Signal) :: any
		return self
	end

	function Signal.Connect(self: Signal, fn: (...any) -> ()): Connection
		return newConnection(fn, false, self)
	end

	function Signal.Once(self: Signal, fn: (...any) -> ()): Connection
		return newConnection(fn, true, self)
	end

	function Signal.Dispatch(self: Signal, ...: any)
		local snapshot = {}
		local connections = self._connections
		for index = 1, #connections do
			snapshot[index] = connections[index]
		end

		for index = 1, #snapshot do
			local connection = snapshot[index]
			if connection._connected() then
				if connection._once then
					connection:Disconnect()
				end

				-- An RBXScriptSignal runs each handler protected, so one bad callback cannot stop
				-- the others. A theme repaint touches every bound widget at once: without this,
				-- one component with a nil reference would leave half the menu unstyled.
				local ok, err = pcall(connection._fn, ...)
				if not ok then
					warn("[Flux] signal handler: " .. tostring(err))
				end
			end
		end
	end

	function Signal.Wait(self: Signal): ...any
		local boundEvent = Instance.new("BindableEvent")
		local payload = nil
		local filled = false

		local connection = self:Connect(function(...)
			payload = table.pack(...)
			filled = true
			boundEvent:Fire()
		end)

		if not filled then
			boundEvent.Event:Wait()
		end

		connection:Disconnect()
		boundEvent:Destroy()

		if payload == nil then
			return nil
		end
		return table.unpack(payload, 1, payload.n)
	end

	function Signal.GetConnectionCount(self: Signal): number
		return #self._connections
	end

	function Signal.Destroy(self: Signal)
		local connections = self._connections
		for index = #connections, 1, -1 do
			connections[index]:Disconnect()
		end

		-- Emptied, not nilled: a widget that dispatches after teardown is a real race during a
		-- window close, and it must be a no-op rather than an error inside the handler loop.
		table.clear(connections)
	end

	return Signal
end

-- src/Utilities/String.lua
FluxRegistry["Flux/Utilities/String"] = function(require)
	--[[
		String — display formatting, rich-text escaping, and the hex/colour conversions the
		colour picker and config export both need.
	]]

	local String = {}

	function String.trim(value: string): string
		return (value:gsub("^%s+", ""):gsub("%s+$", ""))
	end

	function String.lower(value: string): string
		return value:lower()
	end

	function String.startsWith(value: string, prefix: string): boolean
		return value:sub(1, #prefix) == prefix
	end

	function String.endsWith(value: string, suffix: string): boolean
		if suffix == "" then
			return true
		end
		return value:sub(-#suffix) == suffix
	end

	--- Splits on a literal separator and keeps empty fields, so "a,,b" yields three parts and a
	--- config list with a blank entry round-trips instead of silently dropping it.
	function String.split(value: string, separator: string): {string}
		local out = {}

		if separator == "" then
			table.insert(out, value)
			return out
		end

		local pattern = String.escapePattern(separator)
		local cursor = 1

		while true do
			local startAt, endAt = string.find(value, pattern, cursor, false)

			if startAt == nil then
				table.insert(out, string.sub(value, cursor))
				break
			end

			table.insert(out, string.sub(value, cursor, startAt - 1))
			cursor = endAt + 1
		end

		return out
	end

	--- Escape the five characters RichText treats as markup. Every string this library hands
	--- to a RichText label goes through here first, so a config named `[100%] <b>fun</b>`
	--- cannot inject markup into the menu.
	function String.escape(value: string): string
		local result = tostring(value)
		result = result:gsub("&", "&amp;")
		result = result:gsub("<", "&lt;")
		result = result:gsub(">", "&gt;")
		result = result:gsub('"', "&quot;")
		result = result:gsub("'", "&apos;")
		return result
	end

	--- Escape Lua patterns so a user-typed search term is matched literally.
	function String.escapePattern(value: string): string
		return value:gsub("[%(%)%.%%%+%-%*%?%[%]%^%$]", "%%%1")
	end

	--- Wrap the occurrences of `query` inside already-escaped `value` in a colour tag.
	--- Returns the escaped text unchanged when the query does not match, so callers can show
	--- a plain row without a second branch.
	function String.highlight(escapedValue: string, query: string, colorHex: string): string
		if query == nil or query == "" then
			return escapedValue
		end

		local needle = query:lower()
		local haystack = escapedValue:lower()
		local out = {}
		local cursor = 1

		while true do
			local found = haystack:find(needle, cursor, true)
			if found == nil then
				table.insert(out, escapedValue:sub(cursor))
				break
			end

			table.insert(out, escapedValue:sub(cursor, found - 1))
			table.insert(
				out,
				"<font color=\"#" .. colorHex .. "\">" .. escapedValue:sub(found, found + #needle - 1) .. "</font>"
			)
			cursor = found + #needle
		end

		return table.concat(out)
	end

	function String.truncate(value: string, maximum: number, ellipsis: string?): string
		if #value <= maximum then
			return value
		end
		return value:sub(1, math.max(1, maximum - #(ellipsis or "..."))) .. (ellipsis or "...")
	end

	function String.padStart(value: string, width: number, char: string?): string
		local padChar = char or " "
		local out = value
		while #out < width do
			out = padChar .. out
		end
		return out
	end

	--- Colour3 -> "FF4F68".
	function String.colorToHex(color: Color3): string
		local function component(value: number): string
			local scaled = math.floor(math.clamp(value, 0, 1) * 255 + 0.5)
			return String.padStart(("%02X"):format(scaled), 2, "0")
		end
		return component(color.R) .. component(color.G) .. component(color.B)
	end

	--- "FF4F68", "#FF4F68" or "255,79,104" -> Color3. Returns nil rather than a wrong colour.
	function String.hexToColor(value: string): Color3?
		local text = String.trim(value):gsub("^#", "")

		local r, g, b = text:match("^(%x%x)(%x%x)(%x%x)$")
		if r ~= nil then
			return Color3.fromRGB(tonumber(r, 16), tonumber(g, 16), tonumber(b, 16))
		end

		if #text == 6 then
			return nil
		end

		r, g, b = text:match("^(%d+),%s*(%d+),%s*(%d+)$")
		if r ~= nil then
			return Color3.fromRGB(tonumber(r), tonumber(g), tonumber(b))
		end
		return nil
	end

	--- "LeftShift" -> "L-Shift", "MouseButton2" -> "MB2". Key labels are shown to players, so
	--- the engine names are rewritten rather than printed raw.
	local KEY_OVERRIDES = {
		Space = "Space",
		LeftControl = "L-Ctrl",
		RightControl = "R-Ctrl",
		LeftShift = "L-Shift",
		RightShift = "R-Shift",
		LeftAlt = "L-Alt",
		RightAlt = "R-Alt",
		MouseButton1 = "MB1",
		MouseButton2 = "MB2",
		MouseButton3 = "MB3",
	}

	function String.keyName(value: any): string
		if value == nil then
			return "None"
		end

		local name
		if typeof(value) == "EnumItem" then
			name = value.Name
		elseif type(value) == "table" and type(value.Name) == "string" then
			-- A keybind restored from a config file is a table, not a live EnumItem.
			name = value.Name
		else
			name = tostring(value)
		end

		local override = KEY_OVERRIDES[name]
		if override ~= nil then
			return override
		end

		name = name:gsub("^Left", "L-"):gsub("^Right", "R-"):gsub("^MouseButton", "MB")
		name = name:gsub("^Key", "")
		name = name:gsub("^Digit", "")
		return name
	end

	--- Strip characters a Roblox font cannot draw. Emoji render as hollow boxes, and universe
	--- names contain them, so any fetched name is filtered before it reaches a label.
	function String.stripUnsupported(value: string): string
		local out = tostring(value)
		out = out:gsub("[\240-\247][\128-\191][\128-\191][\128-\191]", "")
		out = out:gsub("\\u[Dd][89ABab]%x%x", "")
		out = out:gsub("[\128-\191]", "")
		out = out:gsub("%[%s*%]", "")
		return String.trim(out)
	end

	return String
end

-- src/Utilities/Table.lua
FluxRegistry["Flux/Utilities/Table"] = function(require)
	--[[
		Table — small functional helpers. Deliberately no generalized iteration here: the
		clients this library targets do not always accept `for k, v in tbl do`.
	]]

	local Table = {}

	function Table.size(source: {[any]: any}): number
		local count = 0
		for _ in pairs(source) do
			count += 1
		end
		return count
	end

	function Table.keys(source: {[any]: any}): {any}
		local out = {}
		for key in pairs(source) do
			table.insert(out, key)
		end
		return out
	end

	function Table.values(source: {[any]: any}): {any}
		local out = {}
		for _, value in pairs(source) do
			table.insert(out, value)
		end
		return out
	end

	function Table.copy(source: {[any]: any}): {[any]: any}
		local out = {}
		for key, value in pairs(source) do
			out[key] = value
		end
		return out
	end

	function Table.deepCopy(source: any): any
		if type(source) ~= "table" then
			return source
		end

		local out = {}
		for key, value in pairs(source) do
			out[key] = Table.deepCopy(value)
		end
		return out
	end

	--- Fields from `defaults` that the caller omitted. Nil-on-purpose is preserved because a
	--- component distinguishes "not supplied" from "supplied as false".
	function Table.withDefaults(source: {[any]: any}?, defaults: {[any]: any}): {[any]: any}
		local out = Table.copy(defaults)
		for key, value in pairs(source or {}) do
			out[key] = value
		end
		return out
	end

	function Table.merge(...: {[any]: any}): {[any]: any}
		local out = {}
		for _, source in ipairs({ ... }) do
			for key, value in pairs(source) do
				out[key] = value
			end
		end
		return out
	end

	function Table.includes(list: {any}, value: any): boolean
		for _, item in ipairs(list) do
			if item == value then
				return true
			end
		end
		return false
	end

	function Table.indexOf(list: {any}, predicate: (any) -> boolean): number?
		for index, item in ipairs(list) do
			if predicate(item) then
				return index
			end
		end
		return nil
	end

	function Table.find(list: {any}, predicate: (any) -> boolean): any?
		for _, item in ipairs(list) do
			if predicate(item) then
				return item
			end
		end
		return nil
	end

	function Table.filter(list: {any}, predicate: (any) -> boolean): {any}
		local out = {}
		for _, item in ipairs(list) do
			if predicate(item) then
				table.insert(out, item)
			end
		end
		return out
	end

	function Table.map(list: {any}, fn: (any, number) -> any): {any}
		local out = {}
		for index, item in ipairs(list) do
			out[index] = fn(item, index)
		end
		return out
	end

	--- Insert keeping ascending order by a numeric key, without re-sorting the whole list.
	function Table.insertSorted(list: {any}, item: any, compare: (any, any) -> boolean)
		local position = #list + 1
		for index = #list, 1, -1 do
			if compare(list[index], item) then
				position = index + 1
				break
			end
			position = index
		end
		table.insert(list, position, item)
	end

	function Table.reverse(list: {any}): {any}
		local out = {}
		for index = #list, 1, -1 do
			table.insert(out, list[index])
		end
		return out
	end

	return Table
end

-- src/init.lua
FluxRegistry["Flux/init"] = function(require)
	--[[
		init — the entry point of the bundle.

		tools/build.mjs finishes dist/FluxHub.lua by requiring this module, so whatever it returns
		is what a hub receives from

			local Flux = loadstring(game:HttpGet(url))()

		The version token below is replaced with the contents of VERSION at build time, so the
		published number cannot drift from the file that tags it.
	]]

	local Library = require("Flux/Core/Library")

	local Flux = Library.new()

	Flux.Version = "0.1.0"

	return Flux
end

return fluxRequire("Flux/init")
